export const META = {"stand":"2026-11-01","version":"1.0.0","arbeitsannahme":{"zeichen":"Westliche tropische, geozentrische Astrologie als Einstieg. Die zwölf Zeichen sind hier gleiche 30-Grad-Sektoren ab dem Frühlings-Äquinoktium, keine Sternbilder. Alle Zeiträume sind ungefähre Orientierung. Die Deutungen sind Traditionsmaterial und keine empirischen Persönlichkeitsaussagen.","faktoren":"Zehn zentrale Deutungsfaktoren der westlichen Astrologie: Sonne, Mond und die acht Körper Merkur bis Pluto. Astronomische Angaben sind Fakten, die zugeordneten Themen sind Deutungstradition. Die Erde ist kein astrologischer Faktor; Pluto wird trotz Zwergplanetenstatus mitgezählt.","haeuser":"Zwölf Häuser der westlichen Astrologie als Lebensfelder. Häuser hängen von Geburtszeit und Ort ab; die hier beschriebenen Zuordnungen sind Deutungstradition und keine Tatsachenbehauptungen über reale Personen. Die Hausspitzen verschieben sich je nach Häusersystem.","aspekte":"Fünf Hauptaspekte der westlichen Astrologie mit ihren Winkeldefinitionen. Orben sind Konventionen, keine Naturkonstanten; die Zuordnung zu harmonisch oder spannungsreich ist Deutungstradition.","grundlagen":"Grundlagen- und Vertiefungstexte für den Einstieg in die westliche tropische Astrologie. Die Texte trennen astronomische Fakten, historische Einordnung, Deutungstradition und empirische Evidenz. Sie sind Lehr- und Reflexionsmaterial, keine Diagnose- oder Prognosegrundlage.","beispiele":"Vier ausdrücklich fiktive Lehrbeispiele. Es handelt sich nicht um berechnete Horoskope, nicht um reale Personen und nicht um Gradangaben. Die gesetzten Zeichen- und Hausannahmen dienen nur dazu, das synthetische Lesen zu zeigen.","faq":"Häufige Fragen zur westlichen tropischen Astrologie, beantwortet mit klarer Trennung von Tradition, Astronomie und Evidenz. Die Antworten sind Bildungsmaterial, keine Beratung.","glossar":"Glossar der westlichen tropischen Astrologie mit kurzen, verständlichen Definitionen. Wo ein Begriff Tradition ist, wird er als solche erklärt; astronomische Begriffe sind als Fakten eingeordnet.","lernpfad":"Sechsstufiger Lernpfad für Erwachsene ohne Vorkenntnisse. Der Pfad ist so gebaut, dass jede Stufe eine kurze Orientierung, ein vertiefendes Vergleichsstück und eine konkrete Übung enthält. Er verlangt keine Geburtsdaten und keine Anmeldung.","quellen":"Westliche tropische, geozentrische Astrologie als didaktischer Einstieg. Deutungstradition, astronomischer Fakt, Konvention und empirische Evidenz werden getrennt gekennzeichnet. Alle Quellen wurden am 2026-11-01 tatsächlich abgerufen; der Abrufstatus ist je Eintrag vermerkt."},"counts":{"zeichen":12,"faktoren":10,"haeuser":12,"aspekte":5,"grundlagen":24,"beispiele":4,"faq":15,"glossar":65,"lernpfad":6,"quellen":25,"claims":28}};

export const LERNPFAD_INTRO = "Dieser Lernpfad führt in sechs Stufen durch die westliche tropische Astrologie. Stufe 1 klärt, was Astrologie ist und was sie nicht ist. Stufe 2 führt die zwölf Zeichen ein. Stufe 3 erklärt die zehn Faktoren und die fünf Hauptaspekte. Stufe 4 behandelt Häuser und Achsen. Stufe 5 zeigt, wie eine Radix als Synthese gelesen wird, und wo die Grenzen liegen. Stufe 6 ist ein Nachschlage- und Vertiefungsangebot. Jede Stufe hat eine kurze Orientierung, konkrete Leseschritte und zwei bis drei Verständnisfragen. Wer wenig Zeit hat, kann mit Stufe 1 und 2 beginnen und die späteren Stufen als Nachschlagewerk nutzen. Wer nur eine Frage hat, findet sie im FAQ oder im Glossar.";

export const ZEICHEN = [{"id":"zeichen-widder","slug":"widder","name":"Widder","short":"Der Widder eröffnet den tropischen Tierkreis am Frühlingspunkt. Traditionell steht das kardinale Feuerzeichen für Aufbruch, Initiative und die Erfahrung, sich mit eigener Kraft in die Welt zu setzen.","long":"Astronomische Orientierung: Die Sonne durchläuft den Widder-Sektor des tropischen Tierkreises ungefähr vom 21. März bis zum 19. April. Diese Grenzen sind Näherungen: Der genaue Zeitpunkt des Zeichenwechsels verschiebt sich von Jahr zu Jahr um Stunden bis zu einem Tag, und Publikationen runden unterschiedlich [S06][S19]. Der Sektor ist nicht mit dem Sternbild Widder identisch. Wegen der Präzession der Erdachse liegt der Frühlingspunkt heute im Bereich der Fische, während die tropischen Zeichen weiterhin am Äquinoktium beginnen [S06][S13].\n\nBildsprache: Der Widder ist das erste Tier des Tierkreises, ein Jungtier mit Hörnern, das vorwärts drängt. In der griechischen Überlieferung rettet der goldene Widder Phrixos und Helle; das Goldene Vlies wird später zum Ziel der Argonauten. Das Bild trägt weniger Herrschaft als Aufbruch: etwas in Bewegung setzen, ein Risiko eingehen, eine Richtung behaupten. Der traditionelle Herrscher ist Mars, der auch in der modernen Zuordnung bleibt. Das natürliche erste Haus verbindet das Zeichen mit Körper, Auftreten und der Frage, wie jemand die eigene Existenz behauptet [S12][S10].\n\nDeutung: Als kardinales Feuerzeichen wird der Widder mit Anfang, Impuls und Durchsetzung verbunden. Die Bewegung ist nach außen gerichtet, oft schnell, unmittelbar und wenig abwägend. Das kann als Entschlossenheit, Mut und Klarheit erlebt werden; es kann aber auch Reibung erzeugen, weil der eigene Antrieb vor der Wirkung auf andere kommt. Das Zeichen beschreibt keine Charaktereigenschaft im messbaren Sinn, sondern eine Deutungsfigur für die Art, wie ein Mensch mit Anfang, Wettbewerb und Widerstand umgeht [S07].\n\nDifferenzierung: Eine Widder-Sonne ist nur ein Faktor im Horoskop. Mond, Merkur, Venus, Mars, die Häuser und die Aspekte verändern das Bild erheblich. Wer den Widder nur als laut, aggressiv oder sportlich liest, verfehlt die Spannbreite: Es gibt zurückhaltende Widder-Menschen, deren Impuls sich im Denken, im Handwerk oder in der stillen Weigerung zeigt, sich bremsen zu lassen. Die Tradition neigt dazu, Zeichen mit kulturell codierten Geschlechterbildern aufzuladen; das ist eine historische Schicht, keine Naturtatsache.\n\nTypische Missdeutung: Widder wird oft mit Aggression gleichgesetzt. Näher an der Tradition ist die Beschreibung einer initiierenden Kraft, die auch scheu, ungeduldig oder ungeschickt sein kann. Aggression ist eine mögliche Ausdrucksform, nicht die Definition. Wer das Zeichen als Rechtfertigung für Rücksichtslosigkeit benutzt, verwechselt eine Deutungsfigur mit einer Freigabe.\n\nEntwicklungsfrage: Der Widder lernt, seinen Impuls zu bemerken, bevor er handelt, und zu prüfen, ob das Neue wirklich das Eigene ist oder nur der Reiz des Anfangs.","keywords":["Aufbruch","Initiative","Durchsetzung","Kardinalfeuer","Mars"],"sources":["S06","S07","S10","S12","S13","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-feuer","modalitaet-kardinal","faktor-mars","haus-1","zeichen-waage"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-feuer","modality":"modalitaet-kardinal","polarity":"yang","ruler_traditional":"faktor-mars","ruler_modern":"faktor-mars","date_range_tropical":{"from":"03-21","to":"04-19","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Widder","glyph":"♈","bildsprache":"Gehörnter Widder, Frühlingsauftakt, Goldenes Vlies, vorwärts gerichtete Bewegung."},"strengths":["Kann Anfangen, wo andere noch abwägen","Sagt Direktes klar und zeitnah","Bringt Mut auf, ein Risiko sichtbar zu tragen","Reagiert schnell und pragmatisch auf Widerstand","Setzt Impulse, die Gruppen in Bewegung bringen"],"tensions":["Verwechselt Tempo mit Richtung","Wird ungeduldig, wenn Ergebnisse auf sich warten lassen","Erzeugt durch Schroffheit Reibung, die nicht beabsichtigt war","Lässt Projekte nach dem Start liegen, wenn der Reiz vorbei ist","Nimmt Bremsen persönlich statt als Information"],"reflection_questions":["Wo beginne ich etwas, ohne das Ende mitzudenken?","Wann verwechsle ich Klarheit mit Rücksichtslosigkeit?","Was passiert, wenn ich einem Impuls drei Atemzüge Zeit lasse?"],"common_misreading":"Die verbreitete Gleichsetzung von Widder mit Aggression oder Führungsanspruch ist eine Verkürzung. Die Tradition beschreibt zuerst eine initiierende, nach vorn gerichtete Bewegung, die ebenso schüchtern, ungeschickt oder still sein kann.","natural_house":"haus-1","opposite":"zeichen-waage"},{"id":"zeichen-stier","slug":"stier","name":"Stier","short":"Der Stier ist das fixe Erdzeichen des Tropus. Traditionell verbindet er Stabilität, sinnliche Wahrnehmung und den Umgang mit Ressourcen, Besitz und Grenzen.","long":"Astronomische Orientierung: Der Stier-Sektor reicht ungefähr vom 20. April bis zum 20. Mai. Auch hier handelt es sich um eine gerundete Konvention; der tatsächliche Sonnenstand im Sektor hängt vom Jahr und von der Zeitzone ab [S06][S19]. Das Sternbild Stier ist wesentlich größer als der 30-Grad-Sektor und liegt durch die Präzession nicht deckungsgleich mit ihm [S13].\n\nBildsprache: Der Stier ist ein Zug- und Lasttier, das Gewicht trägt und Boden hält. In der griechischen Mythologie entführt Zeus als Stier die Europa; das Bild schwankt zwischen Fruchtbarkeit, Kraft und Begehren. Der traditionelle Herrscher ist Venus. Das natürliche zweite Haus verbindet das Zeichen mit Nahrung, Besitz, Werten und der Frage, was jemand als das Seine betrachtet [S12][S10].\n\nDeutung: Als fixes Erdzeichen wird der Stier mit Beharren, Körperbewusstsein und Genussfähigkeit verbunden. Die Tradition beschreibt eine Kraft, die nicht schnell ist, aber bleibt; die Dinge prüft, bevor sie ihnen traut, und sie dann hält. Das kann Verlässlichkeit, Ausdauer und eine gute Nähe zu Materie und Sinnlichkeit bedeuten. Es kann aber auch starr werden, wenn Veränderung nötig ist, oder Besitz und Sicherheit so wichtig nehmen, dass Lebendigkeit darunter leidet.\n\nDifferenzierung: Der Stier wird häufig auf Bequemlichkeit und Materialismus reduziert. Tradiert ist eher eine Frage nach Tragfähigkeit: Was hält? Was ist wirklich meins? Was muss ich loslassen, damit etwas wachsen kann? Ein Stier-Mond kann anders wirken als eine Stier-Sonne, und ein Stier-Aszendent beschreibt eher die Art des Auftretens als den gesamten Charakter. Die Zeichenebene ist eine Perspektive unter mehreren.\n\nTypische Missdeutung: Die Gleichung Stier gleich faul oder besitzgierig ist eine kulturelle Verkürzung. Die Tradition betont zuerst Bestand und sinnliche Prüfung. Widerstand gegen Veränderung ist eine mögliche Schattenseite, keine Definition.\n\nEntwicklungsfrage: Der Stier lernt, zwischen tragender Stabilität und bloßer Erstarrung zu unterscheiden, und zu merken, wann Festhalten teurer wird als Loslassen.","keywords":["Stabilität","Sinnlichkeit","Ressourcen","Fixerde","Venus"],"sources":["S06","S07","S10","S12","S13","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-erde","modalitaet-fix","faktor-venus","haus-2","zeichen-skorpion"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-erde","modality":"modalitaet-fix","polarity":"yin","ruler_traditional":"faktor-venus","ruler_modern":"faktor-venus","date_range_tropical":{"from":"04-20","to":"05-20","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Stier","glyph":"♉","bildsprache":"Stierkraft, Zugtier, Fruchtbarkeit, Erdung, Besitzgrenze."},"strengths":["Hält Projekte und Beziehungen über längere Zeit","Nimmt über Körper und Sinne genau wahr","Baut verlässliche Strukturen und Ressourcen auf","Bleibt in Krisen ruhig und belastbar","Hat ein feines Gespür für Qualität und Genuss"],"tensions":["Hält an Zuständen fest, die schon nicht mehr tragen","Verwechselt Sicherheit mit Kontrolle","Braucht lange, bis Veränderung als notwendig akzeptiert wird","Zieht sich in Bequemlichkeit zurück, wenn Anstrengung unangenehm wird","Kann Besitz und Status mit Wert verwechseln"],"reflection_questions":["Was hält mich wirklich, und was halte ich nur aus Gewohnheit?","Wo schütze ich Besitz, obwohl ich eigentlich Beziehung schützen will?","Welche sinnliche Erfahrung bringt mich zurück in den Moment?"],"common_misreading":"Stier gilt oft als materialistisch und unbeweglich. Die Tradition beschreibt zuerst eine prüfende, bestandssichernde Kraft; Erstarrung ist ihre mögliche Schattenform, nicht ihr Wesen.","natural_house":"haus-2","opposite":"zeichen-skorpion"},{"id":"zeichen-zwillinge","slug":"zwillinge","name":"Zwillinge","short":"Zwillinge ist das veränderliche Luftzeichen des Tropus. Traditionell steht es für Wahrnehmung, Sprache, Austausch und die Fähigkeit, mehrere Perspektiven gleichzeitig zu halten.","long":"Astronomische Orientierung: Der Zwillinge-Sektor umfasst ungefähr den 21. Mai bis 20. Juni. Die Grenze ist eine Konvention und kann je nach Quelle um einen Tag abweichen [S06][S19]. Das Sternbild Zwillinge ist nicht der Sektor; die tropische Einteilung folgt dem Frühlingspunkt und damit den Jahreszeiten, nicht den Sternbildgrenzen [S13][S14].\n\nBildsprache: Die Zwillinge verweisen auf die Dioskuren Kastor und Pollux, zwei ungleiche Brüder, die zusammen gehören und doch verschiedene Wege gehen. Das Bild trägt Spannung zwischen Nahe und Eigenständigkeit, zwischen einem und dem anderen. Der traditionelle Herrscher ist Merkur. Das natürliche dritte Haus verbindet das Zeichen mit Nachbarschaft, Geschwistern, Lernen, Medien und alltäglichem Austausch [S12][S10].\n\nDeutung: Als veränderliches Luftzeichen wird Zwillinge mit Beweglichkeit, Neugier und sprachlicher Gewandtheit verbunden. Die Tradition beschreibt ein Wahrnehmen, das schnell verbindet, vergleicht und benennt. Das kann geistige Flexibilität, Humor und die Fähigkeit sein, zwischen Gruppen zu vermitteln. Es kann aber auch zerstreuen: zu viele Fäden, zu wenig Tiefe, ein Wechsel der Position, der andere verunsichert.\n\nDifferenzierung: Zwillinge wird oft als oberflächlich oder unzuverlässig gelesen. Näher an der Tradition ist die Beschreibung einer parallelen Verarbeitung: Mehrere Eindrücke werden gleichzeitig aufgenommen und müssen erst geordnet werden. Das kann wie Widerspruch wirken, obwohl es eine Form des Denkens ist. Merkur in einem anderen Zeichen, ein Wasser-Mond oder ein betontes viertes Haus verändern die Ausdrucksform erheblich.\n\nTypische Missdeutung: Die Rede von der gespaltenen Persönlichkeit ist eine Verkürzung. Das Zeichen beschreibt einen Wechsel der Perspektive, nicht eine gespaltene Identität. Untreue oder Unverbindlichkeit sind mögliche ethische Entscheidungen, keine astrologischen Notwendigkeiten.\n\nEntwicklungsfrage: Zwillinge lernt, Neugier zu vertiefen, statt sie nur zu vervielfältigen, und Worte so zu wählen, dass sie Verbindung schaffen statt Flucht.","keywords":["Neugier","Sprache","Austausch","Veränderliche Luft","Merkur"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-luft","modalitaet-veraenderlich","faktor-merkur","haus-3","zeichen-schuetze"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-luft","modality":"modalitaet-veraenderlich","polarity":"yang","ruler_traditional":"faktor-merkur","ruler_modern":"faktor-merkur","date_range_tropical":{"from":"05-21","to":"06-20","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Zwillinge","glyph":"♊","bildsprache":"Zwei Brüder, Doppelung, Austausch, Brücke zwischen Welten."},"strengths":["Erfasst Zusammenhänge schnell und spielerisch","Findet Worte für komplexe Sachverhalte","Wechselt Perspektiven und vermittelt zwischen Gruppen","Bleibt neugierig und lernbereit","Bringt Leichtigkeit und Humor in festgefahrene Situationen"],"tensions":["Verliert sich in Nebenschauplätzen","Sagt Dinge, bevor sie zu Ende gedacht sind","Weicht Konflikten durch Themenwechsel aus","Wirkt auf andere unverbindlich oder widersprüchlich","Verwechselt Informationsmenge mit Verstehen"],"reflection_questions":["Welches Thema will ich wirklich zu Ende denken?","Wo nutze ich Sprache, um Nähe zu vermeiden?","Was gewinne ich, wenn ich eine Position länger halte?"],"common_misreading":"Zwillinge wird oft als oberflächlich, wankelmütig oder gespalten gelesen. Die Tradition beschreibt zuerst eine schnelle, vergleichende Wahrnehmung, die mehrere Perspektiven zugleich hält und darin auch überfordern kann.","natural_house":"haus-3","opposite":"zeichen-schuetze"},{"id":"zeichen-krebs","slug":"krebs","name":"Krebs","short":"Krebs ist das kardinale Wasserzeichen des Tropus. Traditionell verbindet es Schutz, Zugehörigkeit, Erinnerung und die Frage, wo jemand emotional verwurzelt ist.","long":"Astronomische Orientierung: Der Krebs-Sektor liegt ungefähr zwischen dem 21. Juni und dem 22. Juli. Der Zeitraum ist eine gerundete Orientierung; der genaue Wechsel hängt vom Jahr und von der Zeitzone ab [S06][S19]. Das Sternbild Krebs ist auffallend klein und schwach, während der tropische Sektor exakt 30 Grad umfasst. Das zeigt noch einmal, dass Zeichen und Sternbilder verschiedene Dinge sind [S13][S14].\n\nBildsprache: Der Krebs trägt einen Panzer und weiche Gliedmaßen; er bewegt sich seitwärts, hält sich an Strukturen fest und zieht sich bei Gefahr zurück. Das Bild ist weniger sentimental, als die populäre Deutung vermuten lässt: Es geht um Schutz, Grenze und die Frage, was jemand als Zuhause erlebt. Der traditionelle Herrscher ist der Mond. Das natürliche vierte Haus verbindet das Zeichen mit Herkunft, Familie, Wohnen und innerem Fundament [S12][S10].\n\nDeutung: Als kardinales Wasserzeichen wird Krebs mit emotionaler Aufmerksamkeit, Fürsorge und Erinnerung verbunden. Die kardinale Qualität zeigt sich nicht als lautes Vorwärtsgehen, sondern als initiierende Bewegung im Emotionalen: jemanden aufnehmen, ein Nest bauen, eine Grenze ziehen. Das kann Warmherzigkeit, Schutzinstinkt und eine gute Nähe zu Bedürfnissen bedeuten. Es kann aber auch in Rückzug, Überbehütung oder eine Bindung an alte Verletzungen kippen.\n\nDifferenzierung: Krebs wird häufig als kindlich, empfindlich oder häuslich verkürzt. Tradiert ist eine komplexe Schutzfigur: Wer viel schützt, hat oft selbst einen hohen Schutzbedarf. Ein Krebs-Aszendent kann zurückhaltend wirken, während eine Krebs-Sonne offen fürsorglich auftritt. Die Hausbesetzung und die Aspekte entscheiden, ob das Schutzbedürfnis eher als Nähe oder als Kontrolle erscheint.\n\nTypische Missdeutung: Tränen, Rückzug und Nostalgie sind mögliche Ausdrucksformen, aber nicht das ganze Zeichen. Die Tradition betont ebenso die Fähigkeit, Grenzen zu setzen und für andere da zu sein, ohne sich aufzulösen.\n\nEntwicklungsfrage: Krebs lernt, Schutz und Offenheit so zu dosieren, dass Nähe nicht zur Absicherung wird und alte Geschichten nicht die Gegenwart regieren.","keywords":["Schutz","Zugehörigkeit","Erinnerung","Kardinalwasser","Mond"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-wasser","modalitaet-kardinal","faktor-mond","haus-4","zeichen-steinbock"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-wasser","modality":"modalitaet-kardinal","polarity":"yin","ruler_traditional":"faktor-mond","ruler_modern":"faktor-mond","date_range_tropical":{"from":"06-21","to":"07-22","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Krebs","glyph":"♋","bildsprache":"Panzer und weiche Scheren, Nest, Rückzug, nächtliche Gezeiten."},"strengths":["Nimmt emotionale Zustände differenziert wahr","Schützt Menschen, die Schutz brauchen","Hält Erinnerungen und Zusammenhänge lebendig","Baut Nähe und Verlässlichkeit auf","Kann in Krisen für andere stabilisierend wirken"],"tensions":["Zieht sich zurück, statt Konflikte anzusprechen","Kränkt sich leichter, als sie oder er zeigt","Verwechselt Fürsorge mit Kontrolle","Bleibt an alten Verletzungen hängen","Erwartet Nähe, ohne sie klar zu benennen"],"reflection_questions":["Wo schütze ich mich, obwohl ich eigentlich Nähe will?","Welche alte Geschichte erzähle ich immer wieder?","Wie kann ich Fürsorge zeigen, ohne mich selbst zu verlieren?"],"common_misreading":"Krebs gilt oft als weich, kindlich oder häuslich. Die Tradition beschreibt eine Schutzfigur mit starker Grenz- und Zugehörigkeitsfrage; Rückzug und Fürsorge sind zwei Seiten derselben Bewegung.","natural_house":"haus-4","opposite":"zeichen-steinbock"},{"id":"zeichen-loewe","slug":"loewe","name":"Löwe","short":"Löwe ist das fixe Feuerzeichen des Tropus. Traditionell steht es für Präsenz, Gestaltung, Herz und die Erfahrung, gesehen zu werden.","long":"Astronomische Orientierung: Der Löwe-Sektor umfasst ungefähr den 23. Juli bis 22. August. Wie bei allen Zeichen ist das eine gerundete Konvention; der exakte Wechsel verschiebt sich jährlich [S06][S19]. Das Sternbild Löwe enthält helle Sterne und eine markante Form, ist aber nicht mit dem 30-Grad-Sektor identisch [S13][S14].\n\nBildsprache: Der Löwe ist ein Raubtier mit Mähne, das in der Sonne liegt und seinen Platz behauptet. In der griechischen Überlieferung steht der Nemëische Löwe für eine Kraft, die sich nicht mit einer gewöhnlichen Waffe bezwingen lässt; Herakles überwältigt ihn mit Körperkraft. Das Bild trägt mehr als Eitelkeit: Es geht um Würde, Gestaltung und die Frage, wofür jemand einsteht. Der traditionelle Herrscher ist die Sonne. Das natürliche fünfte Haus verbindet das Zeichen mit Kreativität, Spiel, Liebe und Selbstausdruck [S12][S10].\n\nDeutung: Als fixes Feuerzeichen wird Löwe mit Präsenz, Großzügigkeit und Gestaltungswillen verbunden. Die fixe Qualität gibt der Feuerkraft Dauer: nicht nur anfangen, sondern etwas zur Erscheinung bringen und dazu stehen. Das kann Charisma, Loyalität und die Fähigkeit sein, andere zu ermutigen. Es kann aber auch in Eitelkeit, Kränkung durch Nichtbeachtung oder den Zwang kippen, die Bühne zu kontrollieren.\n\nDifferenzierung: Die populäre Gleichsetzung mit Narzissmus greift zu kurz. Tradiert ist eine Gestaltungsfigur, die Resonanz braucht: Ohne Publikum wird Feuer schnell zu Pose oder Erschöpfung. Eine Löwe-Sonne kann zurückhaltend sein, wenn andere Faktoren Schüchternheit betonen; ein Löwe-Mond zeigt eher den emotionalen Hunger nach Anerkennung. Die kulturelle Aufladung von Männlichkeit und Stolz ist eine historische Schicht, keine Naturtatsache.\n\nTypische Missdeutung: Wer Löwe nur als selbstverliebt liest, übersieht die Großzügigkeit und den Mut, für etwas einzustehen. Wer das Zeichen als Freibrief für Dominanz nimmt, verwechselt eine Deutungsfigur mit einer Erlaubnis.\n\nEntwicklungsfrage: Löwe lernt, sich zu zeigen, ohne die Resonanz anderer zur Bedingung für den eigenen Wert zu machen.","keywords":["Präsenz","Gestaltung","Herz","Fixfeuer","Sonne"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-feuer","modalitaet-fix","faktor-sonne","haus-5","zeichen-wassermann"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-feuer","modality":"modalitaet-fix","polarity":"yang","ruler_traditional":"faktor-sonne","ruler_modern":"faktor-sonne","date_range_tropical":{"from":"07-23","to":"08-22","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Löwe","glyph":"♌","bildsprache":"Mähne, Sonne, Bühne, Herz, königliche Gestalt mit Verantwortung."},"strengths":["Bringt Dinge sichtbar und gestaltet zur Form","Ermutigt andere durch eigene Präsenz","Steht loyal zu Menschen und Projekten","Hat Würde und Haltung in schwierigen Lagen","Kann großzügig teilen und feiern"],"tensions":["Wird kränkbar, wenn Anerkennung ausbleibt","Verwechselt Aufmerksamkeit mit Wertschätzung","Dramatisiert Konflikte, um gesehen zu werden","Kontrolliert die Bühne, statt andere auftreten zu lassen","Verliert sich in Pose, wenn echte Resonanz fehlt"],"reflection_questions":["Wofür stehe ich ein, wenn niemand applaudiert?","Wo verwechsle ich Sichtbarkeit mit Bedeutung?","Wem gebe ich Raum, statt selbst im Zentrum zu bleiben?"],"common_misreading":"Löwe wird oft auf Eitelkeit und Narzissmus reduziert. Die Tradition beschreibt zuerst eine gestaltende, herzgeleitete Präsenz, die Resonanz braucht und in der Schattenform zur Pose erstarren kann.","natural_house":"haus-5","opposite":"zeichen-wassermann"},{"id":"zeichen-jungfrau","slug":"jungfrau","name":"Jungfrau","short":"Jungfrau ist das veränderliche Erdzeichen des Tropus. Traditionell steht es für Unterscheidung, Genauigkeit, Dienst und die Kunst, im Alltag brauchbare Ordnung zu schaffen.","long":"Astronomische Orientierung: Der Jungfrau-Sektor reicht ungefähr vom 23. August bis 22. September. Die Grenzen sind gerundet und variieren leicht je nach Quelle und Jahr [S06][S19]. Das Sternbild Jungfrau ist besonders ausgedehnt und enthält helle Sterne; der tropische Sektor bleibt dennoch exakt 30 Grad breit [S13][S14].\n\nBildsprache: Die Jungfrau trägt eine Ähre und verweist auf Ernte, Auswahl und Bearbeitung. In der griechischen Überlieferung ist Asträa, die Göttin der Gerechtigkeit, mit dem Bild verbunden; sie verlässt die Erde, als die Menschen ungerecht werden. Das Bild ist weniger sexuell konnotiert, als der Name in modernen Sprachen nahelegt: Es geht um Unterscheidung, Reinheit der Methode und die Frage, was brauchbar ist. Der traditionelle Herrscher ist Merkur. Das natürliche sechste Haus verbindet das Zeichen mit Arbeit, Routine, Gesundheit und Dienst [S12][S10].\n\nDeutung: Als veränderliches Erdzeichen wird Jungfrau mit Analyse, Sorgfalt und Verbesserung verbunden. Die Tradition beschreibt einen Blick für Details und Fehler, der Dinge funktionsfähig macht. Das kann handwerkliche Qualität, nützliche Kritik und eine gute Nähe zu Körper und Alltag bedeuten. Es kann aber auch in Perfektionismus, Selbstkritik und die ständige Sorge kippen, nicht zu genügen.\n\nDifferenzierung: Jungfrau wird oft als pedantisch oder kalt gelesen. Tradiert ist eine dienende, unterscheidende Intelligenz, die sich um das kümmert, was tatsächlich getan werden muss. Ein Jungfrau-Mond kann emotionale Sicherheit über Ordnung suchen; ein Jungfrau-Aszendent kann zurückhaltend und beobachtend wirken. Die berufliche und gesundheitliche Ebene ist Tradition und keine medizinische Aussage.\n\nTypische Missdeutung: Die Gleichsetzung mit Reinheit, Keuschheit oder ständiger Kritik ist eine kulturelle Verkürzung. Das Zeichen beschreibt eine Methode des Unterscheidens, nicht einen moralischen Rang. Selbstoptimierung kann ein Ausdruck sein, muss es aber nicht.\n\nEntwicklungsfrage: Jungfrau lernt, zwischen hilfreicher Genauigkeit und selbstschädigender Kontrolle zu unterscheiden, und das Gute im Unvollständigen zu sehen.","keywords":["Genauigkeit","Unterscheidung","Dienst","Veränderliche Erde","Merkur"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-erde","modalitaet-veraenderlich","faktor-merkur","haus-6","zeichen-fische"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert. Keine medizinischen Aussagen."},"element":"element-erde","modality":"modalitaet-veraenderlich","polarity":"yin","ruler_traditional":"faktor-merkur","ruler_modern":"faktor-merkur","date_range_tropical":{"from":"08-23","to":"09-22","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Jungfrau","glyph":"♍","bildsprache":"Ähre, Ernte, Auswahl, kritischer Blick, dienende Genauigkeit."},"strengths":["Erkennt Details und Fehler, die anderen entgehen","Macht Ideen alltagstauglich und überprüfbar","Arbeitet verlässlich und methodisch","Kann hilfreiche, konkrete Kritik formulieren","Sorgt für Ordnung, die Entlastung schafft"],"tensions":["Verwechselt Qualität mit Perfektion","Kritisiert sich selbst härter als andere","Verliert sich in Details und Nebenaufgaben","Sorgt sich um Dinge, die noch nicht eingetreten sind","Wirkt durch ständige Korrektur distanziert"],"reflection_questions":["Wann ist genug wirklich genug?","Wem dient meine Kritik gerade?","Was könnte ich loslassen, ohne dass etwas Wesentliches kaputtgeht?"],"common_misreading":"Jungfrau wird oft als pedantisch, frostig oder krankheitsfixiert dargestellt. Die Tradition beschreibt zuerst eine unterscheidende, dienende Intelligenz; Perfektionismus ist ihre Schattenform, keine Definition.","natural_house":"haus-6","opposite":"zeichen-fische"},{"id":"zeichen-waage","slug":"waage","name":"Waage","short":"Waage ist das kardinale Luftzeichen des Tropus. Traditionell steht es für Abwägung, Beziehung, Fairness und die Frage, wie Eigenes und Anderes ins Gleichgewicht kommen.","long":"Astronomische Orientierung: Der Waage-Sektor liegt ungefähr zwischen dem 23. September und 22. Oktober. Der Herbstpunkt, an dem die Sonne den Waage-Sektor betritt, ist der zweite Nullpunkt des tropischen Systems; die Datumsangabe bleibt dennoch eine gerundete Orientierung [S06][S19]. Das Sternbild Waage ist verhältnismäßig schwach und war in der Antike zeitweise Teil des Skorpions; die Zeichengeschichte und die Sternbildgeschichte verlaufen nicht parallel [S13][S14].\n\nBildsprache: Die Waage ist ein Messinstrument, kein Lebewesen. Sie verweist auf Vergleich, Gewichtung und die Möglichkeit, eine Schieflage zu erkennen. In der griechischen Überlieferung ist die Waage mit Dike, der Gerechtigkeit, und mit dem Herbstäquinoktium verbunden. Der traditionelle Herrscher ist Venus. Das natürliche siebte Haus verbindet das Zeichen mit Partnerschaft, Verträgen, offenen Gegnern und der Erfahrung, sich im Spiegel des Anderen zu sehen [S12][S10].\n\nDeutung: Als kardinales Luftzeichen wird Waage mit Perspektivwechsel, Ästhetik und Diplomatie verbunden. Die kardinale Qualität zeigt sich im Anstoß zur Beziehung: ein Gespräch beginnen, einen Ausgleich suchen, eine Form finden. Das kann Fairness, Takt und die Fähigkeit sein, unterschiedliche Interessen zusammenzubringen. Es kann aber auch in Entscheidungsschwierigkeit, Konfliktvermeidung oder Abhängigkeit von Zustimmung kippen.\n\nDifferenzierung: Waage wird oft als harmoniesüchtig und oberflächlich gelesen. Tradiert ist eine abwägende Figur, die Spannungen aushält, bis eine tragfähige Form gefunden ist. Eine Waage-Sonne kann durchaus konfliktscheu sein; ein Waage-Mond sucht emotionale Balance eher über Beziehung. Die kulturelle Zuschreibung von Weiblichkeit und Schönheit ist eine historische Schicht.\n\nTypische Missdeutung: Wer Waage auf Gefälligkeit reduziert, übersieht die anspruchsvolle Seite: Gerechtigkeit kann unbequem sein, und eine echte Abwägung braucht Mut zur Entscheidung. Harmonie um jeden Preis ist eine Schattenform, nicht das Ziel.\n\nEntwicklungsfrage: Waage lernt, eine Position zu beziehen, ohne die Beziehung abzubrechen, und zu merken, dass Klarheit Fairness sein kann.","keywords":["Abwägung","Beziehung","Fairness","Kardinaluft","Venus"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-luft","modalitaet-kardinal","faktor-venus","haus-7","zeichen-widder"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-luft","modality":"modalitaet-kardinal","polarity":"yang","ruler_traditional":"faktor-venus","ruler_modern":"faktor-venus","date_range_tropical":{"from":"09-23","to":"10-22","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Waage","glyph":"♎","bildsprache":"Zwei Schalen, Gleichgewicht, Herbstpunkt, Spiegel und Vertrag."},"strengths":["Sieht mehrere Seiten einer Sache","Formuliert fair und vermittelnd","Hat ein Gespür für Form, Ton und Ästhetik","Kann Beziehungen und Kooperationen aufbauen","Hält Spannungen aus, bis eine tragbare Lösung gefunden ist"],"tensions":["Schiebt Entscheidungen auf, um niemanden zu enttäuschen","Verwechselt Harmonie mit Konfliktvermeidung","Wird abhängig von Zustimmung","Bleibt unklar, um Beziehungen nicht zu gefährden","Übersieht eigene Bedürfnisse im Abwägen"],"reflection_questions":["Welche Entscheidung vermeide ich, um es allen recht zu machen?","Wo ist Klarheit die fairere Lösung?","Was will ich, wenn ich nicht zuerst an die Reaktion anderer denke?"],"common_misreading":"Waage gilt oft als gefällig und unentschlossen. Die Tradition beschreibt zuerst eine abwägende, beziehungsorientierte Figur; Konfliktvermeidung ist eine Schattenform, nicht das ganze Zeichen.","natural_house":"haus-7","opposite":"zeichen-widder"},{"id":"zeichen-skorpion","slug":"skorpion","name":"Skorpion","short":"Skorpion ist das fixe Wasserzeichen des Tropus. Traditionell steht es für Tiefe, Bindung, Macht und die Auseinandersetzung mit dem, was verborgen ist.","long":"Astronomische Orientierung: Der Skorpion-Sektor umfasst ungefähr den 23. Oktober bis 21. November. Die Grenze ist eine Konvention und kann in Publikationen um einen Tag abweichen [S06][S19]. Das Sternbild Skorpion ist deutlich größer als der tropische Sektor und liegt teilweise außerhalb der Ekliptikbreite; die Präzession verschiebt außerdem die Deckung zwischen Zeichen und Sternbild [S13][S14].\n\nBildsprache: Der Skorpion trägt einen Stachel und lebt in Verstecken. Das Bild ist stark aufgeladen: Gefahr, Gift, Verteidigung, aber auch Häutung und Regeneration. In der griechischen Überlieferung tötet der Skorpion Orion; die Figur steht für eine Kraft, die den Jäger zur Strecke bringt, also für Grenzen der eigenen Macht. Der traditionelle Herrscher ist Mars, in der modernen Zuordnung Pluto. Das natürliche achte Haus verbindet das Zeichen mit geteilten Ressourcen, Intimität, Verlust, Erbe und Transformation [S12][S10].\n\nDeutung: Als fixes Wasserzeichen wird Skorpion mit emotionaler Intensität, Loyalität und einem Gespür für Machtverhältnisse verbunden. Die fixe Qualität gibt dem Wasser Dauer: Gefühle bleiben, Bindungen werden tief, und was einmal wichtig war, lässt sich schwer ablegen. Das kann Krisenfestigkeit, Wahrnehmung für Untertöne und die Fähigkeit sein, sich wirklich einzulassen. Es kann aber auch in Kontrolle, Misstrauen, Geheimhaltung und Groll kippen.\n\nDifferenzierung: Die populäre Darstellung als rachsüchtig, sexuell oder gefährlich ist eine Verkürzung und oft sensationell aufgeladen. Tradiert ist eine Figur der Tiefe und der Grenzüberschreitung: Wer sich auf Skorpion einlässt, kommt an Punkte, die nicht oberflächlich bleiben. Ein Skorpion-Mond zeigt eher die emotionale Intensität, ein Skorpion-Aszendent eher eine zurückhaltende, prüfende Präsenz. Die moderne Pluto-Zuordnung ist eine Ergänzung des 20. Jahrhunderts, keine antike Selbstverständlichkeit.\n\nTypische Missdeutung: Wer Skorpion mit Bösartigkeit gleichsetzt, verwechselt eine Deutungsfigur mit einer moralischen Diagnose. Die Tradition beschreibt eine Schutz- und Tiefenbewegung; Kontrolle und Misstrauen sind mögliche Folgen von Verletzung, keine Naturnotwendigkeit.\n\nEntwicklungsfrage: Skorpion lernt, Intensität zuzulassen, ohne sie in Kontrolle zu verwandeln, und Vertrauen als Entscheidung zu behandeln, nicht als Risikofreiheit.","keywords":["Tiefe","Bindung","Macht","Fixwasser","Pluto"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12","c13"],"cross_refs":["element-wasser","modalitaet-fix","faktor-mars","faktor-pluto","haus-8","zeichen-stier"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert. Keine Aussagen über reale Personen."},"element":"element-wasser","modality":"modalitaet-fix","polarity":"yin","ruler_traditional":"faktor-mars","ruler_modern":"faktor-pluto","date_range_tropical":{"from":"10-23","to":"11-21","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Skorpion","glyph":"♏","bildsprache":"Stachel, Versteck, Häutung, Grenze der Macht, unterirdische Tiefe."},"strengths":["Geht Beziehungen und Themen wirklich auf den Grund","Bleibt in Krisen ansprechbar und loyal","Erkennt Machtverhältnisse und Untertöne","Kann sich intensiv auf eine Sache konzentrieren","Hat Mut, Unangenehmes nicht zu beschönigen"],"tensions":["Verwechselt Schutz mit Kontrolle","Misstraut, bevor Vertrauen überhaupt geprüft wurde","Hält Informationen zurück, um nicht verletzlich zu sein","Trägt Groll über lange Zeit","Zieht sich ganz zurück, statt einen Konflikt zu klären"],"reflection_questions":["Wem schenke ich Vertrauen, und was müsste passieren, damit ich es tue?","Wo schütze ich mich, indem ich andere kontrolliere?","Was wird leichter, wenn ich einen alten Groll loslasse?"],"common_misreading":"Skorpion wird oft als rachsüchtig, gefährlich oder rein sexuell dargestellt. Die Tradition beschreibt eine tiefe, gebundene Wasserfigur, deren Schatten Kontrolle und Misstrauen sind; beides folgt aus Verletzlichkeit, nicht aus Wesen.","natural_house":"haus-8","opposite":"zeichen-stier"},{"id":"zeichen-schuetze","slug":"schuetze","name":"Schütze","short":"Schütze ist das veränderliche Feuerzeichen des Tropus. Traditionell steht es für Weitblick, Sinnsuche, Lernen und die Bewegung über den eigenen Horizont hinaus.","long":"Astronomische Orientierung: Der Schütze-Sektor umfasst ungefähr den 22. November bis 21. Dezember. Die Angabe ist gerundet; der genaue Zeichenwechsel variiert jährlich und mit der Zeitzone [S06][S19]. Das Sternbild Schütze enthält das Zentrum der Milchstraße und ist astronomisch reich, aber nicht deckungsgleich mit dem tropischen Sektor [S13][S14].\n\nBildsprache: Der Schütze ist ein Bogenschütze, halb Mensch, halb Pferd, der auf ein Ziel außerhalb des eigenen Standorts zeigt. Das Bild trägt Reise, Jagd, Belehrung und die Frage, worauf jemand zielt. Der traditionelle Herrscher ist Jupiter. Das natürliche neunte Haus verbindet das Zeichen mit Fernreisen, höherer Bildung, Glauben, Recht und Sinnfragen [S12][S10].\n\nDeutung: Als veränderliches Feuerzeichen wird Schütze mit Optimismus, Lernfreude und Weitblick verbunden. Die veränderliche Qualität macht das Feuer beweglich: Es sucht neue Horizonte, statt an einem Ort zu brennen. Das kann Begeisterungsfähigkeit, großzügiges Denken und die Fähigkeit sein, Menschen für eine Idee zu gewinnen. Es kann aber auch in Maßlosigkeit, Belehrung und Flucht vor Details kippen.\n\nDifferenzierung: Schütze wird oft auf Reiselust und Lebensfreude reduziert. Tradiert ist eine Sinnfigur: Die Bewegung nach außen ist zugleich eine Suche nach Orientierung. Ein Schütze-Mond sucht emotionale Weite; ein Schütze-Aszendent wirkt offen und zugewandt, kann aber Ungeduld zeigen. Die kulturelle Verbindung mit Religion und Lehrhaftigkeit ist historisch, nicht zwingend.\n\nTypische Missdeutung: Die Gleichsetzung mit Oberflächlichkeit oder Besserwisserei ist eine Schattenform. Die Tradition betont zuerst die Fähigkeit, über den eigenen Tellerrand zu schauen; Maßlosigkeit entsteht, wenn Weite mit Beliebigkeit verwechselt wird.\n\nEntwicklungsfrage: Schütze lernt, große Ziele mit konkreten Schritten zu verbinden und zuzuhören, bevor er erklärt.","keywords":["Weitblick","Sinnsuche","Lernen","Veränderliches Feuer","Jupiter"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-feuer","modalitaet-veraenderlich","faktor-jupiter","haus-9","zeichen-zwillinge"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-feuer","modality":"modalitaet-veraenderlich","polarity":"yang","ruler_traditional":"faktor-jupiter","ruler_modern":"faktor-jupiter","date_range_tropical":{"from":"11-22","to":"12-21","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Schütze","glyph":"♐","bildsprache":"Bogen und Pfeil, Zentaur, Horizont, Reise und Ziel."},"strengths":["Denkt in größeren Zusammenhängen","Begeistert sich für Lernen und neue Perspektiven","Ermutigt andere, über Grenzen hinauszudenken","Hat Humor und eine zugewandte Offenheit","Kann Sinn und Richtung in unübersichtlichen Lagen zeigen"],"tensions":["Verliert sich in großen Plänen ohne Umsetzung","Belehrt andere, statt zuzuhören","Verwechselt Freiheit mit Unverbindlichkeit","Übersieht Details, die für andere wichtig sind","Flieht vor Enge, statt sie zu gestalten"],"reflection_questions":["Welches Ziel verfolge ich wirklich, und welches ist nur eine Flucht?","Wann habe ich zuletzt zugehört, ohne zu erklären?","Was braucht mein großer Plan als nächsten konkreten Schritt?"],"common_misreading":"Schütze gilt oft als reisefreudig, laut und belehrend. Die Tradition beschreibt zuerst eine Sinn- und Weitebewegung; Maßlosigkeit und Besserwisserei sind Schattenformen, nicht die Definition.","natural_house":"haus-9","opposite":"zeichen-zwillinge"},{"id":"zeichen-steinbock","slug":"steinbock","name":"Steinbock","short":"Steinbock ist das kardinale Erdzeichen des Tropus. Traditionell steht es für Verantwortung, Struktur, Zeit und die Fähigkeit, langfristig etwas aufzubauen.","long":"Astronomische Orientierung: Der Steinbock-Sektor reicht ungefähr vom 22. Dezember bis 19. Januar. Der Jahreswechsel macht die Datumsangabe besonders fehleranfällig, wenn Zeitzonen oder Quellen unterschiedlich zählen; sie bleibt eine Orientierung [S06][S19]. Das Sternbild Steinbock ist klein und unscheinbar, während der tropische Sektor 30 Grad umfasst [S13][S14].\n\nBildsprache: Der Steinbock ist ein Ziegenfisch, ein Wesen, das Klippen erklimmt und ins Wasser taucht. Das Bild verbindet Aufstieg mit Anpassung an schwieriges Gelände; es geht um Ausdauer, Grenze und die Frage, was jemand bereit ist zu tragen. Der traditionelle Herrscher ist Saturn. Das natürliche zehnte Haus verbindet das Zeichen mit Beruf, öffentlicher Rolle, Verantwortung und Ziel [S12][S10].\n\nDeutung: Als kardinales Erdzeichen wird Steinbock mit Realismus, Disziplin und langfristiger Planung verbunden. Die kardinale Qualität zeigt sich nicht als spontaner Impuls, sondern als gerichtete Anstrengung: einen Weg beginnen, der über Jahre trägt. Das kann Verlässlichkeit, Verantwortungsbewusstsein und die Fähigkeit sein, schwierige Aufgaben zu übernehmen. Es kann aber auch in Härte, Statusfixierung und Freudlosigkeit kippen.\n\nDifferenzierung: Steinbock wird oft als kalt und karrieristisch dargestellt. Tradiert ist eine Figur der Begrenzung und Formgebung: Wer Grenzen kennt, kann bauen. Ein Steinbock-Mond sucht Sicherheit über Struktur; ein Steinbock-Aszendent wirkt zurückhaltend und ernst, kann aber auch eine große Warmherzigkeit schützen. Die kulturelle Gleichsetzung mit Erfolg ist eine moderne Verengung.\n\nTypische Missdeutung: Wer Steinbock auf Status und Leistung reduziert, übersieht die Zeitdimension: Es geht um Reifung, nicht nur um Erfolg. Härte gegen sich selbst ist eine Schattenform, keine Tugend.\n\nEntwicklungsfrage: Steinbock lernt, Verantwortung zu tragen, ohne sich selbst dabei zu vergessen, und Struktur als Ermöglichung statt als Gefängnis zu erleben.","keywords":["Verantwortung","Struktur","Zeit","Kardinalerde","Saturn"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-erde","modalitaet-kardinal","faktor-saturn","haus-10","zeichen-krebs"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-erde","modality":"modalitaet-kardinal","polarity":"yin","ruler_traditional":"faktor-saturn","ruler_modern":"faktor-saturn","date_range_tropical":{"from":"12-22","to":"01-19","note":"Ungefähre tropische Orientierung über den Jahreswechsel; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Steinbock","glyph":"♑","bildsprache":"Ziegenfisch, Klippe, Aufstieg, Zeit und tragende Struktur."},"strengths":["Plant langfristig und hält durch","Übernimmt Verantwortung für das, was sie oder er zusagt","Baut Strukturen, die anderen Halt geben","Bleibt realistisch in schwierigen Lagen","Kann aus begrenzten Mitteln etwas Tragfähiges machen"],"tensions":["Wird zu hart gegen sich selbst","Verwechselt Wert mit Leistung oder Status","Verschiebt Genuss auf später","Kontrolliert aus Angst vor Kontrollverlust","Wirkt distanziert, obwohl Nähe gewünscht ist"],"reflection_questions":["Wofür trage ich Verantwortung, und wofür eigentlich nicht?","Was würde ich tun, wenn niemand meine Leistung bewertet?","Wo darf Leichtigkeit sein, ohne dass etwas zusammenbricht?"],"common_misreading":"Steinbock wird oft als kalt und karrieristisch gelesen. Die Tradition beschreibt zuerst eine Form- und Zeitfigur, die aus Grenzen Tragfähigkeit macht; Härte ist eine Schattenform, keine Definition.","natural_house":"haus-10","opposite":"zeichen-krebs"},{"id":"zeichen-wassermann","slug":"wassermann","name":"Wassermann","short":"Wassermann ist das fixe Luftzeichen des Tropus. Traditionell steht es für Eigenständigkeit, Systemblick, Zukunft und die Spannung zwischen Nähe und Distanz.","long":"Astronomische Orientierung: Der Wassermann-Sektor umfasst ungefähr den 20. Januar bis 18. Februar. Die Grenze ist gerundet und variiert je nach Quelle und Jahr [S06][S19]. Das Sternbild Wassermann ist groß und lichtschwach; der tropische Sektor ist wiederum ein exakter 30-Grad-Abschnitt [S13][S14].\n\nBildsprache: Der Wassermann trägt einen Krug und gießt Wasser aus, das nicht ihm gehört. Das Bild ist paradox: Ein Luftzeichen mit Wasser assoziiert, ein Einzelgänger, der eine gemeinsame Ressource verteilt. In der griechischen Überlieferung ist Ganymed der Mundschenk der Götter; das Bild verbindet Dienst, Außenseitertum und die Frage, wem jemand angehört. Der traditionelle Herrscher ist Saturn, in der modernen Zuordnung Uranus. Das natürliche elfte Haus verbindet das Zeichen mit Freundschaften, Netzwerken, Zukunftsideen und kollektiven Zielen [S12][S10].\n\nDeutung: Als fixes Luftzeichen wird Wassermann mit Eigenständigkeit, Abstraktion und einem Blick für Systeme verbunden. Die fixe Qualität gibt der Luft Dauer: Eine Idee wird nicht schnell fallen gelassen, auch wenn sie unbequem ist. Das kann Erfindungsgeist, Fairness gegenüber Gruppen und die Fähigkeit sein, Abstand als Klarheit zu nutzen. Es kann aber auch in Entfremdung, Prinzipienreiterei und emotionale Distanz kippen.\n\nDifferenzierung: Wassermann wird oft als gefühllos oder exzentrisch dargestellt. Tradiert ist eine Figur, die Zugehörigkeit anders organisiert: über Ideen, Netzwerke und Prinzipien statt über exklusive Nähe. Ein Wassermann-Mond kann Nähe über Freundschaft suchen; ein Wassermann-Aszendent wirkt freundlich-distanziert. Die moderne Uranus-Zuordnung ist eine Ergänzung, keine antike Setzung.\n\nTypische Missdeutung: Wer Wassermann auf Andersartigkeit reduziert, übersieht den Anspruch an Gemeinschaft und Gerechtigkeit. Widerspruch um des Widerspruchs willen ist eine Schattenform, nicht das Wesen.\n\nEntwicklungsfrage: Wassermann lernt, Distanz und Nähe zu verbinden, ohne die eine Seite zur Flucht vor der anderen zu machen.","keywords":["Eigenständigkeit","Systemblick","Zukunft","Fixluft","Uranus"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-luft","modalitaet-fix","faktor-saturn","faktor-uranus","haus-11","zeichen-loewe"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-luft","modality":"modalitaet-fix","polarity":"yang","ruler_traditional":"faktor-saturn","ruler_modern":"faktor-uranus","date_range_tropical":{"from":"01-20","to":"02-18","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Wassermann","glyph":"♒","bildsprache":"Wasserträger, Krug, Netzwerk, Zukunft und geteilte Ressource."},"strengths":["Denkt unabhängig und systemisch","Erkennt Ungerechtigkeit in Strukturen","Bleibt Ideen treu, auch wenn sie unbequem sind","Kann Gruppen und Netzwerke verbinden","Nutzt Distanz, um klar zu sehen"],"tensions":["Zieht sich in Prinzipien zurück, statt Nähe zu riskieren","Wirkt kühl, obwohl Interesse vorhanden ist","Widerspricht reflexartig, um Eigenständigkeit zu zeigen","Verliert den konkreten Menschen aus dem Blick","Verwechselt Freiheit mit Bindungsvermeidung"],"reflection_questions":["Wo verwechsle ich Abstand mit Klarheit?","Welche Nähe habe ich vermieden, obwohl ich sie wollte?","Wem nützt meine Idee konkret?"],"common_misreading":"Wassermann wird oft als gefühllos, exzentrisch oder unverbindlich gelesen. Die Tradition beschreibt zuerst eine eigenständige, systemorientierte Figur; Distanz ist eine mögliche Schutzform, keine Definition.","natural_house":"haus-11","opposite":"zeichen-loewe"},{"id":"zeichen-fische","slug":"fische","name":"Fische","short":"Fische ist das veränderliche Wasserzeichen des Tropus. Traditionell steht es für Durchlässigkeit, Imagination, Mitgefühl und die Frage nach Grenzen zwischen Ich und Welt.","long":"Astronomische Orientierung: Der Fische-Sektor liegt ungefähr zwischen dem 19. Februar und 20. März. Der Zeitraum ist eine gerundete Orientierung; der exakte Wechsel hängt von Jahr und Zeitzone ab [S06][S19]. Das Sternbild Fische ist groß und lichtschwach; der Frühlingspunkt liegt heute im Bereich dieses Sternbilds, während das tropische Zeichen Widder weiterhin am Äquinoktium beginnt [S13][S14].\n\nBildsprache: Zwei Fische, durch eine Schnur verbunden, schwimmen in entgegengesetzte Richtungen. Das Bild trägt Ambivalenz, Durchlässigkeit und die Frage, wie zwei Bewegungen zusammengehören. In der griechischen Überlieferung verwandeln sich Aphrodite und Eros in Fische, um sich zu retten; das Bild verbindet Liebe, Flucht und Anpassung. Der traditionelle Herrscher ist Jupiter, in der modernen Zuordnung Neptun. Das natürliche zwölfte Haus verbindet das Zeichen mit Rückzug, Unbewusstem, Auflösung und dem, was sich nicht sauber ordnen lässt [S12][S10].\n\nDeutung: Als veränderliches Wasserzeichen wird Fische mit Empathie, Imagination und Durchlässigkeit verbunden. Die veränderliche Qualität macht das Wasser beweglich: Es passt sich an, nimmt Formen an und verliert dabei leicht die eigene Kontur. Das kann Mitgefühl, künstlerische Sensibilität und die Fähigkeit sein, Atmosphären wahrzunehmen. Es kann aber auch in Abgrenzungsschwierigkeiten, Realitätsflucht und Überforderung kippen.\n\nDifferenzierung: Fische wird oft als schwach, chaotisch oder esoterisch verkürzt. Tradiert ist eine Figur der Grenzüberschreitung: Das Ich ist nicht klar vom Anderen getrennt, und gerade darin liegt eine besondere Wahrnehmungsfähigkeit. Ein Fische-Mond sucht emotionale Verschmelzung; ein Fische-Aszendent wirkt weich und anpassungsfähig. Die moderne Neptun-Zuordnung ist eine Ergänzung des 19. und 20. Jahrhunderts.\n\nTypische Missdeutung: Wer Fische mit Unzuverlässigkeit oder Schwäche gleichsetzt, verwechselt eine Schattenform mit dem Zeichen. Die Tradition beschreibt zuerst eine durchlässige Wahrnehmung, die einen klaren Rahmen braucht, um nicht in Beliebigkeit zu zerfallen.\n\nEntwicklungsfrage: Fische lernt, Grenzen zu setzen, ohne die eigene Empfindungsfähigkeit zu verlieren, und Mitgefühl mit Selbstachtung zu verbinden.","keywords":["Durchlässigkeit","Imagination","Mitgefühl","Veränderliches Wasser","Neptun"],"sources":["S06","S07","S10","S12","S13","S14","S19"],"claims":["c02","c06","c07","c12"],"cross_refs":["element-wasser","modalitaet-veraenderlich","faktor-jupiter","faktor-neptun","haus-12","zeichen-jungfrau"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Zeichendeutung ist Traditionsmaterial; astronomische Angaben sind separat belegt und als Näherung markiert."},"element":"element-wasser","modality":"modalitaet-veraenderlich","polarity":"yin","ruler_traditional":"faktor-jupiter","ruler_modern":"faktor-neptun","date_range_tropical":{"from":"02-19","to":"03-20","note":"Ungefähre tropische Orientierung; der exakte Wechsel verschiebt sich jährlich und ist zeitzonenabhängig."},"symbol":{"name":"Fische","glyph":"♓","bildsprache":"Zwei Fische an einer Schnur, Meer, Auflösung, Traum und Mitgefühl."},"strengths":["Nimmt Atmosphären und unausgesprochene Gefühle wahr","Kann sich in andere einfühlen, ohne vorschnell zu urteilen","Hat Zugang zu Bildern, Symbolen und künstlerischer Form","Bleibt in unklaren Lagen ansprechbar","Kann Mitgefühl und Großzügigkeit zeigen"],"tensions":["Verliert die eigene Grenze im Anderen","Weicht vor Konflikten in Fantasie oder Rückzug aus","Schiebt Entscheidungen auf, bis sie sich auflösen","Übernimmt Verantwortung für Dinge, die nicht die eigenen sind","Verwechselt Mitgefühl mit Selbstaufgabe"],"reflection_questions":["Wo endet mein Mitgefühl und wo beginnt Selbstaufgabe?","Welche Grenze brauche ich, damit Nähe möglich bleibt?","Was ist real, und was ist meine Sehnsucht?"],"common_misreading":"Fische gilt oft als schwach, chaotisch oder realitätsfern. Die Tradition beschreibt zuerst eine durchlässige, imaginative Wasserfigur; Abgrenzungsschwierigkeiten sind eine Schattenform, keine Definition.","natural_house":"haus-12","opposite":"zeichen-jungfrau"}];

export const FAKTOREN = [{"id":"faktor-sonne","slug":"sonne","name":"Sonne","short":"Die Sonne ist der Zentralkörper des Sonnensystems und in der Astrologie der Faktor für Identität, Selbstausdruck und bewusste Lebensrichtung.","long":"Astronomie: Die Sonne ist ein Stern und enthält den größten Teil der Masse des Sonnensystems. Von der Erde aus gesehen beschreibt sie im Laufe eines Jahres scheinbar einen Kreis entlang der Ekliptik; die tropische Einteilung beginnt diesen Kreis am Frühlingspunkt [S01][S14]. Die Erde umrundet die Sonne in rund 365,2 Tagen [S02]. Die Sonne geht im Osten auf und im Westen unter, weil sich die Erde dreht, nicht weil die Sonne die Erde umkreist.\n\nDeutungstradition: Die Sonne gilt als Faktor für Ich-Bild, Vitalität, Selbstvertrauen, bewusste Absicht und die Frage, wofür jemand steht. In der klassischen Herrschaftslehre regiert sie den Löwen; in der modernen Astrologie wird sie oft als Kern der Persönlichkeit gelesen. Das populäre Sonnenzeichen ist eine Verkürzung dieses Faktors auf die Position im Zeichensektor zum Geburtszeitpunkt [S12][S19].\n\nDifferenzierung: Die Sonne beschreibt keine messbare Persönlichkeit. Ein Sonnenzeichen sagt nichts über Intelligenz, Charakter oder Lebenserfolg aus [S06]. In der Radix wird die Sonne im Verhältnis zu Mond, Aszendent, Haus und Aspekten gelesen; dieselbe Sonne im Löwen kann in verschiedenen Häusern sehr unterschiedlich wirken. Die Sonne steht traditionell auch für Vaterbilder und öffentliche Rollen, aber diese Zuordnung ist kulturell geprägt und nicht universell.\n\nTypische Missdeutung: Die Gleichsetzung von Sonne mit Egoismus oder Herrschaft ist eine Verkürzung. Tradiert ist eher die Frage nach dem eigenen Zentrum: Was gibt jemandem Richtung, und was bleibt davon übrig, wenn niemand zusieht?\n\nZyklus: Die Sonne wechselt im tropischen System ungefähr einmal pro Monat den Zeichensektor; der scheinbare Jahreslauf ist die Grundlage des Sonnenzeichens [S01].","keywords":["Identität","Selbstausdruck","Lebensrichtung","Leuchtkörper","Löwe"],"sources":["S01","S02","S06","S12","S14","S19"],"claims":["c07","c12","c25","c27"],"cross_refs":["zeichen-loewe","haus-5","grund-sonnenzeichen-grenzen","aspekt-konjunktion"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Angaben sind belegt; die Zuordnung zu Identität und Lebensrichtung ist Deutungstradition."},"kind":"leuchtkoerper","astronomy":{"orbital_period_days":null,"orbital_period_text":"Kein Umlauf um die Erde; die Erde umrundet die Sonne in 365,2 Tagen, daraus entsteht der scheinbare Jahreslauf.","discovery":"Seit Urzeiten beobachtet.","visibility":"Mit bloßem Auge sichtbar, aber nie direkt ohne Schutz zu beobachten.","note":"Die Sonne ist der Zentralkörper; geozentrische Angaben sind Beobachtungsperspektive, kein Weltbild."},"themes":["Ich-Bild","Vitalität","bewusste Absicht","Selbstvertrauen","öffentliche Rolle"],"questions":["Wofür stehe ich ein, wenn niemand applaudiert?","Was gibt mir Richtung, unabhängig von Anerkennung?","Wo verwechsle ich Sichtbarkeit mit Selbstwert?"],"misreadings":["Die Sonne als ganzen Menschen zu lesen, statt als einen Faktor neben Mond, Aszendent und Häusern.","Sonnenzeichen-Typologien als Persönlichkeitstest zu verwenden, obwohl sie nur eine Zeichenposition beschreiben."],"rulerships":[{"sign":"zeichen-loewe","system":"traditionell"},{"sign":"zeichen-loewe","system":"modern"}],"cycle_text":"Rund ein Zeichensektor pro Monat; der genaue Wechsel verschiebt sich jährlich um Stunden bis einen Tag."},{"id":"faktor-mond","slug":"mond","name":"Mond","short":"Der Mond ist der nächste Himmelskörper der Erde und in der Astrologie der Faktor für emotionale Regulation, Bedürfnisse, Gewohnheit und körperliche Rhythmen.","long":"Astronomie: Der Mond umrundet die Erde in 27,3217 Tagen (siderischer Monat). Bis zur nächsten gleichen Phase vergehen 29,53 Tage (synodischer Monat), weil sich die Erde währenddessen weiter um die Sonne bewegt [S18]. Seine scheinbare Gestalt verändert sich durch den Winkel zwischen Sonne, Erde und Mond; die Phasen sind kein Schatten der Erde, sondern eine Beleuchtungsfrage. Der Mond stabilisiert die Erdachsenneigung und erzeugt Gezeiten.\n\nDeutungstradition: Der Mond gilt als Faktor für Gefühle, Bedürfnisse, Sicherheit, Erinnerung, Gewohnheit und die Art, wie jemand sich selbst beruhigt. In der Herrschaftslehre regiert er den Krebs; das natürliche vierte Haus verbindet ihn mit Herkunft und Zuhause [S12][S10]. Weil der Mond den Zeichensektor im Mittel etwa alle 2,46 Tage wechselt, ist das Mondzeichen ohne genaue Geburtszeit oft nicht sicher bestimmbar [S18].\n\nDifferenzierung: Die Astrologie liest den Mond nicht als Ursache von Gefühlen, sondern als Symbol für das, was jemand braucht, um sich sicher zu fühlen. Ein Mond in einem Feuerzeichen kann andere Bedürfnisse zeigen als ein Mond in Wasser oder Erde. Die populäre Rede von Mondphasen und Stimmung ist wissenschaftlich nicht belegt; der Mond beeinflusst Gezeiten und Lichtverhältnisse, aber es gibt keine belastbare Evidenz für einen direkten Einfluss auf menschliches Verhalten oder Gesundheit [S06][S09].\n\nTypische Missdeutung: Der Mond wird oft auf Launen oder Mütterlichkeit reduziert. Tradiert ist eine Regulationsfigur: Wie geht jemand mit Nähe, Unsicherheit und Wiederholung um? Der Mond ist nicht das ganze Gefühlsleben, sondern ein Zugang zu Bedürfnissen.\n\nZyklus: Siderisch 27,32 Tage, synodisch 29,53 Tage; daraus folgt ein Zeichenwechsel im Mittel alle 2,46 Tage.","keywords":["Gefühle","Bedürfnisse","Gewohnheit","Rhythmus","Krebs"],"sources":["S18","S12","S10","S06","S09"],"claims":["c07","c12","c15","c27"],"cross_refs":["zeichen-krebs","haus-4","grund-mond","faktor-sonne"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Zyklusdaten sind belegt; die emotionale Deutung ist Tradition und keine medizinische oder psychologische Diagnose."},"kind":"leuchtkoerper","astronomy":{"orbital_period_days":27.3217,"orbital_period_text":"Siderischer Monat 27,3217 Tage; synodischer Monat 29,53 Tage.","discovery":"Seit Urzeiten beobachtet.","visibility":"Mit bloßem Auge sichtbar; Phasen und Bahn sind ohne Hilfsmittel gut beobachtbar.","note":"Der Mond entfernt sich langsam von der Erde; die Bahn ist nicht exakt kreisförmig."},"themes":["emotionale Regulation","Sicherheit","Bedürfnisse","Erinnerung","Rhythmus"],"questions":["Was brauche ich, um mich sicher zu fühlen?","Welche Gewohnheit beruhigt mich, und welche hält mich fest?","Wo verwechsle ich Nähe mit Verschmelzung?"],"misreadings":["Den Mond als direkte Ursache von Stimmung oder Gesundheit zu behandeln; dafür gibt es keine belastbare Evidenz.","Das Mondzeichen ohne Geburtszeit als sicher zu bestimmen, obwohl der Mond den Sektor alle 2,46 Tage wechselt."],"rulerships":[{"sign":"zeichen-krebs","system":"traditionell"},{"sign":"zeichen-krebs","system":"modern"}],"cycle_text":"Siderisch 27,32 Tage; synodisch 29,53 Tage. Der Zeichenwechsel erfolgt im Mittel etwa alle 2,46 Tage."},{"id":"faktor-merkur","slug":"merkur","name":"Merkur","short":"Merkur ist der sonnennächste Planet und in der Astrologie der Faktor für Denken, Sprache, Lernen und Austausch.","long":"Astronomie: Merkur umrundet die Sonne in rund 88 Tagen und ist der kleinste Planet des Sonnensystems [S02]. Von der Erde aus entfernt er sich nie weit von der Sonne; deshalb ist er nur in der Nähe des Horizonts und nur kurz zu sehen. Seine scheinbare Rückwärtsbewegung entsteht durch die unterschiedliche Bahngeschwindigkeit von Erde und Merkur [S15].\n\nDeutungstradition: Merkur gilt als Faktor für Wahrnehmung, Sprache, Denken, Lernen, Handel und Vermittlung. In der Herrschaftslehre regiert er Zwillinge und Jungfrau; das natürliche dritte Haus verbindet ihn mit Nachrichten, Nachbarschaft und alltäglichem Austausch [S12][S10]. Merkur wird oft als schneller, beweglicher Faktor beschrieben, der Informationen sammelt und weitergibt.\n\nDifferenzierung: Ein Merkur-Zeichen beschreibt keine Intelligenz und keine Sprachbegabung im messbaren Sinn. Es beschreibt eine Stilfrage: Wie wird gedacht, wie wird gesprochen, wie wird geprüft? Merkur in einem Wasserzeichen kann anders formulieren als Merkur in Erde oder Luft. Die populäre Rede von Merkur rückläufig als Zeit für Vertrags- oder Technikchaos ist eine moderne Erzählung ohne belastbare Evidenz [S09].\n\nTypische Missdeutung: Merkur wird oft mit List oder Unzuverlässigkeit verbunden. Tradiert ist eine Vermittlungsfigur: Denken und Sprache sind Werkzeuge, die auch irren können. Die ethische Frage ist nicht, ob jemand geschickt spricht, sondern wofür.\n\nZyklus: Rund 88 Tage Umlauf; der Zeichensektor wechselt im Mittel alle zwei bis drei Wochen, stark abhängig von der scheinbaren Rückläufigkeit.","keywords":["Denken","Sprache","Lernen","Vermittlung","Zwillinge"],"sources":["S02","S12","S10","S15","S09"],"claims":["c07","c12","c14","c16","c27"],"cross_refs":["zeichen-zwillinge","zeichen-jungfrau","haus-3","grund-ruecklaeufigkeit"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Daten und die Scheinbarkeit der Rückläufigkeit sind belegt; die Denk- und Sprachdeutung ist Tradition."},"kind":"planet","astronomy":{"orbital_period_days":88,"orbital_period_text":"Rund 88 Tage.","discovery":"Seit der Antike bekannt.","visibility":"Mit bloßem Auge, aber nur kurz und nahe der Sonne.","note":"Merkur ist der sonnennächste und kleinste Planet; seine hohe Bahngeschwindigkeit erzeugt häufige scheinbare Rückläufe."},"themes":["Wahrnehmung","Sprache","Lernen","Handel","Vermittlung"],"questions":["Welche Geschichte erzähle ich mir über das, was ich sehe?","Wo hilft mir Sprache, und wo verdeckt sie?","Was prüfe ich selbst, statt es nur weiterzugeben?"],"misreadings":["Merkur mit Intelligenz gleichzusetzen; das Zeichen beschreibt einen Stil, keine Messgröße.","Rückläufigkeit als Ursache für konkrete technische oder vertragliche Probleme zu behandeln."],"rulerships":[{"sign":"zeichen-zwillinge","system":"traditionell"},{"sign":"zeichen-jungfrau","system":"traditionell"},{"sign":"zeichen-zwillinge","system":"modern"},{"sign":"zeichen-jungfrau","system":"modern"}],"cycle_text":"Umlauf rund 88 Tage; der Zeichensektor wechselt im Mittel alle zwei bis drei Wochen, mit scheinbaren Rückläufen."},{"id":"faktor-venus","slug":"venus","name":"Venus","short":"Venus ist der zweite Planet von der Sonne und in der Astrologie der Faktor für Werte, Attraktion, Ästhetik und Beziehungsstil.","long":"Astronomie: Venus umrundet die Sonne in rund 225 Tagen und ist von der Erde aus der hellste Planet am Himmel [S02]. Sie erscheint als Morgen- oder Abendstern, weil sie innerhalb der Erdbahn läuft und nie weit von der Sonne entfernt steht. Ihre dichte Atmosphäre und die hohe Oberflächentemperatur sind astronomische Eigenschaften, keine astrologischen Zeichen.\n\nDeutungstradition: Venus gilt als Faktor für das, was jemand schön, wertvoll oder anziehend findet: Beziehung, Genuss, Kunst, Harmonie und materielle Werte. In der Herrschaftslehre regiert sie Stier und Waage; das natürliche zweite und siebte Haus verbinden sie mit Besitz und Partnerschaft [S12][S10].\n\nDifferenzierung: Venus beschreibt keine Liebesfähigkeit und keine Moral. Sie zeigt eine Präferenz: Was wird als wertvoll erlebt, und wie wird Nähe gestaltet? Venus in Erde kann Nähe über Verlässlichkeit suchen, Venus in Luft über Gespräch. Die kulturelle Aufladung von Venus mit Weiblichkeit und Schönheit ist eine historische Schicht, keine Naturtatsache.\n\nTypische Missdeutung: Venus wird oft auf Romantik reduziert. Tradiert ist sie auch eine Figur für Wert und Tausch: Was ist jemand bereit zu geben, und was erwartet jemand dafür? Das schließt Geld, Kunst und Selbstwert ein.\n\nZyklus: Rund 225 Tage Umlauf; der Zeichensektor wechselt im Mittel alle drei bis vier Wochen.","keywords":["Werte","Attraktion","Ästhetik","Beziehung","Waage"],"sources":["S02","S12","S10"],"claims":["c07","c12","c16","c27"],"cross_refs":["zeichen-stier","zeichen-waage","haus-2","haus-7"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Daten sind belegt; die Zuordnung zu Werten und Attraktion ist Deutungstradition."},"kind":"planet","astronomy":{"orbital_period_days":224.7,"orbital_period_text":"Rund 225 Tage.","discovery":"Seit der Antike bekannt.","visibility":"Mit bloßem Auge als Morgen- oder Abendstern sehr hell sichtbar.","note":"Venus läuft innerhalb der Erdbahn und entfernt sich scheinbar nie weit von der Sonne."},"themes":["Werte","Attraktion","Genuss","Kunst","Beziehungsstil"],"questions":["Was ist mir wirklich wertvoll?","Wo verwechsle ich Anerkennung mit Nähe?","Wie gestalte ich Nähe, ohne mich zu verbiegen?"],"misreadings":["Venus auf Romantik zu verkürzen und Wert-, Geld- und Kunstfragen zu übersehen.","Venus-Zeichen als Aussage über Liebesfähigkeit oder Moral zu lesen."],"rulerships":[{"sign":"zeichen-stier","system":"traditionell"},{"sign":"zeichen-waage","system":"traditionell"},{"sign":"zeichen-stier","system":"modern"},{"sign":"zeichen-waage","system":"modern"}],"cycle_text":"Umlauf rund 225 Tage; der Zeichensektor wechselt im Mittel alle drei bis vier Wochen."},{"id":"faktor-mars","slug":"mars","name":"Mars","short":"Mars ist der vierte Planet von der Sonne und in der Astrologie der Faktor für Antrieb, Durchsetzung, Begehren und Konflikt.","long":"Astronomie: Mars umrundet die Sonne in rund 687 Tagen und ist der nächste äußere Nachbar der Erde [S02]. Seine rötliche Farbe stammt von Eisenmineralien auf der Oberfläche. Wie alle äußeren Planeten kann er von der Erde aus scheinbar rückwärts laufen, wenn die Erde ihn auf ihrer inneren Bahn überholt [S15].\n\nDeutungstradition: Mars gilt als Faktor für Energie, Durchsetzung, Mut, Begehren, Streit und die Art, wie jemand Widerstand begegnet. In der klassischen Herrschaftslehre regiert er Widder und Skorpion; in der modernen Astrologie bleibt Widder, während Skorpion oft Pluto zugeordnet wird [S12][S10].\n\nDifferenzierung: Mars beschreibt keine Gewaltbereitschaft. Tradiert ist eine Bewegungs- und Grenzfigur: Wie setzt jemand sich durch, wie verteidigt jemand etwas, wie geht jemand mit Frustration um? Mars in Wasser kann indirekt kämpfen, Mars in Erde langsam und zäh. Die kulturelle Gleichsetzung von Mars mit Männlichkeit ist eine historische Schicht.\n\nTypische Missdeutung: Mars wird oft mit Aggression oder Krieg gleichgesetzt. Die Tradition kennt auch den Mut, eine Grenze zu ziehen, und die Fähigkeit, für etwas einzustehen. Aggression ist eine mögliche Form, nicht die Definition.\n\nZyklus: Rund 687 Tage Umlauf; der Zeichensektor wechselt im Mittel alle sechs bis sieben Wochen, mit einer Rückläufigkeitsphase etwa alle zwei Jahre.","keywords":["Antrieb","Durchsetzung","Mut","Konflikt","Widder"],"sources":["S02","S12","S10","S15"],"claims":["c07","c12","c14","c16","c27"],"cross_refs":["zeichen-widder","zeichen-skorpion","haus-1","grund-ruecklaeufigkeit"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Daten sind belegt; die Antriebs- und Konfliktdeutung ist Tradition."},"kind":"planet","astronomy":{"orbital_period_days":687,"orbital_period_text":"Rund 687 Tage.","discovery":"Seit der Antike bekannt.","visibility":"Mit bloßem Auge als rötlicher Punkt sichtbar.","note":"Die scheinbare Rückläufigkeit entsteht durch das Überholen der Erde auf der inneren Bahn."},"themes":["Antrieb","Durchsetzung","Begehren","Abgrenzung","Konflikt"],"questions":["Wofür kämpfe ich, und wogegen?","Wie gehe ich mit Frustration um?","Wo ist Nachgeben eine Entscheidung und wo ein Muster?"],"misreadings":["Mars mit Gewalt oder Aggression gleichzusetzen.","Den Planeten als Ursache für Konflikte zu behandeln, statt als Deutungsfigur für den Umgang mit ihnen."],"rulerships":[{"sign":"zeichen-widder","system":"traditionell"},{"sign":"zeichen-skorpion","system":"traditionell"},{"sign":"zeichen-widder","system":"modern"}],"cycle_text":"Umlauf rund 687 Tage; der Zeichensektor wechselt im Mittel alle sechs bis sieben Wochen."},{"id":"faktor-jupiter","slug":"jupiter","name":"Jupiter","short":"Jupiter ist der größte Planet des Sonnensystems und in der Astrologie der Faktor für Ausdehnung, Sinn, Chancen und Überzeugungen.","long":"Astronomie: Jupiter umrundet die Sonne in rund 11,9 Jahren und ist massereicher als alle anderen Planeten zusammen [S02]. Von der Erde aus ist er mit bloßem Auge als heller Punkt sichtbar. Seine scheinbare Rückläufigkeit ist ein Perspektiveffekt der unterschiedlichen Bahngeschwindigkeiten [S15].\n\nDeutungstradition: Jupiter gilt als Faktor für Wachstum, Weite, Glauben, Bildung, Recht und die Frage, woran jemand sich orientiert. In der Herrschaftslehre regiert er Schütze und Fische; in der modernen Astrologie bleibt Schütze, während Fische oft Neptun zugeordnet wird [S12][S10].\n\nDifferenzierung: Jupiter beschreibt kein Glück und keine moralische Überlegenheit. Tradiert ist eine Ausdehnungsfigur: Was wird größer, wenn jemand ihm folgt? Das kann Großzügigkeit und Lernfreude sein, aber auch Maßlosigkeit und Überzeugung ohne Prüfung. Jupiter in Erde kann Wachstum konkret und langsam suchen, Jupiter in Feuer eher expansiv.\n\nTypische Missdeutung: Jupiter wird oft als Glücksplanet gelesen. Die Tradition kennt auch die Übertreibung: Zu viel Weite kann Details und Grenzen übersehen. Glück ist keine astrologische Kategorie.\n\nZyklus: Rund 11,9 Jahre Umlauf; der Zeichensektor wechselt im Mittel etwa einmal pro Jahr.","keywords":["Wachstum","Sinn","Bildung","Überzeugung","Schütze"],"sources":["S02","S12","S10","S15"],"claims":["c07","c12","c14","c16","c27"],"cross_refs":["zeichen-schuetze","zeichen-fische","haus-9","grund-transite"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Daten sind belegt; die Sinn- und Wachstumsdeutung ist Tradition."},"kind":"planet","astronomy":{"orbital_period_days":4331,"orbital_period_text":"Rund 11,9 Jahre.","discovery":"Seit der Antike bekannt.","visibility":"Mit bloßem Auge als heller Punkt sichtbar.","note":"Jupiter ist massereicher als alle anderen Planeten zusammen; seine Monde sind ein eigener Forschungsgegenstand."},"themes":["Wachstum","Sinn","Bildung","Recht","Überzeugung"],"questions":["Woran orientiere ich mich, wenn niemand zusieht?","Wo wird meine Weite zur Übertreibung?","Was lerne ich gerade wirklich?"],"misreadings":["Jupiter als Garantie für Glück oder Erfolg zu lesen.","Wachstum mit moralischer Richtigkeit gleichzusetzen."],"rulerships":[{"sign":"zeichen-schuetze","system":"traditionell"},{"sign":"zeichen-fische","system":"traditionell"},{"sign":"zeichen-schuetze","system":"modern"}],"cycle_text":"Umlauf rund 11,9 Jahre; der Zeichensektor wechselt im Mittel etwa einmal pro Jahr."},{"id":"faktor-saturn","slug":"saturn","name":"Saturn","short":"Saturn ist der sechste Planet von der Sonne und in der Astrologie der Faktor für Grenze, Struktur, Zeit und Verantwortung.","long":"Astronomie: Saturn umrundet die Sonne in rund 29,4 Jahren und ist für sein Ringsystem bekannt [S02]. Mit bloßem Auge ist er als gelblicher Punkt sichtbar; die Ringe sind erst mit Teleskopen zu erkennen. Seine scheinbare Rückläufigkeit folgt demselben Perspektivmuster wie bei den anderen äußeren Planeten [S15].\n\nDeutungstradition: Saturn gilt als Faktor für Begrenzung, Disziplin, Verantwortung, Zeit, Reifung und die Frage, was jemand aus hält. In der Herrschaftslehre regiert er Steinbock und Wassermann; in der modernen Astrologie bleibt Steinbock, während Wassermann oft Uranus zugeordnet wird [S12][S10].\n\nDifferenzierung: Saturn beschreibt keine Strafe und kein Unglück. Tradiert ist eine Formfigur: Wo braucht jemand Struktur, und wo wird Struktur zur Härte? Saturn in Erde kann sich in langfristigem Aufbau zeigen, Saturn in Wasser in emotionaler Zurückhaltung. Die populäre Angst vor Saturn-Rückkehr ist eine moderne Erzählung, keine belegte Ereignisvorhersage.\n\nTypische Missdeutung: Saturn wird oft als böser, einschränkender Planet gelesen. Die Tradition kennt auch die entlastende Seite: Grenzen machen Entscheidungen möglich. Verantwortung ist nicht dasselbe wie Selbstbestrafung.\n\nZyklus: Rund 29,4 Jahre Umlauf; der Zeichensektor wechselt im Mittel etwa alle zweieinhalb Jahre.","keywords":["Grenze","Struktur","Zeit","Verantwortung","Steinbock"],"sources":["S02","S12","S10","S15"],"claims":["c07","c12","c14","c16","c27"],"cross_refs":["zeichen-steinbock","zeichen-wassermann","haus-10","grund-transite"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Daten sind belegt; die Grenz- und Verantwortungsdeutung ist Tradition."},"kind":"planet","astronomy":{"orbital_period_days":10747,"orbital_period_text":"Rund 29,4 Jahre.","discovery":"Seit der Antike bekannt.","visibility":"Mit bloßem Auge als gelblicher Punkt sichtbar; Ringe nur mit Teleskop.","note":"Saturn ist der letzte mit bloßem Auge ohne weiteres auffindbare Planet der klassischen Siebenzahl."},"themes":["Grenze","Disziplin","Verantwortung","Zeit","Reifung"],"questions":["Welche Grenze entlastet mich?","Wo bin ich zu hart gegen mich?","Was baue ich langfristig, und wofür?"],"misreadings":["Saturn als Strafe oder Unglücksfaktor zu lesen.","Saturn-Rückkehr als sichere Ereignisvorhersage zu behandeln."],"rulerships":[{"sign":"zeichen-steinbock","system":"traditionell"},{"sign":"zeichen-wassermann","system":"traditionell"},{"sign":"zeichen-steinbock","system":"modern"}],"cycle_text":"Umlauf rund 29,4 Jahre; der Zeichensektor wechselt im Mittel etwa alle zweieinhalb Jahre."},{"id":"faktor-uranus","slug":"uranus","name":"Uranus","short":"Uranus ist ein Eisriese und in der modernen Astrologie der Faktor für Eigenständigkeit, Unterbrechung und Erneuerung.","long":"Astronomie: Uranus umrundet die Sonne in rund 84 Jahren und gehört zu den Eisriesen [S02][S24]. Seine Achse ist stark geneigt, sodass die Pole abwechselnd lange im Licht und im Dunkeln liegen. Uranus gehört nicht zur klassischen Siebenzahl der mit bloßem Auge bekannten Himmelskörper und wurde erst mit optischen Hilfsmitteln gefunden [S12].\n\nDeutungstradition: Uranus ist eine moderne Ergänzung der Astrologie. Er gilt als Faktor für Individualisierung, Bruch mit Konventionen, Innovation, Freiheit und plötzliche Veränderung. In der modernen Herrschaftslehre wird ihm Wassermann zugeordnet [S12][S10].\n\nDifferenzierung: Uranus beschreibt keine Rebellion und keine politische Haltung. Tradiert ist eine Unterbrechungsfigur: Wo wird ein Muster durchbrochen, und was wird dadurch sichtbar? Uranus in einem festen Zeichen kann Eigenständigkeit betonen, Uranus in Wasser eher als emotionale Distanzierung erscheinen. Die Zuordnung zu Wassermann ist eine Konvention des modernen Astrologiebetriebs, keine antike Setzung.\n\nTypische Missdeutung: Uranus wird oft als Chaot oder Befreier gefeiert. Die Tradition kennt auch die kalte Seite: Distanz, die Nähe verhindert, und Widerspruch, der nur der eigenen Unabhängigkeit dient.\n\nZyklus: Rund 84 Jahre Umlauf; der Zeichensektor wechselt im Mittel etwa alle sieben Jahre.","keywords":["Eigenständigkeit","Unterbrechung","Innovation","Freiheit","Wassermann"],"sources":["S02","S24","S12","S10"],"claims":["c07","c12","c16","c24","c27"],"cross_refs":["zeichen-wassermann","haus-11","grund-herrschaft"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Daten sind belegt; die Freiheits- und Unterbrechungsdeutung ist moderne Deutungstradition."},"kind":"planet","astronomy":{"orbital_period_days":30589,"orbital_period_text":"Rund 84 Jahre.","discovery":"Nicht zur klassischen Siebenzahl gehörend; mit optischen Hilfsmitteln entdeckt.","visibility":"Ohne Hilfsmittel nicht zuverlässig sichtbar.","note":"Uranus ist ein Eisriese mit stark geneigter Achse; die genaue Entdeckungsgeschichte wird hier nicht als Jahreszahl behauptet."},"themes":["Eigenständigkeit","Bruch","Innovation","Freiheit","Netzwerk"],"questions":["Wo durchbreche ich ein Muster, und wozu?","Ist meine Distanz Schutz oder Flucht?","Was bleibt von meiner Freiheit, wenn ich sie teile?"],"misreadings":["Uranus mit Rebellion oder Fortschritt gleichzusetzen.","Die moderne Wassermann-Zuordnung als antike Tradition auszugeben."],"rulerships":[{"sign":"zeichen-wassermann","system":"modern"}],"cycle_text":"Umlauf rund 84 Jahre; der Zeichensektor wechselt im Mittel etwa alle sieben Jahre."},{"id":"faktor-neptun","slug":"neptun","name":"Neptun","short":"Neptun ist der äußerste Planet des Sonnensystems und in der modernen Astrologie der Faktor für Auflösung, Imagination und Durchlässigkeit.","long":"Astronomie: Neptun umrundet die Sonne in rund 164 Jahren und ist der äußerste der acht Planeten [S02][S25]. Er wurde 1846 auf Grundlage von Bahnstörungen des Uranus aufgefunden und ist ohne Teleskop nicht sichtbar [S24][S25]. Seine blaue Farbe entsteht unter anderem durch Methan in der Atmosphäre.\n\nDeutungstradition: Neptun ist eine moderne Ergänzung. Er gilt als Faktor für Imagination, Mitgefühl, Spiritualität, Auflösung von Grenzen und die Frage, was sich nicht exakt fassen lässt. In der modernen Herrschaftslehre wird ihm Fische zugeordnet [S12][S10].\n\nDifferenzierung: Neptun beschreibt keine besondere Spiritualität und keine psychische Krankheit. Tradiert ist eine Durchlässigkeitsfigur: Wo verschwimmen Grenzen, und wo wird daraus Offenheit statt Orientierungslosigkeit? Neptun in Erde kann Ideale konkretisieren wollen, Neptun in Luft sie abstrahieren. Die Zuordnung zu Fische ist eine Konvention des 19./20. Jahrhunderts.\n\nTypische Missdeutung: Neptun wird oft als reine Esoterik oder als Illusion gelesen. Die Tradition kennt beides: die Fähigkeit, Bilder und Atmosphären wahrzunehmen, und die Gefahr, sich in ihnen zu verlieren.\n\nZyklus: Rund 164 Jahre Umlauf; der Zeichensektor wechselt im Mittel etwa alle 14 Jahre.","keywords":["Imagination","Mitgefühl","Auflösung","Spiritualität","Fische"],"sources":["S02","S24","S25","S12","S10"],"claims":["c07","c12","c16","c24","c27"],"cross_refs":["zeichen-fische","haus-12","grund-herrschaft"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Daten sind belegt; die Imaginations- und Auflösungsdeutung ist moderne Deutungstradition."},"kind":"planet","astronomy":{"orbital_period_days":59800,"orbital_period_text":"Rund 164 Jahre.","discovery":"1846 auf Grundlage von Bahnstörungen aufgefunden.","visibility":"Ohne Teleskop nicht sichtbar.","note":"Neptun ist der äußerste der acht Planeten; Pluto liegt jenseits davon auf einer anderen Bahn."},"themes":["Imagination","Mitgefühl","Grenzauflösung","Sehnsucht","Ambiguität"],"questions":["Wo sehe ich, was ich sehen will?","Welche Grenze braucht meine Offenheit?","Was trägt meine Sehnsucht, und was verdeckt sie?"],"misreadings":["Neptun mit Spiritualität oder psychischer Erkrankung gleichzusetzen.","Durchlässigkeit als Tugend zu feiern, ohne die Notwendigkeit von Grenzen zu benennen."],"rulerships":[{"sign":"zeichen-fische","system":"modern"}],"cycle_text":"Umlauf rund 164 Jahre; der Zeichensektor wechselt im Mittel etwa alle 14 Jahre."},{"id":"faktor-pluto","slug":"pluto","name":"Pluto","short":"Pluto ist ein Zwergplanet im Kuipergürtel und in der modernen Astrologie der Faktor für Macht, Tiefe, Verlust und Transformation.","long":"Astronomie: Pluto wurde am 18. Februar 1930 entdeckt und umrundet die Sonne in rund 248 Jahren auf einer stark exzentrischen Bahn [S20][S02]. Seit der IAU-Entscheidung von 2006 gilt er als Zwergplanet, nicht als Planet. Diese Einordnung ist ein astronomischer Status, keine Aussage darüber, ob Astrologinnen und Astrologen ihn weiter als Deutungsfaktor verwenden.\n\nDeutungstradition: Pluto ist eine moderne Ergänzung. Er gilt als Faktor für Macht, Kontrolle, Verlust, Scham, Tiefe und Prozesse, die sich nicht freiwillig vollziehen. In der modernen Herrschaftslehre wird ihm Skorpion zugeordnet [S12].\n\nDifferenzierung: Pluto beschreibt keine Gewalt und kein Schicksal. Tradiert ist eine Transformationsfigur: Was muss sterben, damit etwas anderes entstehen kann? Pluto in einem Zeichen kann Machtfragen betonen, Pluto in einem Haus das Lebensfeld, in dem Kontrolle und Hingabe verhandelt werden. Die Gleichsetzung mit Tod oder Katastrophe ist eine populäre Verkürzung.\n\nTypische Missdeutung: Pluto wird oft als dunkle, gefährliche Kraft inszeniert. Die Tradition kennt auch die Fähigkeit, sich mit dem Unangenehmen auseinanderzusetzen und Machtverhältnisse zu erkennen. Das ist keine Erlaubnis für Kontrolle.\n\nZyklus: Rund 248 Jahre Umlauf; der Zeichensektor wechselt wegen der exzentrischen Bahn stark variabel, grob zwischen 12 und 30 Jahren.","keywords":["Macht","Tiefe","Transformation","Kontrolle","Skorpion"],"sources":["S20","S02","S12"],"claims":["c07","c12","c13","c16","c27"],"cross_refs":["zeichen-skorpion","haus-8","grund-herrschaft"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Daten und der Zwergplanetenstatus sind belegt; die Macht- und Transformationsdeutung ist moderne Tradition."},"kind":"zwergplanet","astronomy":{"orbital_period_days":90560,"orbital_period_text":"Rund 248 Jahre.","discovery":"Entdeckt am 18. Februar 1930.","visibility":"Nur mit Teleskop sichtbar.","note":"Seit 2006 als Zwergplanet klassifiziert; die astrologische Verwendung ist davon unabhängig."},"themes":["Macht","Kontrolle","Verlust","Tiefe","Transformation"],"questions":["Wo gebe ich Macht ab, ohne es zu merken?","Was muss ich loslassen, damit etwas Neues entstehen kann?","Wann wird Schutz zu Kontrolle?"],"misreadings":["Pluto mit Tod, Gewalt oder sicheren Katastrophen gleichzusetzen.","Den astronomischen Zwergplanetenstatus mit der astrologischen Verwendung zu verwechseln."],"rulerships":[{"sign":"zeichen-skorpion","system":"modern"}],"cycle_text":"Umlauf rund 248 Jahre; der Zeichensektor wechselt wegen der exzentrischen Bahn stark variabel, grob zwischen 12 und 30 Jahren."}];

export const HAEUSER = [{"id":"haus-1","slug":"erstes-haus","name":"1. Haus","short":"Das erste Haus beginnt am Aszendenten und beschreibt traditionell Auftreten, Körperbezug, Selbstdarstellung und die Art, wie jemand in Situationen eintritt.","long":"Das erste Haus liegt am östlichen Horizont und beginnt in vielen Häusersystemen am Aszendenten. Es ist ein Winkelhaus und wird traditionell mit Identität, physischer Erscheinung, Temperament und der unmittelbaren Art des Auftretens verbunden [S10][S22]. Seine Lage am Horizont macht es zu einem der sensibelsten Bereiche für die Geburtszeit: Schon wenige Minuten können den Aszendenten und damit die Hausspitze verschieben.\n\nDeutung: Das erste Haus beschreibt keine fertige Persönlichkeit. Es zeigt eine Eintrittspforte: Wie beginnt jemand ein Gespräch, wie reagiert er auf einen Raum, wie zeigt sie sich, bevor sie sich erklärt? Zeichen und Planeten an der Hausspitze färben diese erste Bewegung. Ein besetztes erstes Haus kann Themen sichtbar machen, die andere sofort wahrnehmen; ein leeres erstes Haus ist keine Leerstelle, weil der Herrscher des Aszendenten weiterhin bedeutsam bleibt [S12].\n\nGrenze: Aussagen über Körper und Gesundheit sind hier Tradition und keine medizinische Diagnose. Das erste Haus ist kein Krankheitsbild und keine Charakterdiagnose.","keywords":["Aszendent","Auftreten","Identität","Winkelhaus","erster Eindruck"],"sources":["S10","S22","S12"],"claims":["c07","c08","c09","c26"],"cross_refs":["zeichen-widder","faktor-mars","grund-aszendent-mc","grund-haeuser-systeme"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Hausdeutung ist Traditionsmaterial; die Abhängigkeit von Zeit und Ort ist eine Konvention der Berechnung."},"number":1,"natural_sign":"zeichen-widder","angularity":"winkelhaus","hemisphere":"unter_dem_horizont","themes":["Auftreten","Körperbezug","Selbstwahrnehmung","Anfang","erster Eindruck"],"questions":["Wie trete ich in einen Raum, bevor ich spreche?","Was zeigen andere an mir, das ich selbst nicht sehe?","Wo verwechsle ich Schutz mit Maske?"],"caution":"Keine medizinischen oder charakterdiagnostischen Aussagen. Die Hausspitze ist zeitabhängig und systemabhängig."},{"id":"haus-2","slug":"zweites-haus","name":"2. Haus","short":"Das zweite Haus beschreibt traditionell Ressourcen, Werte, Besitz und die Frage, was jemand als das Seine betrachtet und wovon er lebt.","long":"Das zweite Haus folgt auf den Aszendenten und ist ein Sukzedentenhaus. Es wird traditionell mit materiellen und immateriellen Ressourcen verbunden: Geld, Besitz, Nahrung, Fähigkeiten, Selbstwert und das, was jemand als Sicherheit erlebt [S10]. Der natürliche Bezug zum Stier und zur Venus ist eine Analogie, keine automatische Gleichsetzung.\n\nDeutung: Das zweite Haus fragt nicht nur, was jemand hat, sondern wie er Wert bildet und was er bereit ist zu investieren. Ein betontes zweites Haus kann Ressourcenbewusstsein oder Besorgnis um Sicherheit zeigen; ein Planet dort kann die Art beschreiben, wie Werte erworben, gehalten oder geteilt werden. Die Hausbesetzung ist dabei nur ein Faktor neben Zeichen, Aspekten und Herrscher.\n\nGrenze: Finanzielle Aussagen sind hier keine Beratung. Das zweite Haus beschreibt eine symbolische Beziehung zu Ressourcen, keine Prognose über Einkommen, Vermögen oder Kreditwürdigkeit.","keywords":["Ressourcen","Werte","Besitz","Selbstwert","Sicherheit"],"sources":["S10","S12"],"claims":["c07","c08","c26"],"cross_refs":["zeichen-stier","faktor-venus","haus-8"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Ressourcen und Werten ist Tradition; keine Finanz- oder Rechtsberatung."},"number":2,"natural_sign":"zeichen-stier","angularity":"sukzedentenhaus","hemisphere":"unter_dem_horizont","themes":["Geld","Besitz","Fähigkeiten","Selbstwert","Sicherheit"],"questions":["Was bedeutet mir Sicherheit wirklich?","Welche Fähigkeit ist mir selbstverständlich geworden?","Wo verwechsle ich Wert mit Preis?"],"caution":"Keine Finanz-, Anlage- oder Schuldenberatung. Symbolische Ressourcenfrage, keine Prognose."},{"id":"haus-3","slug":"drittes-haus","name":"3. Haus","short":"Das dritte Haus beschreibt traditionell Kommunikation, Lernen, Nachbarschaft, Geschwister und den alltäglichen Austausch von Informationen.","long":"Das dritte Haus ist ein Kadentenhaus und wird traditionell mit kurzen Wegen, Nachrichten, Sprache, frühem Lernen, Geschwistern und der nahen Umgebung verbunden [S10]. Es steht in Analogie zu Zwillingen und Merkur: Wahrnehmung, Vergleich und Vermittlung.\n\nDeutung: Das dritte Haus fragt, wie jemand Informationen aufnimmt, ordnet und weitergibt. Ein betontes drittes Haus kann Neugier, viel Kommunikation oder eine lebhafte innere Stimme zeigen. Ein Planet dort kann die Art des Lernens oder Sprechens prägen. Es geht weniger um tiefe Überzeugungen als um den täglichen Verkehr mit Zeichen, Worten und Menschen in der Nähe.\n\nGrenze: Das Haus beschreibt keine Intelligenz und keine Sprachbegabung im messbaren Sinn. Es ist ein symbolisches Feld für Austausch und Lernen.","keywords":["Kommunikation","Lernen","Nachbarschaft","Geschwister","Alltag"],"sources":["S10","S12"],"claims":["c07","c08","c26"],"cross_refs":["zeichen-zwillinge","faktor-merkur","haus-9"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Kommunikation und Lernen ist Tradition, keine Messung von Intelligenz."},"number":3,"natural_sign":"zeichen-zwillinge","angularity":"kadentenhaus","hemisphere":"unter_dem_horizont","themes":["Sprache","Lernen","Nachbarschaft","Geschwister","Information"],"questions":["Wie spreche ich mit mir selbst?","Welche Informationen suche ich, und welche meide ich?","Wo ist Schweigen die klarere Antwort?"],"caution":"Keine Aussage über Intelligenz oder Sprachfähigkeit; Hausdeutung ist symbolisch."},{"id":"haus-4","slug":"viertes-haus","name":"4. Haus","short":"Das vierte Haus liegt am unteren Himmel und beschreibt traditionell Herkunft, Familie, Wohnen, inneres Fundament und das, was jemand als Zuhause erlebt.","long":"Das vierte Haus beginnt am IC, dem unteren Meridianpunkt. Es ist ein Winkelhaus und wird traditionell mit Herkunft, Elternhaus, Wurzeln, Wohnen, seelischem Fundament und dem Ende von Angelegenheiten verbunden [S10]. Die Analogie zu Krebs und Mond betont Schutz, Erinnerung und Zugehörigkeit.\n\nDeutung: Das vierte Haus beschreibt nicht nur die reale Familie, sondern die innere Struktur, von der aus jemand Sicherheit entwickelt. Ein betontes viertes Haus kann eine starke Bindung an Herkunft oder eine intensive Auseinandersetzung mit ihr zeigen. Ein Planet dort kann die Art beschreiben, wie jemand sich einrichtet, was er als privat schützt und wo er sich zu Hause fühlt.\n\nGrenze: Aussagen über Familie sind keine Aussagen über reale Angehörige. Das Haus beschreibt eine Perspektive auf Herkunft und Zugehörigkeit, keine Tatsachen über andere Menschen.","keywords":["Herkunft","Familie","Zuhause","Fundament","IC"],"sources":["S10","S12","S23"],"claims":["c07","c08","c09","c26"],"cross_refs":["zeichen-krebs","faktor-mond","haus-10","grund-aszendent-mc"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Herkunft und Zuhause ist Tradition; keine Aussagen über reale Familienmitglieder."},"number":4,"natural_sign":"zeichen-krebs","angularity":"winkelhaus","hemisphere":"unter_dem_horizont","themes":["Herkunft","Familie","Wohnen","Geborgenheit","inneres Fundament"],"questions":["Was bedeutet Zuhause für mich, unabhängig von einem Ort?","Welche Geschichte meiner Herkunft trage ich weiter?","Wo brauche ich Rückzug, um wieder Boden zu finden?"],"caution":"Keine Aussagen über reale Familienmitglieder oder Kindheitsdiagnosen."},{"id":"haus-5","slug":"fuenftes-haus","name":"5. Haus","short":"Das fünfte Haus beschreibt traditionell Kreativität, Spiel, Selbstausdruck, Liebe und die Freude am Hervorbringen.","long":"Das fünfte Haus ist ein Sukzedentenhaus und wird traditionell mit Vergnügen, Spiel, Kreativität, Romantik, Kindern und dem Wunsch verbunden, etwas Eigenes in die Welt zu bringen [S10]. Die Analogie zu Löwe und Sonne betont Gestaltung, Herz und Sichtbarkeit.\n\nDeutung: Das fünfte Haus fragt, was jemand aus Freude tut, nicht aus Pflicht. Ein betontes fünftes Haus kann Gestaltungswillen, Spiellust oder den Wunsch nach Anerkennung zeigen. Ein Planet dort kann die Art beschreiben, wie jemand liebt, gestaltet oder sich zeigt. Es geht auch um Risiko und darum, sich mit einem Ergebnis zu identifizieren.\n\nGrenze: Das Haus ist keine Aussage über Fruchtbarkeit, Kinderzahl oder sexuelle Orientierung. Es beschreibt eine symbolische Ebene von Kreativität und Freude.","keywords":["Kreativität","Spiel","Liebe","Selbstausdruck","Freude"],"sources":["S10","S12"],"claims":["c07","c08","c26"],"cross_refs":["zeichen-loewe","faktor-sonne","haus-11"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Kreativität und Freude ist Tradition; keine Aussagen zu Fruchtbarkeit oder realen Kindern."},"number":5,"natural_sign":"zeichen-loewe","angularity":"sukzedentenhaus","hemisphere":"unter_dem_horizont","themes":["Kreativität","Spiel","Romantik","Selbstausdruck","Risiko"],"questions":["Was tue ich aus Freude, ohne es rechtfertigen zu müssen?","Wo verwechsle ich Beifall mit Nähe?","Welches Risiko wäre es wert?"],"caution":"Keine Aussagen zu Fruchtbarkeit, Kinderwunsch oder sexueller Orientierung."},{"id":"haus-6","slug":"sechstes-haus","name":"6. Haus","short":"Das sechste Haus beschreibt traditionell Arbeit, Alltag, Routinen, Dienst und die Frage, wie jemand für sich und andere sorgt.","long":"Das sechste Haus ist ein Kadentenhaus und wird traditionell mit täglicher Arbeit, Pflichten, Handwerk, Dienst, Gesundheit und den kleinen Wiederholungen des Lebens verbunden [S10]. Die Analogie zu Jungfrau und Merkur betont Unterscheidung, Methode und Verbesserung.\n\nDeutung: Das sechste Haus fragt, wie jemand seinen Alltag organisiert und welche Rolle Arbeit, Routine und Nützlichkeit spielen. Ein betontes sechstes Haus kann Sorgfalt, Dienstbereitschaft oder ein starkes Pflichtgefühl zeigen. Ein Planet dort kann die Art beschreiben, wie jemand Aufgaben angeht, Grenzen zieht oder sich um Körper und Umgebung kümmert.\n\nGrenze: Das Haus ist keine medizinische Diagnose. Aussagen über Gesundheit sind hier als Alltagssymbolik zu lesen, nicht als Befund, Therapie oder Prognose.","keywords":["Arbeit","Alltag","Routine","Dienst","Sorgfalt"],"sources":["S10","S12"],"claims":["c07","c08","c26"],"cross_refs":["zeichen-jungfrau","faktor-merkur","haus-12"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Arbeit und Alltag ist Tradition; ausdrücklich keine medizinischen Aussagen."},"number":6,"natural_sign":"zeichen-jungfrau","angularity":"kadentenhaus","hemisphere":"unter_dem_horizont","themes":["Arbeit","Routine","Dienst","Handwerk","Selbstfürsorge"],"questions":["Welche Routine trägt mich, und welche erschöpft mich?","Wem diene ich, und wem sollte ich nicht dienen?","Wo ist Perfektion eine Ausrede?"],"caution":"Keine medizinische Diagnose, Therapie oder Gesundheitsprognose. Nur Alltagssymbolik."},{"id":"haus-7","slug":"siebtes-haus","name":"7. Haus","short":"Das siebte Haus beginnt am Deszendenten und beschreibt traditionell Partnerschaft, Verträge, offene Gegner und die Erfahrung, sich im Anderen zu spiegeln.","long":"Das siebte Haus liegt am westlichen Horizont gegenüber dem Aszendenten. Es ist ein Winkelhaus und wird traditionell mit Ehe, Partnerschaft, Geschäftspartnern, Verträgen und offenen Gegnern verbunden [S10][S22]. Die Analogie zu Waage und Venus betont Abwägung, Beziehung und Fairness.\n\nDeutung: Das siebte Haus beschreibt nicht, wen jemand heiratet, sondern wie jemand Beziehung gestaltet und was er im Anderen sucht oder abwehrt. Ein betontes siebtes Haus kann Beziehungsorientierung, Verhandlungsbereitschaft oder eine starke Fixierung auf das Gegenüber zeigen. Ein Planet dort kann die Art beschreiben, wie Nähe, Vertrag und Konflikt ausgehandelt werden.\n\nGrenze: Das Haus ist keine Aussage über konkrete Partner oder Trennungen. Es beschreibt eine symbolische Beziehungsachse, keine Ereignisvorhersage.","keywords":["Partnerschaft","Vertrag","Beziehung","Spiegel","Deszendent"],"sources":["S10","S22","S12"],"claims":["c07","c08","c09","c26"],"cross_refs":["zeichen-waage","faktor-venus","haus-1"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Partnerschaft ist Tradition; keine Aussagen über reale Partner oder Beziehungsverläufe."},"number":7,"natural_sign":"zeichen-waage","angularity":"winkelhaus","hemisphere":"ueber_dem_horizont","themes":["Partnerschaft","Vertrag","Nähe","Konflikt","Spiegelung"],"questions":["Was suche ich im Anderen, das ich selbst nicht zeige?","Wo sage ich ja, obwohl ich nein meine?","Welche Konflikte gehören wirklich mir?"],"caution":"Keine Aussagen über konkrete Partnerwahl, Trennung oder Ehe. Symbolische Beziehungsachse."},{"id":"haus-8","slug":"achtes-haus","name":"8. Haus","short":"Das achte Haus beschreibt traditionell geteilte Ressourcen, Intimität, Verlust, Erbe, Macht und Prozesse der Transformation.","long":"Das achte Haus ist ein Sukzedentenhaus und wird traditionell mit gemeinsamem Besitz, Schulden, Erbe, Intimität, Krisen, Verlust und dem Umgang mit Macht verbunden [S10]. Die Analogie zu Skorpion und den Herrschern Mars (traditionell) und Pluto (modern) betont Tiefe, Bindung und Grenzüberschreitung.\n\nDeutung: Das achte Haus fragt, was jemand teilt und was er zurückhält, wie er mit Abhängigkeit und Kontrolle umgeht und was geschieht, wenn Sicherheiten wegbrechen. Ein betontes achtes Haus kann Intensität, Krisenfestigkeit oder ein starkes Bedürfnis nach Kontrolle zeigen. Ein Planet dort kann die Art beschreiben, wie jemand Verlust, Nähe und gemeinsame Ressourcen verarbeitet.\n\nGrenze: Das Haus ist kein Todesurteil und keine Aussage über Erbschaften oder Krankheiten. Die populäre Gleichsetzung mit Tod ist eine Verkürzung; tradiert ist ein Feld von Bindung, Verlust und Wandlung.","keywords":["Intimität","Verlust","Erbe","Macht","Transformation"],"sources":["S10","S12","S20"],"claims":["c07","c08","c26"],"cross_refs":["zeichen-skorpion","faktor-pluto","haus-2"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Intimität und Wandlung ist Tradition; keine Todes-, Erb- oder Krankheitsprognose."},"number":8,"natural_sign":"zeichen-skorpion","angularity":"sukzedentenhaus","hemisphere":"ueber_dem_horizont","themes":["Intimität","geteilte Ressourcen","Verlust","Macht","Wandlung"],"questions":["Was halte ich zurück, um nicht verletzlich zu sein?","Wem vertraue ich, und warum?","Was bedeutet Teilen für mich?"],"caution":"Keine Aussagen zu Tod, Erbe, Krankheit oder finanziellen Verlusten."},{"id":"haus-9","slug":"neuntes-haus","name":"9. Haus","short":"Das neunte Haus beschreibt traditionell Sinnfragen, höhere Bildung, Fernreisen, Recht, Glauben und die Suche nach Orientierung.","long":"Das neunte Haus ist ein Kadentenhaus und wird traditionell mit Fernreisen, höherer Bildung, Philosophie, Religion, Recht und der Frage nach dem großen Zusammenhang verbunden [S10]. Die Analogie zu Schütze und Jupiter betont Weite, Überzeugung und Sinnsuche.\n\nDeutung: Das neunte Haus fragt, woran jemand glaubt und wie er sich orientiert, wenn die naheliegenden Antworten nicht reichen. Ein betontes neuntes Haus kann Lernfreude, Reiselust oder eine starke Überzeugung zeigen. Ein Planet dort kann die Art beschreiben, wie jemand Sinn konstruiert, Autoritäten prüft oder Grenzen überschreitet.\n\nGrenze: Das Haus ist keine Aussage über den Wahrheitsgehalt einer Weltanschauung. Es beschreibt eine symbolische Suchbewegung, keine religiöse oder rechtliche Wahrheit.","keywords":["Sinn","Bildung","Reise","Glauben","Orientierung"],"sources":["S10","S12"],"claims":["c07","c08","c26"],"cross_refs":["zeichen-schuetze","faktor-jupiter","haus-3"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Sinn und Bildung ist Tradition; keine Aussage über Wahrheit oder religiöse Verbindlichkeit."},"number":9,"natural_sign":"zeichen-schuetze","angularity":"kadentenhaus","hemisphere":"ueber_dem_horizont","themes":["Sinn","höhere Bildung","Fernreise","Recht","Glauben"],"questions":["Woran glaube ich, wenn ich es nicht beweisen kann?","Welche Überzeugung habe ich von anderen übernommen?","Was lerne ich, wenn ich meinen Horizont verschiebe?"],"caution":"Keine religiöse, rechtliche oder weltanschauliche Wahrheitsaussage."},{"id":"haus-10","slug":"zehntes-haus","name":"10. Haus","short":"Das zehnte Haus beginnt am MC und beschreibt traditionell Beruf, öffentliche Rolle, Verantwortung und das Bild, das andere von jemandem haben.","long":"Das zehnte Haus beginnt am MC, dem oberen Meridianpunkt. Es ist ein Winkelhaus und wird traditionell mit Beruf, öffentlicher Stellung, Autorität, Verantwortung und dem Ruf einer Person verbunden [S10][S23]. Die Analogie zu Steinbock und Saturn betont Struktur, Zeit und Leistung.\n\nDeutung: Das zehnte Haus beschreibt nicht, welchen Beruf jemand ausübt, sondern wie er öffentlich wirken und welche Verantwortung er tragen will. Ein betontes zehntes Haus kann Karriereorientierung, Sichtbarkeit oder eine starke Beziehung zu Autorität zeigen. Ein Planet dort kann die Art beschreiben, wie jemand Verantwortung übernimmt, sich präsentiert oder mit Erwartungen umgeht.\n\nGrenze: Das Haus ist keine Berufs- oder Erfolgsprognose. Es beschreibt eine symbolische Achse von öffentlicher Rolle und innerem Fundament, nicht ein messbares Karriereergebnis.","keywords":["Beruf","öffentliche Rolle","Verantwortung","MC","Ruf"],"sources":["S10","S23","S12"],"claims":["c07","c08","c09","c26"],"cross_refs":["zeichen-steinbock","faktor-saturn","haus-4","grund-aszendent-mc"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Beruf und öffentlicher Rolle ist Tradition; keine Karriere- oder Erfolgsprognose."},"number":10,"natural_sign":"zeichen-steinbock","angularity":"winkelhaus","hemisphere":"ueber_dem_horizont","themes":["Beruf","öffentliche Rolle","Autorität","Verantwortung","Ruf"],"questions":["Wofür will ich öffentlich einstehen?","Welche Erwartung habe ich an Erfolg?","Wer definiert, was gute Arbeit ist?"],"caution":"Keine Berufs-, Einkommens- oder Erfolgsprognose."},{"id":"haus-11","slug":"elftes-haus","name":"11. Haus","short":"Das elfte Haus beschreibt traditionell Freundschaften, Netzwerke, Gruppen, Zukunftsideen und die Frage, wozu jemand gehören will.","long":"Das elfte Haus ist ein Sukzedentenhaus und wird traditionell mit Freundschaft, Gemeinschaft, Förderern, Netzwerken, Hoffnungen und kollektiven Zielen verbunden [S10]. Die Analogie zu Wassermann und den Herrschern Saturn (traditionell) und Uranus (modern) betont Eigenständigkeit und Systemblick.\n\nDeutung: Das elfte Haus fragt, welche Gemeinschaft jemand sucht und welche Rolle er in ihr spielt. Ein betontes elftes Haus kann Netzwerkorientierung, Idealismus oder eine starke Bindung an Gruppen zeigen. Ein Planet dort kann die Art beschreiben, wie jemand Freundschaft versteht, Ziele teilt oder Distanz und Nähe in Gruppen reguliert.\n\nGrenze: Das Haus ist keine Aussage über die Anzahl oder Qualität realer Freundschaften. Es beschreibt eine symbolische Ebene von Zugehörigkeit und Zukunft.","keywords":["Freundschaft","Netzwerk","Gruppe","Zukunft","Zugehörigkeit"],"sources":["S10","S12"],"claims":["c07","c08","c26"],"cross_refs":["zeichen-wassermann","faktor-uranus","haus-5"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Freundschaft und Netzwerk ist Tradition; keine Aussage über reale soziale Beziehungen."},"number":11,"natural_sign":"zeichen-wassermann","angularity":"sukzedentenhaus","hemisphere":"ueber_dem_horizont","themes":["Freundschaft","Netzwerk","Gruppe","Hoffnung","Zukunft"],"questions":["Welcher Gruppe gehöre ich an, und warum?","Wo bin ich Teil eines Netzwerks, das mich nicht trägt?","Was hoffe ich für die Zukunft, und was tue ich dafür?"],"caution":"Keine Aussage über reale Freundschaften, Mitgliedschaften oder soziale Prognosen."},{"id":"haus-12","slug":"zwoelftes-haus","name":"12. Haus","short":"Das zwölfte Haus beschreibt traditionell Rückzug, Unbewusstes, Auflösung, Abgeschiedenheit und das, was sich der direkten Kontrolle entzieht.","long":"Das zwölfte Haus ist ein Kadentenhaus und wird traditionell mit Rückzug, Einsamkeit, Traum, Unbewusstem, verborgenen Dingen, Gefangenschaft und Auflösung verbunden [S10]. Die Analogie zu Fische und den Herrschern Jupiter (traditionell) und Neptun (modern) betont Durchlässigkeit und Grenzüberschreitung.\n\nDeutung: Das zwölfte Haus fragt, was jemand zurückzieht, was er nicht zeigen kann oder will und wo er sich selbst im Weg steht. Ein betontes zwölftes Haus kann Rückzugsbedarf, eine reiche Innenwelt oder ein Gefühl von Unklarheit zeigen. Ein Planet dort kann die Art beschreiben, wie jemand mit Einsamkeit, Schuld, Traum oder Auflösung umgeht.\n\nGrenze: Das Haus ist keine Diagnose und keine Aussage über psychische Erkrankung, Sucht oder Gefangenschaft. Die populäre Rede vom Schicksalshaus ist eine Verkürzung; tradiert ist ein Feld von Rückzug und innerer Verarbeitung.","keywords":["Rückzug","Unbewusstes","Traum","Auflösung","Einsamkeit"],"sources":["S10","S12"],"claims":["c07","c08","c26"],"cross_refs":["zeichen-fische","faktor-neptun","haus-6"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Zuordnung zu Rückzug und Unbewusstem ist Tradition; keine psychologische oder medizinische Diagnose."},"number":12,"natural_sign":"zeichen-fische","angularity":"kadentenhaus","hemisphere":"ueber_dem_horizont","themes":["Rückzug","Traum","Unbewusstes","Loslassen","Stille"],"questions":["Was ziehe ich zurück, weil ich es nicht zeigen kann?","Welche Stille brauche ich, und welche Isolation schadet mir?","Was würde ich sehen, wenn ich nicht wegschaue?"],"caution":"Keine psychologische oder medizinische Diagnose; keine Aussagen über Sucht, Haft oder Schicksal."}];

export const ASPEKTE = [{"id":"aspekt-konjunktion","slug":"konjunktion","name":"Konjunktion","short":"Die Konjunktion verbindet zwei Faktoren am selben Ort des Tierkreises. Traditionell gilt sie als Verdichtung: Die beteiligten Themen liegen nah beieinander und verstärken sich gegenseitig.","long":"Definition: Zwei Faktoren stehen bei einer Konjunktion im selben Gradbereich des Tierkreises, also in einem Winkel von etwa 0 Grad. Die zulässige Abweichung ist der Orbis. In der modernen Praxis werden für die Konjunktion häufig rund 8 bis 10 Grad angesetzt, bei Sonne oder Mond auch mehr; ohne Sonne und Mond nennen manche Astrologinnen und Astrologen eher 8 Grad [S11][S17].\n\nDeutung: Die Konjunktion gilt als Verdichtung. Anders als ein Spannungsaspekt trennt sie die Faktoren nicht, sondern legt sie übereinander. Das kann als Bündelung, Intensität oder Ununterscheidbarkeit erlebt werden: Zwei Themen sind so nah, dass sie schwer getrennt wahrgenommen werden. Ob das als Stärke oder als Enge wirkt, hängt von den beteiligten Faktoren, ihren Zeichen und Häusern ab. Eine Konjunktion von Sonne und Mond (Neumond) ist etwas anderes als eine Konjunktion von Saturn und Pluto.\n\nDifferenzierung: Die Konjunktion ist kein automatisch günstiger oder ungünstiger Aspekt. Sie kann Ressourcen bündeln, aber auch einen blinden Fleck erzeugen, weil zwei Motive immer gemeinsam auftreten. Wichtig ist, welche Faktoren beteiligt sind und ob ein Faktor den anderen dominiert. Die populäre Rede von einer guten oder schlechten Konjunktion verdeckt diese Unterschiede.\n\nOrb-Hinweis: Der Orbis ist eine Konvention. Ein weiter Orbis macht den Aspekt schwächer, ein enger Orbis prägnanter; eine einheitliche Norm gibt es nicht [S17].","keywords":["0 Grad","Verdichtung","Bündelung","Neumond","Orbis"],"sources":["S11","S17"],"claims":["c10","c11"],"cross_refs":["grund-aspekt-orben","faktor-sonne","faktor-mond"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Der Winkel ist eine Definition; die Deutung als Verdichtung und die Orb-Größen sind Fachkonventionen."},"angle_deg":0,"glyph":"☌","traditionelle_qualitaet":"Verdichtend und verbindend; weder eindeutig förderlich noch eindeutig spannungsreich. Die Qualität hängt von den beteiligten Faktoren ab.","orb":{"modern_typisch":"etwa 8 bis 10 Grad, bei Sonne oder Mond auch weiter","spanne":"etwa 0 bis 10 Grad, in manchen Schulen enger","schulhinweis":"Psychologische Astrologie neigt zu weiteren Orben, Horary und traditionelle Schulen zu engeren. Ohne Sonne und Mond werden häufig 8 Grad genannt [S11][S17]."},"common_misreading":"Die Konjunktion wird oft pauschal als guter oder starker Aspekt gelesen. Tatsächlich verbindet sie nur; ob daraus Ressource oder Enge wird, entscheiden die beteiligten Faktoren und der Kontext."},{"id":"aspekt-sextil","slug":"sextil","name":"Sextil","short":"Das Sextil trennt zwei Faktoren um 60 Grad. Traditionell gilt es als anregender, eher günstiger Aspekt, der Gelegenheiten und Austausch betont.","long":"Definition: Ein Sextil liegt bei einem Winkel von 60 Grad, also bei zwei Zeichen Abstand im Tierkreis. Die moderne Praxis verwendet häufig Orben von etwa 4 bis 6 Grad; manche Schulen gehen bis 8 Grad [S11]. Der Aspekt gehört zu den Hauptaspekten, auch wenn er in der populären Astrologie weniger Aufmerksamkeit bekommt als Quadrat oder Trigon.\n\nDeutung: Das Sextil wird traditionell als Gelegenheit, Anregung und Beweglichkeit gelesen. Es verbindet Faktoren, die sich ergänzen können, ohne sich zu bedrängen. Das kann als Neugier, Kooperation oder praktische Lösung erscheinen. Anders als das Trigon gilt es nicht als selbstverständlich fließend; es braucht eher eine bewusste Nutzung. Wer ein Sextil nicht aufgreift, verliert keine Katastrophe, sondern eine Möglichkeit.\n\nDifferenzierung: Die Qualität hängt von den beteiligten Faktoren ab. Ein Sextil zwischen Mond und Venus kann soziale Wärme begünstigen; ein Sextil zwischen Mars und Saturn kann strukturierte Anstrengung ermöglichen. Die Zuordnung zu günstig ist eine Tradition, keine Messung. In der modernen Psychologie der Astrologie wird das Sextil oft als Entwicklungschance beschrieben, die aktiv ergriffen werden muss.\n\nOrb-Hinweis: Kleine Orben sind üblich, weil der Aspekt sonst schnell in die Nähe anderer Winkel gerät. Die genaue Grenze ist eine Konvention [S17].","keywords":["60 Grad","Gelegenheit","Austausch","Anregung","Hauptaspekt"],"sources":["S11","S17"],"claims":["c10","c11"],"cross_refs":["grund-aspekt-orben","aspekt-trigon","aspekt-quadrat"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Der Winkel ist definiert; die Deutung als Gelegenheit und die Orb-Grenzen sind Konvention."},"angle_deg":60,"glyph":"⚹","traditionelle_qualitaet":"Anregend und eher förderlich; betont Gelegenheit und Austausch, ohne die Faktoren zu verschmelzen.","orb":{"modern_typisch":"etwa 4 bis 6 Grad","spanne":"etwa 2 bis 8 Grad, je nach Schule und beteiligten Faktoren","schulhinweis":"Kleinere Orben sind üblich, weil das Sextil sonst in die Nähe anderer Winkel rutscht. Psychologische Schulen nutzen eher weitere Orben [S17]."},"common_misreading":"Das Sextil wird oft als automatisch glücklich gelesen. Tradiert ist es eine Gelegenheit, die genutzt werden muss; ohne bewusste Entscheidung bleibt es eine Möglichkeit."},{"id":"aspekt-quadrat","slug":"quadrat","name":"Quadrat","short":"Das Quadrat trennt zwei Faktoren um 90 Grad. Traditionell gilt es als Spannungsaspekt, der Reibung, Entscheidungsdruck und Entwicklung erzwingt.","long":"Definition: Ein Quadrat liegt bei 90 Grad, also bei drei Zeichen Abstand. Die moderne Praxis verwendet häufig Orben von etwa 6 bis 8 Grad; manche Schulen gehen bis 8 Grad oder etwas darüber [S11]. Es ist neben der Opposition der klassische Spannungsaspekt.\n\nDeutung: Das Quadrat wird traditionell als Reibung gelesen: Zwei Faktoren wollen gleichzeitig wirken und stehen sich dabei im Weg. Das kann als innerer Konflikt, als äußerer Druck oder als Antrieb erlebt werden. Die Spannung ist nicht automatisch schlecht; sie kann Energie erzeugen, die ohne Widerstand fehlen würde. Wer ein Quadrat nur als Unglück liest, übersieht die developmental Seite: Reibung kann zu Handlung, Struktur und Reifung führen.\n\nDifferenzierung: Die Qualität hängt von den beteiligten Faktoren ab. Ein Quadrat zwischen Sonne und Saturn kann Disziplin erzwingen; ein Quadrat zwischen Venus und Mars kann Begehren und Bindung gegeneinander stellen. Die populäre Vorstellung, Quadrate seien grundsätzlich schlecht, ist eine Verkürzung. In der Radixdeutung wird eher gefragt, wie mit der Spannung umgegangen wird, als ob sie glücklich oder unglücklich macht.\n\nOrb-Hinweis: Ein Quadrat mit weitem Orbis kann als Hintergrundspannung wirken; ein exaktes Quadrat wird oft als prägnanter erlebt. Die Grenze bleibt eine Konvention [S17].","keywords":["90 Grad","Spannung","Reibung","Entwicklung","Hauptaspekt"],"sources":["S11","S17"],"claims":["c10","c11"],"cross_refs":["grund-aspekt-orben","aspekt-opposition","aspekt-trigon"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Der Winkel ist definiert; die Deutung als Spannung und die Orb-Grenzen sind Konvention."},"angle_deg":90,"glyph":"□","traditionelle_qualitaet":"Spannungsreich und handlungsfordernd; kann Reibung, Druck und Entwicklungsimpulse erzeugen.","orb":{"modern_typisch":"etwa 6 bis 8 Grad","spanne":"etwa 5 bis 8 Grad, je nach Schule und beteiligten Faktoren","schulhinweis":"Traditionelle und Horary-Schulen arbeiten enger, psychologische Schulen weiter. Ein exaktes Quadrat gilt als prägnanter als ein weites [S17]."},"common_misreading":"Das Quadrat wird oft als sicherer Unglücksfaktor gelesen. Tradiert ist es eine Spannung, die Handlung und Reifung erzwingen kann; entscheidend ist der Umgang mit ihr."},{"id":"aspekt-trigon","slug":"trigon","name":"Trigon","short":"Das Trigon trennt zwei Faktoren um 120 Grad. Traditionell gilt es als fließender, günstiger Aspekt, der Ressourcen und Selbstverständlichkeit betont.","long":"Definition: Ein Trigon liegt bei 120 Grad, also bei vier Zeichen Abstand. Die moderne Praxis verwendet häufig Orben von etwa 5 bis 10 Grad, abhängig von den beteiligten Faktoren [S11]. Es gilt als der klassische Harmonieaspekt neben dem Sextil.\n\nDeutung: Das Trigon wird traditionell als leichtes Zusammenspiel gelesen: Die Faktoren unterstützen sich, ohne dass viel gerungen werden muss. Das kann als Talent, Selbstverständlichkeit oder Glück im Sinne von Leichtigkeit erscheinen. Die Schattenseite ist, dass Leichtigkeit auch bequem machen kann: Was immer gelingt, wird selten geprüft oder weiterentwickelt.\n\nDifferenzierung: Nicht jedes Trigon ist automatisch wohltünd. Ein Trigon zwischen zwei schwierigen Faktoren kann eine Spannung so glatt machen, dass sie unbemerkt bleibt. Die Qualität hängt von den beteiligten Faktoren, ihren Zeichen und Häusern ab. Die populäre Gleichsetzung von Trigon mit Glück ist eine Verkürzung; tradiert ist eher ein Feld von Begabung und Selbstverständlichkeit.\n\nOrb-Hinweis: Weite Orben sind beim Trigon üblich, weil der Aspekt als stabil gilt. Die Grenze bleibt eine Konvention [S11][S17].","keywords":["120 Grad","Fließen","Talent","Leichtigkeit","Hauptaspekt"],"sources":["S11","S17"],"claims":["c10","c11"],"cross_refs":["grund-aspekt-orben","aspekt-sextil","aspekt-quadrat"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Der Winkel ist definiert; die Deutung als Harmonie und die Orb-Grenzen sind Konvention."},"angle_deg":120,"glyph":"△","traditionelle_qualitaet":"Fließend und eher förderlich; betont Ressourcen, Talent und Selbstverständlichkeit, kann aber bequem machen.","orb":{"modern_typisch":"etwa 6 bis 8 Grad, teilweise bis 10 Grad","spanne":"etwa 5 bis 10 Grad, je nach Schule und beteiligten Faktoren","schulhinweis":"Weite Orben sind üblich, weil das Trigon als stabil gilt. Psychologische Schulen nutzen eher größere Spielräume [S11][S17]."},"common_misreading":"Das Trigon wird oft als garantierter Glücksfall gelesen. Tradiert ist es eine Leichtigkeit, die auch zur Bequemlichkeit oder zum Übersehen von Spannungen führen kann."},{"id":"aspekt-opposition","slug":"opposition","name":"Opposition","short":"Die Opposition stellt zwei Faktoren gegenüber. Traditionell gilt sie als Spannungsaspekt, der Polarisierung, Spiegelung und Ausgleich verlangt.","long":"Definition: Eine Opposition liegt bei 180 Grad, also bei sechs Zeichen Abstand. Die moderne Praxis verwendet häufig Orben von etwa 8 bis 10 Grad; manche Schulen gehen bis 10 Grad oder etwas darüber [S11]. Sie ist der zweite klassische Spannungsaspekt neben dem Quadrat.\n\nDeutung: Die Opposition wird traditionell als Gegenüberstellung gelesen: Zwei Faktoren stehen sich gegenüber und verlangen eine Vermittlung. Das kann als äußerer Konflikt, als Projektion auf andere oder als innere Polarität erscheinen. Anders als das Quadrat ist die Opposition symmetrischer; sie kann bewusster verhandelt werden, weil beide Seiten sichtbar sind. Die Kunst liegt nicht darin, eine Seite zu wählen, sondern einen Umgang mit beiden zu finden.\n\nDifferenzierung: Die Opposition ist kein automatisch schlechter Aspekt. Sie kann Wachheit, Dialog und Balance erzeugen. Die populäre Vorstellung, Opposition bedeute Trennung oder Feindschaft, ist eine Verkürzung. In der Radixdeutung wird gefragt, welche Themen gegeneinander stehen und wie sie integriert werden können. Die Achse der beteiligten Häuser ist dabei oft wichtiger als der Winkel allein.\n\nOrb-Hinweis: Oppositionen mit weitem Orbis können als Hintergrundspannung wirken; exakte Oppositionen werden oft als prägnanter erlebt. Die Grenze bleibt eine Konvention [S17].","keywords":["180 Grad","Gegenüberstellung","Polarität","Ausgleich","Hauptaspekt"],"sources":["S11","S17"],"claims":["c10","c11"],"cross_refs":["grund-aspekt-orben","aspekt-quadrat","aspekt-konjunktion"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Der Winkel ist definiert; die Deutung als Polarität und die Orb-Grenzen sind Konvention."},"angle_deg":180,"glyph":"☍","traditionelle_qualitaet":"Spannungsreich und ausgleichsfordernd; betont Gegenüberstellung, Spiegelung und Verhandlung zwischen zwei Polen.","orb":{"modern_typisch":"etwa 8 bis 10 Grad","spanne":"etwa 5 bis 10 Grad, je nach Schule und beteiligten Faktoren","schulhinweis":"Traditionelle Schulen arbeiten enger, psychologische weiter. Die Achsenhäuser sind oft aussagekräftiger als der reine Winkel [S17]."},"common_misreading":"Die Opposition wird oft als sichere Trennung oder Feindschaft gelesen. Tradiert ist sie eine Polarität, die Dialog und Ausgleich verlangt und beide Seiten sichtbar macht."}];

export const GRUNDLAGEN = [{"id":"grund-begriff","slug":"was-astrologie-ist","name":"Was Astrologie ist","title":"Was Astrologie ist - und was sie nicht ist","level":"grundlagen","short":"Astrologie ist ein historisches Deutungssystem, das Himmelskörperpositionen als Zeichen für irdische und menschliche Zusammenhänge liest. Sie ist keine Astronomie und keine wissenschaftlich bestätigte Wirkungstheorie.","long":"Astrologie ist eine Form der Divination: Sie deutet die Positionen und Bewegungen von Sonne, Mond, Planeten und Sternen als Zeichen für irdische und menschliche Zusammenhänge [S07]. Der Bezug auf den Himmel macht sie nicht zu einer Naturwissenschaft. Astronomie beschreibt, was Himmelskörper sind und wie sie sich bewegen; Astrologie ordnet diesen Bewegungen Bedeutungen zu. Beide nutzen teilweise dieselben Beobachtungen, verfolgen aber verschiedene Ziele.\n\nHistorisch wurde Astrologie lange als ernsthafte Wissensform behandelt und war mit Mathematik, Kalenderkunde und Medizin verbunden. In der modernen Wissenschaft gilt sie als Pseudoscience, weil ihre Wirkbehauptungen in kontrollierten Studien nicht bestanden haben und kein plausibler Mechanismus bekannt ist [S06][S07][S09]. Das heißt nicht, dass historische Texte wertlos sind oder dass Menschen keine sinnvollen Erfahrungen mit astrologischen Symbolen machen können. Es heißt, dass die Behauptung, Himmelskörper würden Persönlichkeit oder Ereignisse verursachen, nicht durch Evidenz gestützt ist.\n\nDieses Paket behandelt Astrologie deshalb als Kultur- und Deutungstradition. Es erklärt, wie die Tradition aufgebaut ist, welche Regeln sie verwendet und woher ihre Bilder kommen. Es behauptet nicht, dass diese Regeln die Welt kausal erklären. Wer Astrologie nutzt, sollte den Unterschied zwischen einem interessanten Deutungsangebot und einer Tatsachenbehauptung kennen.\n\nDie wichtigste Arbeitshaltung: Neugier auf das Symbolsystem, Klarheit über den Geltungsanspruch, Respekt vor Menschen, die astrologische Sprache für Selbstreflexion nutzen, und Skepsis gegenüber jeder Aussage, die mit Sicherheit Gesundheit, Geld, Beziehungen oder Zukunft vorhersagt.","keywords":["Divination","Deutungssystem","Astronomie","Pseudoscience","Geltungsanspruch"],"sources":["S06","S07","S09"],"claims":["c17","c19","c23"],"cross_refs":["grund-geschichte","grund-evidenz","grund-ethik","grund-ekliptik"],"kennzeichnung":{"typ":"gemischt","hinweis":"Historische und wissenschaftliche Einordnung sind belegt; die Nutzung als Reflexionssprache ist eine redaktionelle Entscheidung."},"key_points":["Astrologie ist ein Deutungssystem, keine Astronomie.","Die moderne Wissenschaft ordnet astrologische Wirkbehauptungen als nicht belegt ein.","Kulturelle und reflexive Nutzung ist möglich, ohne die Wirkbehauptung zu übernehmen."]},{"id":"grund-geschichte","slug":"geschichte","name":"Geschichte","title":"Kurze Geschichte der Astrologie","level":"grundlagen","short":"Die Astrologie entstand aus mesopotamischer Himmelsomen-Deutung, wurde in hellenistischer Zeit horoskopbasiert und verbreitete sich über Indien, den islamischen Raum und Europa.","long":"Die frühesten Vorläufer liegen in Mesopotamien: Himmelserscheinungen wurden als Omen für Herrscher, Ernten, Kriege und Naturereignisse gedeutet. Diese Omen-Astrologie war zunächst stärker kollektiv und königlich geprägt als individuell [S07]. In der hellenistischen Zeit entstand die horoskopbasierte Astrologie, die den Himmel auf den Geburtszeitpunkt einer Person bezog. Der Begriff Horoskop kommt vom griechischen horoskopos, dem Stundenmarkierer beziehungsweise Aszendenten [S22].\n\nPtolemaios verfasste im 2. Jahrhundert n. Chr. die Tetrabiblos, eine einflussreiche systematische Darstellung der Astrologie, die über das Mittelalter und die frühe Neuzeit weiterwirkte. Über Handels- und Gelehrtennetzwerke gelangte astrologisches Wissen nach Indien, in den islamischen Raum und nach Europa; regionale Traditionen entwickelten eigene Systeme, etwa die vedische Astrologie mit siderischem Bezug [S07][S13].\n\nIn Europa war Astrologie bis in die frühe Neuzeit Teil von Universitäts- und Hofkultur. Mit der wissenschaftlichen Revolution verschob sich die Grenze: Astronomie wurde mathematisch-empirisch, Astrologie blieb ein Deutungssystem. Im 20. Jahrhundert entstand die psychologische Astrologie, die Zeichen und Planeten als Persönlichkeits- und Entwicklungsbilder las. Gleichzeitig wurde die Zeitungshoroskop-Kultur massenwirksam [S07].\n\nFür den Einstieg reicht diese grobe Linie. Wichtig ist, dass Astrologie keine einheitliche Lehre ist: Unterschiedliche Epochen und Regionen verwenden verschiedene Zeichen, Häuser, Aspekte und Herrschaftsregeln. Wer von der Astrologie spricht, sollte sagen, welche Tradition gemeint ist.","keywords":["Mesopotamien","Hellenismus","Ptolemaios","Indien","psychologische Astrologie"],"sources":["S07","S22","S13"],"claims":["c22","c23","c03"],"cross_refs":["grund-begriff","grund-tropisch-siderisch","grund-herrschaft"],"kennzeichnung":{"typ":"historisch","hinweis":"Grobe Entwicklungslinie nach Enzyklopädie und Tertiärquelle; regionale und schulische Unterschiede sind vielfältiger."},"key_points":["Vorläufer in Mesopotamien, horoskopbasierte Form in hellenistischer Zeit.","Ptolemaios und die Tetrabiblos prägten die europäische Überlieferung.","Astrologie ist historisch und regional vielfältig, keine einheitliche Lehre."]},{"id":"grund-ekliptik","slug":"ekliptik-und-himmelssphaere","name":"Ekliptik","title":"Ekliptik, Himmelssphäre und geozentrische Perspektive","level":"grundlagen","short":"Die Ekliptik ist die scheinbare Jahresbahn der Sonne am Himmel. Die Astrologie beschreibt Positionen von der Erde aus, also geozentrisch, ohne damit ein geozentrisches Weltbild zu behaupten.","long":"Von der Erde aus betrachtet wandert die Sonne im Laufe eines Jahres scheinbar durch eine Reihe von Sternbildern. Diese scheinbare Bahn heißt Ekliptik. Sie ist die Projektion der Erdbahn auf die gedachte Himmelssphäre. Der Zodiak ist ein Gürtel von etwa 8 Grad nördlich und südlich der Ekliptik, in dem Sonne, Mond und die hellen Planeten überwiegend erscheinen [S14].\n\nDie Ekliptik ist gegen den Himmelsäquator geneigt, weil die Erdachse um etwa 23,4 Grad gekippt ist [S01]. Diese Neigung erzeugt die Jahreszeiten und die unterschiedlichen Tageslängen. Der Frühlingspunkt, an dem die Sonne den Himmelsäquator nach Norden kreuzt, ist der Nullpunkt des tropischen Tierkreises.\n\nGeozentrisch bedeutet in der Astrologie: Die Positionen werden so beschrieben, wie sie von einem Ort auf der Erde aus erscheinen. Das ist keine Behauptung, die Erde stehe im Zentrum des Sonnensystems. Die Planeten umlaufen die Sonne; ihre scheinbaren Bewegungen am Himmel entstehen aus der Kombination von Erdrotation, Erdbahn und Planetenbahnen [S15].\n\nFür die Deutung ist diese Perspektive konstitutiv: Ein Horoskop ist eine Karte des Himmels von einem bestimmten Ort zu einer bestimmten Zeit. Ohne Ort und Zeit keine Häuser und keine Achsen. Wer astronomische und astrologische Aussagen vergleicht, sollte deshalb immer fragen, ob von einer beobachteten Position, einer berechneten Bahn oder einer zugeordneten Bedeutung die Rede ist.","keywords":["Ekliptik","Himmelssphäre","geozentrisch","Frühlingspunkt","Zodiak"],"sources":["S14","S01","S15"],"claims":["c04","c25","c02"],"cross_refs":["grund-tropisch-siderisch","grund-zeichen-sternbilder","grund-aszendent-mc"],"kennzeichnung":{"typ":"astronomie","hinweis":"Geometrische und astronomische Grundlagen; die astrologische Nutzung dieser Punkte ist eine separate Konvention."},"key_points":["Die Ekliptik ist die scheinbare Sonnenbahn, nicht die Erdbahn selbst.","Geozentrisch meint den Beobachtungsstandpunkt, nicht ein Weltbild.","Der Zodiak ist ein Gürtel um die Ekliptik, kein einzelnes Sternbild."]},{"id":"grund-tropisch-siderisch","slug":"tropisch-und-siderisch","name":"Tropisch und siderisch","title":"Tropischer und siderischer Tierkreis","level":"vertiefung","short":"Tropische Astrologie rechnet ab dem Frühlingspunkt, siderische Astrologie ab einem sternbezogenen Nullpunkt. Beide teilen die Ekliptik in zwölf Zeichen, meinen aber unterschiedliche Bezugssysteme.","long":"Der tropische Tierkreis beginnt am Frühlings-Äquinoktium und teilt die Ekliptik in zwölf gleiche Sektoren von 30 Grad. Die Zeichen sind damit an den Jahreszeiten orientiert, nicht an den sichtbaren Sternbildern [S13][S19]. Das ist die in der westlichen Astrologie übliche Konvention und die Arbeitsannahme dieses Pakets.\n\nDer siderische Tierkreis orientiert sich an der Position der Sterne. Weil die Erdachse präzediert, verschiebt sich der Frühlingspunkt langsam gegenüber dem Sternhintergrund, etwa um ein Grad in 72 Jahren [S13]. Siderische Systeme korrigieren diese Verschiebung mit einem Ayanamsa genannten Wert. In der vedischen Astrologie ist der Lahiri-Ayanamsa verbreitet; weitere Systeme existieren [S13].\n\nDie Folge: Derselbe Himmelskörper kann tropisch in einem anderen Zeichen stehen als siderisch. Die Differenz ist nicht willkürlich, sondern folgt aus dem gewählten Nullpunkt. Sie ist heute schulabhängig und wird hier nicht als fester Gradwert behauptet, weil verschiedene Ayanamsas verschiedene Werte liefern [S13].\n\nFür den Einstieg gilt: Man sollte tropische und siderische Aussagen nicht unmarkiert mischen. Ein Text, der von Widder spricht, meint im tropischen System den Sektor ab dem Frühlingspunkt; im siderischen System meint er einen anderen Abschnitt des Himmels. Beide Systeme können intern konsistent sein. Die Frage, welches richtig ist, ist eine Frage der Tradition und des Zwecks, nicht der Astronomie allein.","keywords":["tropisch","siderisch","Ayanamsa","Lahiri","Frühlingspunkt"],"sources":["S13","S19","S06"],"claims":["c02","c03","c06"],"cross_refs":["grund-zeichen-sternbilder","grund-ekliptik","zeichen-widder"],"kennzeichnung":{"typ":"konvention","hinweis":"Definitionen und Präzessionsfolge sind belegt; die Wahl des Systems ist eine Tradition, keine Naturtatsache."},"key_points":["Tropisch rechnet ab dem Frühlingspunkt, siderisch ab einem sternbezogenen Nullpunkt.","Ayanamsa-Werte korrigieren die Präzession, sind aber schulabhängig.","Systeme nicht unmarkiert mischen."]},{"id":"grund-zeichen-sternbilder","slug":"zeichen-und-sternbilder","name":"Zeichen vs. Sternbilder","title":"Warum Zeichen und Sternbilder nicht dasselbe sind","level":"vertiefung","short":"Tierkreiszeichen sind 30-Grad-Sektoren; Sternbilder sind ungleiche Areale mit IAU-Grenzen. Wegen der Präzession liegt der Frühlingspunkt heute nicht mehr im Sternbild Widder.","long":"Die zwölf Tierkreiszeichen sind keine Sternbilder. Ein Zeichen ist ein Sektor von genau 30 Grad auf der Ekliptik; ein Sternbild ist ein historisch definiertes Areal am Himmel mit sehr unterschiedlicher Größe und Form. Die IAU kennt 88 Sternbilder mit seit 1928/1930 festen Grenzen [S04]. Zwölf davon liegen entlang der Ekliptik, dazu kommt Ophiuchus, der Schlangenträger [S05][S14].\n\nDie tropischen Zeichen beginnen am Frühlingspunkt. Dieser Punkt verschiebt sich durch die Präzession der Erdachse langsam rückwärts durch den Tierkreis, etwa 0,014 Grad pro Jahr beziehungsweise ein Grad in rund 72 Jahren [S01][S13]. Deshalb liegt der Frühlingspunkt heute im Bereich der Fische, nicht im Sternbild Widder. Die Sonne steht in den heutigen Kalendermonaten auch in anderen Sternbildern als in den Zeichen, die ihnen historisch zugeordnet wurden.\n\nDas ist kein Fehler der Astrologie im Sinne eines Rechenfehlers: Das tropische System definiert seine Zeichen bewusst über die Jahreszeiten und nicht über die Sternbilder [S13][S19]. Der häufig zitierte Satz, die NASA habe den Tierkreis geändert, ist eine Verwechslung. Die NASA hat auf die Differenz zwischen Astronomie und Astrologie hingewiesen; sie hat kein astrologisches System umgestellt [S05][S06].\n\nWer die sichtbaren Sternbilder als Bezug nehmen will, landet bei der siderischen Astrologie. Wer die Jahreszeiten als Bezug nimmt, bleibt beim tropischen System. Beides sind Konventionen mit unterschiedlichen Nullpunkten. Wichtig ist, den Unterschied zu benennen, statt Zeichen und Sternbilder als dasselbe zu behandeln.","keywords":["Präzession","Ophiuchus","IAU","Sternbilder","Frühlingspunkt"],"sources":["S01","S04","S05","S06","S13","S14","S19"],"claims":["c01","c05","c02","c03"],"cross_refs":["grund-tropisch-siderisch","grund-ekliptik","zeichen-fische"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Fakten und Definitionsunterschiede sind belegt; die Bewertung als Fehler oder Nichtfehler ist eine Interpretationsfrage."},"key_points":["Zeichen sind 30-Grad-Sektoren, Sternbilder sind ungleiche Areale.","Die Präzession verschiebt den Frühlingspunkt gegenüber den Sternbildern.","Tropische und siderische Systeme setzen verschiedene Nullpunkte."]},{"id":"element-feuer","slug":"element-feuer","name":"Feuer","title":"Element Feuer","level":"grundlagen","short":"Feuer steht in der Elementlehre für Wärme, Bewegung, Begeisterung und Ausstrahlung. Die Zeichen Widder, Löwe und Schütze werden ihm zugeordnet.","long":"Feuer ist eines der vier klassischen Elemente der abendländischen Naturphilosophie und in der Astrologie eine Deutungsqualität. Ihm werden Wärme, Bewegung, Begeisterung, Mut und Ausstrahlung zugeordnet. Die drei Feuerzeichen sind Widder (kardinal), Löwe (fix) und Schütze (veränderlich) [S14][S12].\n\nDie Elementlehre ist keine Physik. Sie beschreibt keine Stoffe im modernen Sinn, sondern eine symbolische Qualität: Wie richtet sich etwas nach außen, wie wird Energie sichtbar, wie schnell entzündet sich etwas? Feuer kann wärmen, erhellen und antreiben, aber auch verbrennen und verbrauchen. Diese Ambivalenz gehört zur Deutung.\n\nFeuerzeichen werden traditionell mit Initiative, Selbstausdruck und Begeisterungsfähigkeit verbunden. Ein Mensch mit vielen Feuerzeichen kann als temperamentvoll, direkt oder optimistisch erscheinen; das ist eine Typisierung, keine Messung. Entscheidend ist immer die Kombination mit Mond, Aszendent, Häusern und Aspekten. Einzelne Zeichen oder Elemente reichen nicht für eine Persönlichkeitsaussage.\n\nFür den Einstieg hilft eine einfache Frage: Wo im Horoskop zeigt sich Feuer, und was macht es mit der Energie? Feuer in einem Winkelhaus kann präsenter wirken als Feuer in einem späten Haus. Die Elementlehre ist ein Vergleichswerkzeug, kein Etikett.","keywords":["Feuer","Wärme","Begeisterung","Widder","Löwe","Schütze"],"sources":["S14","S12"],"claims":["c02","c07","c12"],"cross_refs":["zeichen-widder","zeichen-loewe","zeichen-schuetze","modalitaet-kardinal"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Elementlehre ist eine symbolische Tradition; sie beschreibt keine physikalischen Stoffe oder messbaren Eigenschaften."},"key_points":["Feuer ist eine symbolische Qualität, keine Physik.","Widder, Löwe und Schütze sind die drei Feuerzeichen.","Elemente sind Vergleichswerkzeuge, keine Persönlichkeitsdiagnosen."]},{"id":"element-erde","slug":"element-erde","name":"Erde","title":"Element Erde","level":"grundlagen","short":"Erde steht für Konkretes, Bestand, Körperbezug und praktische Umsetzung. Die Zeichen Stier, Jungfrau und Steinbock werden ihr zugeordnet.","long":"Erde ist das Element der Konkretisierung. In der Astrologie werden ihm Bestand, Verlässlichkeit, Körperbezug, Sinnlichkeit und praktische Umsetzung zugeordnet. Die drei Erdzeichen sind Stier (fix), Jungfrau (veränderlich) und Steinbock (kardinal) [S14][S12].\n\nDie Erdqualität fragt: Was hält? Was ist brauchbar? Was kann getestet werden? Erde ist langsamer als Feuer oder Luft, aber oft belastbarer. Sie kann als bodenständig, geduldig und realistisch erscheinen, aber auch als schwerfällig, besitzorientiert oder übervorsichtig. Wie bei allen Elementen ist die Ambivalenz Teil der Deutung.\n\nErde ist kein moralischer Wert. Die Tradition neigt dazu, Erdzeichen mit Vernunft und Feuerzeichen mit Impuls zu verbinden; das sind kulturelle Zuordnungen, keine Naturgesetze. Ein Erdzeichen kann impulsiv sein, wenn andere Faktoren es tragen; ein Feuerzeichen kann sehr praktisch sein. Die Elementlehre beschreibt Schwerpunkte, keine Ausschließlichkeiten.\n\nFür die Radixdeutung ist interessant, wo Erde fehlt oder überbetont ist. Ein Mangel an Erde kann als Schwierigkeit mit Alltag, Körper oder Verlässlichkeit gelesen werden; eine Überbetonung als Tendenz, sich in Sicherheit oder Kontrolle zurückzuziehen. Auch das sind Deutungsangebote, keine Befunde.","keywords":["Erde","Bestand","Körper","Praxis","Stier","Jungfrau","Steinbock"],"sources":["S14","S12"],"claims":["c02","c07","c12"],"cross_refs":["zeichen-stier","zeichen-jungfrau","zeichen-steinbock","modalitaet-fix"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Elementlehre ist eine symbolische Tradition; keine medizinischen oder materiellen Tatsachenbehauptungen."},"key_points":["Erde steht für Konkretisierung und Bestand.","Stier, Jungfrau und Steinbock sind die drei Erdzeichen.","Erdzuordnung ist kein moralischer oder medizinischer Befund."]},{"id":"element-luft","slug":"element-luft","name":"Luft","title":"Element Luft","level":"grundlagen","short":"Luft steht für Wahrnehmung, Austausch, Abstraktion und Distanz. Die Zeichen Zwillinge, Waage und Wassermann werden ihr zugeordnet.","long":"Luft ist das Element des Austauschs und der Abstraktion. In der Astrologie werden ihm Wahrnehmung, Sprache, Denken, Beziehung und Distanz zugeordnet. Die drei Luftzeichen sind Zwillinge (veränderlich), Waage (kardinal) und Wassermann (fix) [S14][S12].\n\nLuft fragt: Wie wird etwas wahrgenommen, benannt und geteilt? Sie kann beweglich, neugierig und vermittelnd wirken, aber auch distanziert, zerstreut oder übermäßig prinzipienorientiert. Luft ist nicht automatisch intelligent und Feuer nicht automatisch mutig; die Elemente beschreiben Stile, keine Begabungen.\n\nIn der traditionellen Elementlehre bildet Luft mit Feuer die aktiven, mit Wasser und Erde die empfangenderen Qualitäten; diese Polarität ist historisch und kulturell geprägt. Sie kann als Orientierung dienen, sollte aber nicht als starre Geschlechter- oder Charakterordnung gelesen werden.\n\nFür die Deutung ist die Verbindung von Luft und Kommunikation wichtig: Luftzeichen werden oft mit Sprache, Netzwerken und Perspektivwechsel verbunden. Ein Horoskop mit vielen Luftzeichen kann einen Menschen zeigen, der viel denkt und spricht; ob das als Offenheit oder als Flucht in Distanz erlebt wird, entscheiden die anderen Faktoren.","keywords":["Luft","Austausch","Denken","Distanz","Zwillinge","Waage","Wassermann"],"sources":["S14","S12"],"claims":["c02","c07","c12"],"cross_refs":["zeichen-zwillinge","zeichen-waage","zeichen-wassermann","modalitaet-veraenderlich"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Elementlehre ist eine symbolische Tradition; keine Aussage über Intelligenz oder Charakter."},"key_points":["Luft steht für Wahrnehmung, Sprache und Austausch.","Zwillinge, Waage und Wassermann sind die drei Luftzeichen.","Luft ist kein Maß für Intelligenz."]},{"id":"element-wasser","slug":"element-wasser","name":"Wasser","title":"Element Wasser","level":"grundlagen","short":"Wasser steht für Gefühl, Bindung, Durchlässigkeit und Erinnerung. Die Zeichen Krebs, Skorpion und Fische werden ihm zugeordnet.","long":"Wasser ist das Element der Bindung und der Durchlässigkeit. In der Astrologie werden ihm Gefühl, Erinnerung, Nähe, Schutz und die Fähigkeit zugeordnet, Atmosphären wahrzunehmen. Die drei Wasserzeichen sind Krebs (kardinal), Skorpion (fix) und Fische (veränderlich) [S14][S12].\n\nWasser fragt: Was berührt mich, was bindet mich, wo bin ich durchlässig? Es kann empathisch, tief und schützend wirken, aber auch in Rückzug, Verschmelzung oder Kontrolle kippen. Wasser ist nicht automatisch emotionaler als andere Elemente; es beschreibt eine Art der Bezogenheit.\n\nDie traditionelle Zuordnung von Wasser zu Gefühlen ist kulturell verstärkt. In der Deutung ist wichtig, zwischen Empfindung und Ausdruck zu unterscheiden: Ein Mensch mit wenig Wasser kann sehr gefühlvoll sein, aber anders sprechen; ein Mensch mit viel Wasser kann Gefühle zurückhalten, um nicht verletzlich zu sein. Die Elementlehre ist ein Zugang, kein Test.\n\nFür die Radixdeutung ist die Frage nach Grenzen zentral: Wo fließt etwas zusammen, und wo braucht es ein Ufer? Wasser ohne Begrenzung kann überfluten; Wasser mit klaren Ufern kann tragen. Diese Metapher ist Tradition, keine psychologische Diagnose.","keywords":["Wasser","Gefühl","Bindung","Durchlässigkeit","Krebs","Skorpion","Fische"],"sources":["S14","S12"],"claims":["c02","c07","c12"],"cross_refs":["zeichen-krebs","zeichen-skorpion","zeichen-fische","modalitaet-kardinal"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Elementlehre ist eine symbolische Tradition; keine psychologische oder medizinische Diagnose."},"key_points":["Wasser steht für Bindung, Empfindung und Durchlässigkeit.","Krebs, Skorpion und Fische sind die drei Wasserzeichen.","Wasser ist kein Maß für Emotionalität oder Gesundheit."]},{"id":"modalitaet-kardinal","slug":"modalitaet-kardinal","name":"Kardinal","title":"Modalität kardinal","level":"grundlagen","short":"Kardinalzeichen beginnen mit den Jahreszeiten und werden traditionell mit Initiative, Anfang und Richtungsgebung verbunden: Widder, Krebs, Waage, Steinbock.","long":"Die Modalitäten teilen die zwölf Zeichen in drei Gruppen von je vier. Kardinal sind die Zeichen, die an den Sonnenwenden und Äquinoktien beginnen: Widder, Krebs, Waage und Steinbock [S14]. In der Deutung werden sie mit Anfang, Initiative und Richtungsgebung verbunden.\n\nKardinal bedeutet nicht automatisch Führung oder Erfolg. Die Tradition beschreibt eine Bewegung, die etwas in Gang setzt: ein Projekt beginnen, eine Beziehung initiieren, eine Struktur aufbauen, eine Entscheidung treffen. Kardinalzeichen können entschlossen wirken, aber auch ungeduldig oder dominant, wenn andere nicht mitziehen.\n\nDie Modalität ist eine formale Einteilung, keine Persönlichkeitseigenschaft. Sie wird erst im Zusammenspiel mit Element, Haus und Aspekten aussagekräftig. Ein kardinales Feuerzeichen (Widder) wirkt anders als ein kardinales Wasserzeichen (Krebs) oder ein kardinales Erdzeichen (Steinbock). Die Modalität beschreibt den Rhythmus, das Element die Qualität.\n\nFür den Einstieg hilft die Frage: Wo beginnt jemand etwas, und wo beginnt er immer wieder neu, ohne zu Ende zu kommen? Kardinalität kann ein Motor sein, aber auch eine Schleife.","keywords":["kardinal","Initiative","Anfang","Widder","Krebs","Waage","Steinbock"],"sources":["S14"],"claims":["c02","c07"],"cross_refs":["zeichen-widder","zeichen-krebs","zeichen-waage","zeichen-steinbock","element-feuer"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Modalitäteneinteilung ist eine astrologische Konvention; die Deutung als Initiative ist Tradition."},"key_points":["Kardinalzeichen beginnen an den Jahreszeitenpunkten.","Kardinal meint Initiative, nicht automatisch Führung.","Die Modalität wirkt nur im Zusammenspiel mit Element und Kontext."]},{"id":"modalitaet-fix","slug":"modalitaet-fix","name":"Fix","title":"Modalität fix","level":"grundlagen","short":"Fixzeichen liegen in der Mitte der Jahreszeiten und werden traditionell mit Dauer, Stabilität und Beharrlichkeit verbunden: Stier, Löwe, Skorpion, Wassermann.","long":"Fix sind die Zeichen in der Mitte der Jahreszeiten: Stier, Löwe, Skorpion und Wassermann [S14]. In der Deutung werden sie mit Dauer, Stabilität, Beharrlichkeit und der Fähigkeit verbunden, etwas zu halten.\n\nFix bedeutet nicht automatisch Starrheit. Die Tradition beschreibt eine Kraft, die Bestand gibt: Eine Entscheidung wird durchgehalten, eine Beziehung gepflegt, ein Wert verteidigt. Fixzeichen können verlässlich wirken, aber auch schwer zu bewegen sein, wenn Veränderung nötig ist.\n\nDie Modalität ist eine formale Einteilung. Ein fixes Feuerzeichen (Löwe) wirkt anders als ein fixes Wasserzeichen (Skorpion) oder ein fixes Luftzeichen (Wassermann). Die Fixqualität beschreibt den Rhythmus, in dem etwas gehalten wird; das Element beschreibt, was gehalten wird.\n\nFür den Einstieg hilft die Frage: Was halte ich fest, und dient das noch? Fixierung kann Schutz sein oder Gefangenschaft. Die Deutung sollte beides sehen.","keywords":["fix","Dauer","Stabilität","Stier","Löwe","Skorpion","Wassermann"],"sources":["S14"],"claims":["c02","c07"],"cross_refs":["zeichen-stier","zeichen-loewe","zeichen-skorpion","zeichen-wassermann","element-erde"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Modalitäteneinteilung ist eine astrologische Konvention; die Deutung als Dauer ist Tradition."},"key_points":["Fixzeichen liegen in der Mitte der Jahreszeiten.","Fix meint Dauer und Beharrlichkeit, nicht automatisch Starrheit.","Fixierung kann Schutz oder Gefangenschaft sein."]},{"id":"modalitaet-veraenderlich","slug":"modalitaet-veraenderlich","name":"Veränderlich","title":"Modalität veränderlich","level":"grundlagen","short":"Veränderliche Zeichen enden die Jahreszeiten und werden traditionell mit Anpassung, Übergang und Auflösung verbunden: Zwillinge, Jungfrau, Schütze, Fische.","long":"Veränderlich sind die Zeichen am Ende der Jahreszeiten: Zwillinge, Jungfrau, Schütze und Fische [S14]. In der Deutung werden sie mit Anpassung, Übergang, Flexibilität und der Fähigkeit verbunden, zwischen Zuständen zu vermitteln.\n\nVeränderlich bedeutet nicht automatisch Unzuverlässigkeit. Die Tradition beschreibt eine Bewegung, die sich anpasst und löst: Ein Muster wird verabschiedet, eine Form wird verändert, ein Übergang wird gestaltet. Veränderliche Zeichen können flexibel und lernbereit wirken, aber auch zerstreut oder flüchtig, wenn sie keine Richtung finden.\n\nDie Modalität ist eine formale Einteilung. Ein veränderliches Feuerzeichen (Schütze) wirkt anders als ein veränderliches Erdzeichen (Jungfrau) oder ein veränderliches Wasserzeichen (Fische). Die Modalität beschreibt den Rhythmus des Übergangs; das Element beschreibt, was übergeht.\n\nFür den Einstieg hilft die Frage: Was löst sich gerade auf, und was entsteht daraus? Veränderung kann Befreiung sein oder Orientierungslosigkeit. Die Deutung sollte beides benennen.","keywords":["veränderlich","Anpassung","Übergang","Zwillinge","Jungfrau","Schütze","Fische"],"sources":["S14"],"claims":["c02","c07"],"cross_refs":["zeichen-zwillinge","zeichen-jungfrau","zeichen-schuetze","zeichen-fische","element-luft"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Modalitäteneinteilung ist eine astrologische Konvention; die Deutung als Anpassung ist Tradition."},"key_points":["Veränderliche Zeichen enden die Jahreszeiten.","Veränderlich meint Anpassung und Übergang, nicht automatisch Unzuverlässigkeit.","Übergänge können Befreiung oder Orientierungslosigkeit bedeuten."]},{"id":"grund-herrschaft","slug":"herrschaft-und-wuerden","name":"Herrschaft","title":"Herrschersysteme und Würden","level":"vertiefung","short":"Die traditionelle Herrschaftslehre ordnet die Zeichen den sieben sichtbaren Himmelskörpern zu; moderne Systeme ergänzen Uranus, Neptun und Pluto. Die Zuordnungen sind Konventionen.","long":"In der traditionellen Astrologie hat jedes Zeichen einen Herrscher. Die ältere Lehre verwendet die sieben mit bloßem Auge sichtbaren Himmelskörper: Sonne, Mond, Merkur, Venus, Mars, Jupiter und Saturn [S12]. Daraus ergibt sich die klassische Zuordnung: Widder und Skorpion zu Mars, Stier und Waage zu Venus, Zwillinge und Jungfrau zu Merkur, Krebs zum Mond, Löwe zur Sonne, Schütze und Fische zu Jupiter, Steinbock und Wassermann zu Saturn.\n\nMit der Entdeckung der äußeren Planeten wurden moderne Zuordnungen ergänzt: Uranus für Wassermann, Neptun für Fische, Pluto für Skorpion. Diese Ergänzungen sind Konventionen des 19. und 20. Jahrhunderts, keine antiken Setzungen [S12]. Viele Astrologinnen und Astrologen verwenden traditionelle und moderne Herrscher nebeneinander, oft mit unterschiedlicher Gewichtung.\n\nDas System der Würden beschreibt, wie gut ein Planet in einem Zeichen steht. Domizil bedeutet: Der Planet steht in einem Zeichen, das er regiert. Exil bedeutet das Gegenteil; Erhöhung und Fall sind weitere Abstufungen. Die Tradition nennt dies essentielle Würden. Sie sind ein Bewertungssystem innerhalb der Astrologie, keine messbare Eigenschaft [S12].\n\nFür den Einstieg reicht: Herrschaft ist eine Verweisstruktur. Sie sagt, welcher Planet für ein Zeichen oder eine Hausspitze zuständig ist und wo man weitersuchen kann. Sie sagt nicht, dass ein Mensch von einem Planeten bestimmt wird. Die Wahl zwischen traditionellen und modernen Herrschern sollte im Text sichtbar gemacht werden.","keywords":["Herrscher","Domizil","Exil","Würden","Uranus","Pluto"],"sources":["S12","S10"],"claims":["c12","c26","c13"],"cross_refs":["grund-haeuser-systeme","faktor-saturn","faktor-uranus","faktor-pluto"],"kennzeichnung":{"typ":"konvention","hinweis":"Herrschafts- und Würdenlehre sind astrologische Konventionen; moderne Zuordnungen sind historisch jünger."},"key_points":["Traditionell regieren sieben sichtbare Himmelskörper die Zeichen.","Uranus, Neptun und Pluto sind moderne Ergänzungen.","Würden sind ein internes Bewertungssystem, keine Messgröße."]},{"id":"grund-aspekt-orben","slug":"aspekte-und-orben","name":"Aspekte und Orben","title":"Aspekte, Winkel und Orben","level":"vertiefung","short":"Aspekte sind Winkelbeziehungen zwischen Faktoren. Die fünf Hauptaspekte sind Konjunktion, Sextil, Quadrat, Trigon und Opposition; Orben legen fest, wie genau ein Winkel sein muss.","long":"Ein Aspekt ist eine Winkelbeziehung zwischen zwei Faktoren im Horoskop, oft zwischen Planeten, aber auch zu Aszendent oder MC [S11]. Die fünf Hauptaspekte sind Konjunktion (0 Grad), Sextil (60 Grad), Quadrat (90 Grad), Trigon (120 Grad) und Opposition (180 Grad). Weitere Aspekte wie Halbsextil (30 Grad) oder Quincunx (150 Grad) gelten als Neben- oder Minoraspekte.\n\nEin Aspekt muss nicht exakt sein. Der Orbis ist die zulässige Abweichung: Ein Quadrat bei 87 Grad kann noch als Quadrat gelten, wenn der Orbis 3 Grad beträgt. Orben sind Konventionen. Moderne psychologische Astrologie neigt zu weiteren Orben, Horary und traditionelle Schulen zu engeren; Sonne und Mond erhalten oft größere Spielräume als die äußeren Planeten [S11][S17].\n\nNeben dem Winkel sind weitere Unterscheidungen üblich: Ein applikativer Aspekt wird enger, ein separater weiter. Ein partiler Aspekt ist fast exakt. Ein Aspekt kann außerhalb der Zeichen liegen, obwohl der Winkel stimmt (out-of-sign oder dissociate); manche Schulen gewichten ihn dann schwächer. Diese Regeln sind nicht einheitlich [S17].\n\nWichtig ist die Trennung von Geometrie und Deutung: Der Winkel ist berechenbar, die Bedeutung ist Tradition. Ein Quadrat ist nicht automatisch schlecht, ein Trigon nicht automatisch gut. Die Qualität hängt von den beteiligten Faktoren, ihren Zeichen, Häusern und dem Kontext ab. Wer Orben als Naturgesetze behandelt, verwechselt eine Fachkonvention mit einer Messung.","keywords":["Aspekt","Orbis","applikativ","separativ","partil","Hauptaspekte"],"sources":["S11","S17"],"claims":["c10","c11"],"cross_refs":["aspekt-konjunktion","aspekt-sextil","aspekt-quadrat","aspekt-trigon","aspekt-opposition"],"kennzeichnung":{"typ":"konvention","hinweis":"Winkel sind definiert; Orben und Bewertungen sind schulabhängige Konventionen."},"key_points":["Fünf Hauptaspekte: 0, 60, 90, 120 und 180 Grad.","Orben sind Konventionen, keine Naturkonstanten.","Winkelgeometrie und Deutung sind zu trennen."]},{"id":"grund-haeuser-systeme","slug":"haeusersysteme","name":"Häusersysteme","title":"Häuser und Häusersysteme","level":"vertiefung","short":"Häuser sind zeit- und ortsabhängige Lebensfelder. Es gibt mehrere Systeme; Placidus ist im modernen Westen verbreitet, Equal House teilt ab dem Aszendenten in 30-Grad-Schritten.","long":"Häuser teilen das Horoskop in zwölf Felder, die von der Geburtszeit und vom Geburtsort abhängen. Sie beschreiben Lebensbereiche wie Identität, Ressourcen, Kommunikation, Herkunft, Kreativität, Arbeit, Partnerschaft, gemeinsame Ressourcen, Sinn, Beruf, Netzwerk und Rückzug [S10]. Die Häuser sind damit etwas anderes als die Zeichen: Zeichen sind am Himmel orientiert, Häuser an der lokalen Perspektive.\n\nEs gibt verschiedene Häusersysteme. Equal House teilt die Ekliptik vom Aszendenten aus in zwölf gleiche Abschnitte von 30 Grad. Ganzzeichen-Häuser ordnen jedem Haus ein volles Zeichen zu, beginnend mit dem Zeichen des Aszendenten. Placidus ist ein zeitbasiertes Quadrantensystem und im modernen Westen verbreitet; Koch, Campanus, Regiomontanus und andere Systeme existieren ebenfalls [S10][S16].\n\nDie Systeme liefern unterschiedliche Hausspitzen und damit unterschiedliche Zuordnungen von Planeten zu Häusern. Kein System ist wissenschaftlich als das richtige erwiesen; die Wahl ist eine Fachkonvention. Placidus ist jenseits der Polarkreise nicht durchgehend definiert, weil bestimmte Grade zirkumpolar sind und nie den Horizont berühren [S10]. In hohen Breiten werden deshalb oft Equal House oder Ganzzeichen-Häuser verwendet.\n\nFür die Deutung ist Transparenz wichtig: Ein Text sollte nennen, welches System verwendet wird. Wer zwei Horoskope vergleicht, sollte nicht unbemerkt das System wechseln. Die Hausdeutung selbst ist Tradition; die geometrische Konstruktion ist berechenbar, die Bedeutung der Felder nicht.","keywords":["Häuser","Placidus","Equal House","Ganzzeichen","Polarkreis"],"sources":["S10","S16"],"claims":["c08","c09","c26"],"cross_refs":["grund-aszendent-mc","haus-1","haus-10","grund-radix-synthese"],"kennzeichnung":{"typ":"konvention","hinweis":"Die Existenz mehrerer Systeme und die Placidus-Grenze sind belegt; die Wahl des Systems ist eine Fachkonvention."},"key_points":["Häuser hängen von Zeit und Ort ab, Zeichen nicht.","Placidus ist verbreitet, aber jenseits der Polarkreise nicht durchgehend definiert.","Das verwendete System muss transparent genannt werden."]},{"id":"grund-aszendent-mc","slug":"aszendent-und-mc","name":"Aszendent und MC","title":"Aszendent, Deszendent, MC und IC","level":"vertiefung","short":"Aszendent und MC sind die beiden Hauptachsen des Horoskops: der östliche Horizontschnittpunkt und der obere Meridianpunkt der Ekliptik. Sie machen die Geburtszeit wichtig.","long":"Der Aszendent ist der Punkt der Ekliptik, der im Moment der Geburt am östlichen Horizont aufgeht. Der Deszendent liegt gegenüber am westlichen Horizont. Der MC (Medium Coeli) ist der Punkt der Ekliptik, der den oberen Meridian schneidet; der IC liegt gegenüber am unteren Meridian [S22][S23]. Diese vier Punkte bilden die Achsen des Horoskops.\n\nDie Achsen sind geometrische Schnittpunkte, keine Himmelskörper. Der Aszendent hängt von der genauen Zeit und vom Ort ab; der MC von Zeit und geografischer Länge. Schon wenige Minuten können den Aszendenten um etwa ein Grad verschieben; die Faustregel von rund vier Minuten pro Grad ist eine Näherung und variiert je nach Breite und Tierkreiszeichen. Ohne belastbare Geburtszeit ist der Aszendent oft nicht sicher bestimmbar [S22].\n\nIn der Deutung steht der Aszendent traditionell für Auftreten, Körperbezug und die Art, wie jemand in Kontakt tritt; der Deszendent für das Gegenüber und die Beziehung; der MC für öffentliche Rolle und Beruf; der IC für Herkunft und inneres Fundament [S10][S23]. Diese Zuordnungen sind Tradition. Sie werden erst im Zusammenhang mit Zeichen, Planeten und Häusern aussagekräftig.\n\nDie wichtigste praktische Konsequenz: Astrologie mit Häusern ist keine reine Datumsangelegenheit. Wer nur das Geburtsdatum kennt, kann ein Sonnenzeichen bestimmen, aber keine belastbare Radix mit Häusern und Aszendent. Dieses Paket verlangt deshalb keine Geburtsdaten und simuliert keine Achsen.","keywords":["Aszendent","MC","IC","Deszendent","Geburtszeit"],"sources":["S22","S23","S10"],"claims":["c09","c08"],"cross_refs":["haus-1","haus-7","haus-10","haus-4","grund-haeuser-systeme"],"kennzeichnung":{"typ":"konvention","hinweis":"Die geometrischen Definitionen sind belegt; die Deutungen der Achsen sind Tradition."},"key_points":["Aszendent und MC sind Schnittpunkte der Ekliptik mit Horizont beziehungsweise Meridian.","Die Achsen machen die Geburtszeit für die Radix entscheidend.","Ohne genaue Zeit keine belastbare Haus- und Achsenbestimmung."]},{"id":"grund-radix-synthese","slug":"radix-lesen","name":"Radix lesen","title":"Radixlesen als Synthese","level":"vertiefung","short":"Radixlesen ist kein Ablesen einzelner Zeichen, sondern eine gewichtete Synthese aus Faktoren, Zeichen, Häusern, Aspekten und Achsen - als Hypothese, nicht als Diagnose.","long":"Eine Radix ist die Karte des Himmels zum Geburtszeitpunkt an einem Ort. Sie enthält Faktoren (Sonne, Mond, Planeten), Zeichenpositionen, Häuser, Achsen und Aspekte. Radixlesen bedeutet, diese Ebenen zu gewichten und miteinander in Beziehung zu setzen [S10][S11]. Es gibt keine allgemein verbindliche Reihenfolge; die folgende Methode ist ein didaktischer Vorschlag.\n\nSchritt 1: die Leitfrage klären. Wer eine Radix liest, sollte wissen, ob es um Selbstreflexion, um ein symbolisches Porträt oder um eine konkrete Entscheidung geht. Astrologie ist keine Diagnose und keine Prognose; die Leitfrage bestimmt, welche Ebenen relevant sind.\n\nSchritt 2: die Grundstruktur erfassen. Sonne, Mond und Aszendent werden oft als erste Trias gelesen: Sonne für bewusste Richtung, Mond für Bedürfnisse und Regulation, Aszendent für Auftreten und Zugang. Diese Trias ist Tradition, keine vollständige Persönlichkeit.\n\nSchritt 3: Schwerpunkte suchen. Welche Zeichen, Elemente und Modalitäten sind häufig? Welche Häuser sind besetzt? Welche Planeten stehen in Winkelhäusern? Welche Aspekte sind eng? Häufungen sind Hinweise, keine Beweise.\n\nSchritt 4: Herrscher und Achsen verfolgen. Der Herrscher des Aszendenten und die Herrscher der besetzten Hausspitzen zeigen, wohin die Aufmerksamkeit weiterwandert. Dispositor-Ketten können lange Wege ergeben; sie sind ein Navigationsmittel, kein Schicksalsfaden [S12].\n\nSchritt 5: Spannungen und Ressourcen benennen. Quadrate und Oppositionen sind nicht automatisch schlecht, Trigone nicht automatisch gut. Frage: Wie geht jemand mit der Spannung um? Welche Ressource steht zur Verfügung?\n\nSchritt 6: Gegenprobe. Welche Lesart würde die Person selbst nicht erkennen? Welche Alternative ergibt sich, wenn man das Häusersystem wechselt oder eine unsichere Geburtszeit berücksichtigt? Eine gute Lesart bleibt vorläufig und benennt ihre Grenzen.\n\nSchritt 7: Sprache prüfen. Beschreibungen sollten differenziert, nicht deterministisch und nicht schmeichelnd sein. Der Barnum-Effekt warnt davor, allgemeine Aussagen für treffend zu halten [S21]. Eine Radixdeutung ist ein Angebot, keine Messung.","keywords":["Radix","Synthese","Gewichtung","Herrscher","Gegenprobe"],"sources":["S10","S11","S12","S21"],"claims":["c07","c20","c26"],"cross_refs":["grund-aszendent-mc","grund-aspekt-orben","grund-haeuser-systeme","grund-sonnenzeichen-grenzen"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Die Methode ist ein didaktischer Vorschlag; sie ist keine psychologische Diagnose und keine Prognose."},"key_points":["Radixlesen ist eine gewichtete Synthese, kein Ablesen einzelner Zeichen.","Die Lesart bleibt Hypothese und braucht Gegenprobe.","Sprache und Geltungsanspruch müssen transparent bleiben."]},{"id":"grund-transite","slug":"transite","name":"Transite","title":"Transite und Zeitdeutung","level":"vertiefung","short":"Transite sind aktuelle Himmelsstellungen im Verhältnis zur Radix. Sie werden traditionell als Zeitqualitäten gelesen, nicht als sichere Ereignisvorhersagen.","long":"Ein Transit ist die aktuelle Position eines Faktors am Himmel im Verhältnis zu einer festen Radix. Man vergleicht also, wo ein Planet heute steht und welche Punkte der Geburtskarte er berührt. Transite sind ein Zeitdeutungsinstrument der Astrologie, keine astronomische Besonderheit. Bei der Auswertung werden die Winkel zwischen Transitposition und Radixpunkt wie jeder andere Aspekt als Winkelabstand gemessen [S11]; welches Haus dabei berührt wird, hängt von Zeit und Ort ab, nicht vom Datum [S10].\n\nDie Zeitmaße sind sehr unterschiedlich: Der Mond bewegt sich in Stunden durch Grade, die Sonne in Tagen, Mars in Wochen, Jupiter in Monaten, Saturn in Jahren, Uranus, Neptun und Pluto in Jahrzehnten. Daraus ergeben sich unterschiedliche Lesarten: Ein Mondtransit wird als kurze Stimmung gelesen, ein Saturntransit als langer Prozess. Diese Zuordnungen sind Tradition, keine Messung von Wirkung.\n\nIn der populären Astrologie werden Transite oft als Ereignisvorhersage verkauft: Saturn-Rückkehr, Pluto-Transit, Merkur rückläufig. Die Tradition kennt auch die vorsichtigere Lesart: Ein Transit beschreibt eine Zeitqualität, die unterschiedlich erlebt werden kann. Ob und wie etwas geschieht, hängt von vielen Faktoren ab, nicht von einem Winkel allein. Eine sichere Vorhersage von Gesundheit, Geld, Trennung oder Erfolg ist mit Astrologie nicht belegt [S09].\n\nFür dieses Paket gilt: Transite werden erklärt, aber nicht berechnet. Eine echte Transitberechnung braucht Ephemeriden, eine belastbare Radix und eine dokumentierte Zeit- und Häuserkonvention. Zufallswerte oder geschätzte Positionen wären keine Berechnung.","keywords":["Transit","Zeitqualität","Saturnrückkehr","Ephemeriden","keine Prognose"],"sources":["S10","S11","S09"],"claims":["c07","c17","c28"],"cross_refs":["grund-ruecklaeufigkeit","grund-radix-synthese","grund-berechnung"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Transitdeutung ist Tradition; die Ablehnung sicherer Ereignisvorhersagen folgt aus der Evidenzlage."},"key_points":["Transite vergleichen aktuelle Stellungen mit der Radix.","Zeitmaße reichen von Stunden bis Jahrzehnten.","Transite sind Zeitqualitäten, keine sicheren Ereignisvorhersagen."]},{"id":"grund-ruecklaeufigkeit","slug":"ruecklaeufigkeit","name":"Rückläufigkeit","title":"Rückläufigkeit: Scheinbewegung, nicht Umkehr","level":"vertiefung","short":"Rückläufig erscheinende Planeten bewegen sich nicht tatsächlich rückwärts. Die Umkehr ist eine Perspektivwirkung der unterschiedlichen Bahngeschwindigkeiten.","long":"Von der Erde aus gesehen verlangsamt ein Planet manchmal seine Bewegung vor dem Sternhintergrund, hält an und scheint einige Zeit rückwärts zu laufen. Das ist die scheinbare Rückläufigkeit. Sie entsteht, weil Erde und Planet unterschiedlich schnell um die Sonne laufen; die Erde überholt den äußeren Planeten auf der inneren Bahn, und die Projektion seiner Bewegung kehrt sich zeitweise um [S15].\n\nAstronomisch bewegt sich der Planet weiter in derselben Richtung. Die Bezeichnung rückläufig beschreibt also die beobachtete Bewegung am Himmel, nicht eine Umkehr der Bahn. Bei Merkur und Venus, die innerhalb der Erdbahn laufen, ist das Phänomen besonders auffällig; bei den äußeren Planeten tritt es ebenfalls auf, aber seltener und über längere Zeiträume [S15].\n\nIn der Astrologie wird die Rückläufigkeit als Zeit der Verlangsamung, Überprüfung oder Innerlichkeit gedeutet. Besonders Merkur rückläufig ist zu einem populären Motiv geworden, oft verbunden mit der Warnung vor Verträgen, Technik oder Reisen. Für solche konkreten Warnungen gibt es keine belastbare Evidenz [S09]. Die Deutung ist Tradition, nicht Vorhersage.\n\nSinnvoll ist die Unterscheidung: Astronomisch ist die Rückläufigkeit ein Perspektiveffekt und berechenbar. Astrologisch ist sie ein Symbol für Wiederholung, Prüfung und verlangsamte Bewegung. Wer beides trennt, kann das Motiv nutzen, ohne es als Naturgesetz auszugeben.","keywords":["Rückläufigkeit","Scheinbewegung","Merkur","Perspektive","keine Warnung"],"sources":["S15","S09"],"claims":["c14","c17","c19"],"cross_refs":["faktor-merkur","grund-transite","grund-zeichen-sternbilder"],"kennzeichnung":{"typ":"gemischt","hinweis":"Die astronomische Erklärung ist belegt; die Deutung als Prüfungszeit ist Tradition ohne Wirkungsnachweis."},"key_points":["Rückläufigkeit ist eine scheinbare Bewegung.","Ursache sind unterschiedliche Bahngeschwindigkeiten.","Keine belastbare Evidenz für konkrete Warnungen vor Verträgen oder Technik."]},{"id":"grund-sonnenzeichen-grenzen","slug":"grenzen-der-sonnenzeichen","name":"Grenzen der Sonnenzeichen","title":"Grenzen der Sonnenzeichen-Typologie","level":"vertiefung","short":"Das Sonnenzeichen beschreibt nur die Sonnenposition im Zeichensektor. Es reicht nicht für Persönlichkeitsaussagen; allgemeine Beschreibungen wirken oft treffend, weil sie vage sind.","long":"Das Sonnenzeichen ist der bekannteste Teil der Astrologie und der am stärksten verkürzte. Es beschreibt die Position der Sonne im tropischen Zeichensektor zum Geburtszeitpunkt. Ein Horoskop enthält aber mindestens neun weitere Faktoren, zwölf Häuser, Achsen und Aspekte [S10][S11][S19]. Wer nur das Sonnenzeichen liest, liest einen kleinen Ausschnitt.\n\nDie populäre Sonnenzeichen-Typologie ist aus mehreren Gründen problematisch. Erstens sind die Beschreibungen oft so allgemein, dass sie auf viele Menschen passen; der Barnum- beziehungsweise Forer-Effekt erklärt, warum solche Texte als treffend erlebt werden [S21]. Zweitens gibt es keine belastbare Evidenz für einen Zusammenhang zwischen Geburtsdatum und Persönlichkeit oder Intelligenz [S06][S09]. Drittens sind die Datumsgrenzen Näherungen und variieren je nach Jahr und Quelle [S06].\n\nDer bekannteste doppelblinde Test an Radixdeutungen, Carlson 1985, ergab laut Sekundärliteratur keine bessere Trefferquote als Zufall [S08][S09]. Auch die größere Untersuchung von Dean und Kelly fand keine Unterstützung für astrologische Behauptungen [S09]. Als alternative Erklärung für scheinbare Zusammenhänge werden unter anderem saisonale Geburtseffekte diskutiert [S19]. Das sind keine Beweise gegen jede kulturelle Nutzung, aber sie sprechen gegen die Behauptung, Sonnenzeichen seien eine zuverlässige Persönlichkeitsdiagnose.\n\nWas bleibt? Das Sonnenzeichen kann als Einstieg in ein Symbolsystem dienen: Es gibt ein Thema, eine Bildsprache, eine Reflexionsfrage. Es ist kein Test und keine Identität. Wer Astrologie ernsthaft als Tradition behandelt, sollte den Unterschied zwischen einem Deutungsangebot und einer Tatsachenbehauptung sichtbar halten.","keywords":["Sonnenzeichen","Barnum-Effekt","Carlson","Evidenz","Typologie"],"sources":["S06","S08","S09","S10","S11","S19","S21"],"claims":["c17","c18","c20","c21","c07"],"cross_refs":["faktor-sonne","grund-evidenz","grund-ethik","zeichen-widder"],"kennzeichnung":{"typ":"empirie","hinweis":"Die Evidenzlage ist belegt; die Nutzung des Sonnenzeichens als Reflexionsmotiv ist eine redaktionelle Entscheidung."},"key_points":["Das Sonnenzeichen ist nur ein Faktor von vielen.","Vage Beschreibungen wirken durch den Barnum-Effekt treffend.","Kontrollierte Tests stützen keine Persönlichkeitsdiagnose per Sonnenzeichen."]},{"id":"grund-mond","slug":"mond-verstehen","name":"Mond verstehen","title":"Den Mond verstehen: Astronomie und Deutung","level":"vertiefung","short":"Der Mond ist astronomisch der nächste Himmelskörper und astrologisch ein Faktor für Bedürfnisse und Rhythmen. Phasen, Zyklus und Zeichenwechsel sollten auseinandergehalten werden.","long":"Der Mond umrundet die Erde in 27,3217 Tagen. Bis zur nächsten gleichen Phase vergehen 29,53 Tage, weil die Erde sich währenddessen weiter um die Sonne bewegt [S18]. Die Phasen entstehen durch den Beleuchtungswinkel von Sonne, Erde und Mond. Bei Neumond steht der Mond zwischen Erde und Sonne, bei Vollmond steht die Erde zwischen beiden. Finsternisse sind besondere Konstellationen, keine regulären Monatsereignisse.\n\nAstrologisch gilt der Mond als Faktor für Bedürfnisse, emotionale Regulation, Sicherheit, Erinnerung und körperliche Rhythmen. Das Mondzeichen beschreibt, in welchem Sektor der Mond zum Geburtszeitpunkt stand. Weil der Mond den Sektor im Mittel etwa alle 2,46 Tage wechselt, ist das Mondzeichen ohne genaue Geburtszeit oft unsicher [S18]. Die Mondphase zur Geburt wird in manchen Schulen ebenfalls gedeutet; auch das ist Tradition.\n\nDie populäre Verbindung von Mondphasen mit Schlaf, Stimmung, Geburten oder Unfällen ist wissenschaftlich nicht belegt. Der Mond erzeugt Gezeiten und beeinflusst Lichtverhältnisse; ein direkter, zuverlässiger Einfluss auf menschliches Verhalten oder Gesundheit ist nicht nachgewiesen [S06][S09]. Das heißt nicht, dass Mondbeobachtung sinnlos ist: Sie ist astronomisch interessant und kulturell reich. Aber sie ist kein Gesundheits- oder Ereignisradar.\n\nFür die Deutung ist eine ruhige Sprache wichtig: Der Mond beschreibt, was jemand braucht, um sich sicher zu fühlen, und wie er mit Wiederholung umgeht. Das ist ein Reflexionsangebot, keine Diagnose. Wer den Mond als Symbol nutzt, sollte die astronomischen Fakten daneben stehen lassen, statt sie zu überdehnen.","keywords":["Mond","Phasen","synodisch","Mondzeichen","Bedürfnisse"],"sources":["S18","S06","S09"],"claims":["c15","c17","c07"],"cross_refs":["faktor-mond","zeichen-krebs","haus-4","grund-transite"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Zyklusdaten sind belegt; die emotionale Deutung ist Tradition, gesundheitliche Wirkbehauptungen werden ausdrücklich nicht gestützt."},"key_points":["Siderischer Monat 27,32 Tage, synodischer Monat 29,53 Tage.","Der Mond wechselt den Zeichensektor im Mittel alle 2,46 Tage.","Keine belastbare Evidenz für Mondphasen als Gesundheits- oder Ereignisradar."]},{"id":"grund-evidenz","slug":"evidenz-und-grenzen","name":"Evidenz","title":"Evidenzlage und Grenzen der Astrologie","level":"nachschlagen","short":"Kontrollierte Studien haben keine belastbare Evidenz für astrologische Wirkbehauptungen ergeben; ein plausibler Mechanismus ist nicht bekannt. Kulturelle Bedeutung bleibt davon unberührt.","long":"Die wissenschaftliche Prüfung der Astrologie hat eine lange Geschichte. Der bekannteste doppelblinde Test stammt von Shawn Carlson (1985): Astrologinnen und Astrologen sollten Radixen Persönlichkeitsprofilen zuordnen; laut Sekundärliteratur war die Trefferquote nicht besser als Zufall [S08][S09]. Weitere Untersuchungen, darunter die groß angelegte Studie von Dean und Kelly, fanden ebenfalls keine Unterstützung [S09].\n\nDie Einordnung als Pseudoscience folgt nicht aus einer einzelnen Studie, sondern aus dem Gesamtbild: Astrologische Aussagen wurden wiederholt geprüft und bestanden die Tests nicht; es gibt keinen bekannten physikalischen oder biologischen Mechanismus, der die behaupteten Effekte plausibel machen würde; und die Regeln sind historisch gewachsen und schulabhängig, nicht aus einer Theorie abgeleitet [S07][S09].\n\nDas ist ein Negativbefund, kein Beweis, dass nie irgendein Effekt existiert. Wissenschaft arbeitet mit vorläufigen Aussagen. Aber die Beweislast liegt bei denen, die eine Wirkung behaupten. Solange keine belastbare Evidenz vorliegt, ist es unredlich, Astrologie als gesicherte Persönlichkeits- oder Ereignisdiagnose darzustellen.\n\nUnberührt davon bleibt die kulturelle, historische und reflexive Bedeutung. Menschen können astrologische Symbole nutzen, um über sich nachzudenken, ohne zu behaupten, die Sterne würden ihr Leben bestimmen. Dieses Paket versucht genau diese Trennung: die Tradition verständlich machen, ohne ihre Wirkbehauptungen zu übernehmen. Wer Astrologie als Kunst, Sprache oder Kulturphänomen schätzt, muss nicht behaupten, sie sei Wissenschaft.","keywords":["Evidenz","Carlson","Pseudoscience","Mechanismus","Geltungsanspruch"],"sources":["S07","S08","S09","S06"],"claims":["c17","c18","c19"],"cross_refs":["grund-begriff","grund-sonnenzeichen-grenzen","grund-ethik"],"kennzeichnung":{"typ":"empirie","hinweis":"Die Evidenzlage wird nach Enzyklopädie, Studie und Tertiärquelle referiert; die Studie selbst war nur im Abstract zugänglich."},"key_points":["Kontrollierte Tests stützen astrologische Wirkbehauptungen nicht.","Ein plausibler Mechanismus ist nicht bekannt.","Kulturelle Nutzung ist unabhängig von der Wahrheitsfrage möglich."]},{"id":"grund-ethik","slug":"ethik-und-grenzen","name":"Ethik","title":"Ethik, Sprache und Grenzen der Deutung","level":"nachschlagen","short":"Astrologische Deutung darf keine Diagnosen, keine sicheren Prognosen und keine Angstmache erzeugen. Geburtsdaten sind persönliche Daten und brauchen Schutz.","long":"Astrologische Sprache kann stark wirken. Sie kann Menschen helfen, über sich nachzudenken, aber sie kann auch verunsichern, abhängig machen oder falsche Sicherheit erzeugen. Deshalb braucht jede verantwortliche Darstellung klare Grenzen.\n\nKeine Diagnosen: Astrologie ist kein medizinisches, psychologisches oder psychiatrisches Verfahren. Aussagen über Krankheit, Heilung, Suizidalität, Sucht oder Therapie gehören nicht in ein Horoskop. Keine sicheren Prognosen: Aussagen über Gesundheit, Geld, Schwangerschaft, Trennung, Tod oder Unfälle sind mit Astrologie nicht belegbar und sollten nicht als Vorhersage formuliert werden [S09]. Keine Angstmache: Drohungen mit Transiten, Rückläufen oder schlechten Aspekten sind ethisch problematisch und fachlich nicht gedeckt.\n\nKeine realen Personen ohne Einwilligung: Beispieldeutungen sollten fiktiv sein und das klar sagen. Reale Menschen dürfen nicht ohne Zustimmung analysiert oder öffentlich gedeutet werden. Geburtsdaten sind personenbezogene Daten; wer sie erhebt, braucht einen Zweck, eine Rechtsgrundlage und Datenschutz. Dieses Paket erhebt keine Geburtsdaten und braucht keine Konten.\n\nSprache: Deutungen sollten differenziert, respektvoll und nicht deterministisch sein. Sie sollten Tradition als Tradition kennzeichnen und nicht den Eindruck erwecken, wissenschaftliche Befunde zu referieren. Sie sollten keine kulturellen Stereotype über Geschlecht, Herkunft oder Körper reproduzieren. Und sie sollten den Menschen nicht auf ein Zeichen reduzieren.\n\nDie ethische Leitfrage lautet nicht: Was sagt das Horoskop? Sondern: Hilft diese Aussage der Person, sich selbst besser zu verstehen, ohne ihr Angst zu machen oder ihre Freiheit zu nehmen?","keywords":["Ethik","keine Diagnose","keine Prognose","Datenschutz","Sprache"],"sources":["S09","S07"],"claims":["c17","c19","c28"],"cross_refs":["grund-evidenz","grund-sonnenzeichen-grenzen","grund-radix-synthese"],"kennzeichnung":{"typ":"konvention","hinweis":"Redaktionelle und berufsethische Leitlinien; sie folgen aus der Evidenzlage und dem Datenschutz, nicht aus astrologischer Lehre."},"key_points":["Keine medizinischen, psychologischen oder finanziellen Diagnosen.","Keine sicheren Ereignis- oder Gesundheitsprognosen.","Geburtsdaten sind personenbezogen und nur mit Zweck und Schutz zu verarbeiten."]},{"id":"grund-berechnung","slug":"echte-berechnung","name":"Echte Berechnung","title":"Was eine echte Radixberechnung braucht","level":"nachschlagen","short":"Eine echte Radix- oder Transitberechnung braucht Ephemeriden, Zeitzonen, Geodaten und eine dokumentierte Häuserkonvention. Zufallswerte wären keine Berechnung.","long":"Dieses Paket enthält keine Radixberechnung. Das ist eine bewusste Entscheidung: Eine scheinbar genaue Grafik mit erfundenen oder geschätzten Positionen wäre eine Täuschung. Wenn später eine echte Berechnung angeboten wird, sind mehrere Hürden zu lösen.\n\nEphemeriden: Für Sonne, Mond und Planeten werden belastbare Positionsdaten benötigt, etwa aus einem etablierten Ephemeridenwerk. Die verbreitete Swiss Ephemeris ist dual lizenziert (AGPL oder kommerzielle Lizenz); die Lizenzfrage muss vor der Integration geklärt werden, nicht danach. Alternativ kommen frei lizenzierte Datensätze in Frage, deren Genauigkeit und Abdeckung zu prüfen sind.\n\nZeit und Ort: Geburtszeit, Zeitzone, Sommerzeitregeln und geografische Koordinaten müssen korrekt sein. Historische Zeitzonen sind fehleranfällig; eine Bibliothek mit IANA-Zeitzonendaten ist nötig. Die Genauigkeit der Geburtszeit begrenzt die Genauigkeit von Aszendent und Häusern; ohne Zeitangabe sind diese Punkte nicht belastbar [S22][S23].\n\nHäuser und Aspekte: Das Häusersystem muss gewählt und dokumentiert werden. Placidus ist verbreitet, aber in hohen Breiten nicht durchgehend definiert [S10]. Aspektorben müssen als Konvention offengelegt werden. Eine Berechnung ohne diese Angaben ist nicht reproduzierbar.\n\nDatenschutz und Tests: Geburtsdaten sind personenbezogene Daten. Speicherung, Löschung, Einwilligung und Zweckbindung sind zu klären. Technisch braucht es Referenztests gegen bekannte Beispiele, Plausibilitätsprüfungen und eine klare Fehlerbehandlung. Eine Berechnung ist erst dann brauchbar, wenn sie reproduzierbar, dokumentiert und ethisch verantwortbar ist [S10].","keywords":["Ephemeriden","Swiss Ephemeris","Zeitzonen","Datenschutz","Häusersystem"],"sources":["S10","S22","S23"],"claims":["c28","c08","c09"],"cross_refs":["grund-aszendent-mc","grund-haeuser-systeme","grund-transite","grund-ethik"],"kennzeichnung":{"typ":"konvention","hinweis":"Technische Anforderungen für einen späteren Rechenschritt; keine Implementierung und keine erfundenen Positionen in diesem Paket."},"key_points":["Ephemeriden, Zeitzonen, Geodaten und Häuserkonvention sind Pflicht.","Lizenz- und Datenschutzfragen müssen vor der Implementierung geklärt sein.","Ohne belastbare Geburtszeit keine belastbaren Achsen und Häuser."]}];

export const LERNPFAD = [{"id":"lernpfad-stufe-1","slug":"orientierung","title":"Stufe 1: Orientierung","level":"grundlagen","goal":"Nach dieser Stufe kannst du erklären, was Astrologie ist, worin sie sich von Astronomie unterscheidet und warum die Unterscheidung von Tradition und Evidenz für eine verantwortliche Nutzung wichtig ist.","reading_time_min":25,"steps":[{"title":"Begriff und Geltungsanspruch","refs":["grund-begriff","grund-geschichte"],"task":"Lies die beiden Textseiten und notiere in eigenen Worten den Unterschied zwischen einem Deutungssystem und einer Naturwissenschaft. Achte darauf, welche Aussagen als Tradition und welche als Fakt markiert sind."},{"title":"Himmel und Beobachtung","refs":["grund-ekliptik","grund-zeichen-sternbilder"],"task":"Vollziehe die Unterscheidung von Ekliptik, Tierkreis und Sternbild nach. Zeichne zur Kontrolle einen Kreis mit zwölf gleichen Sektoren und markiere daneben, warum ein Sternbild nicht deckungsgleich mit einem Sektor ist."},{"title":"Evidenz und Sprache","refs":["grund-evidenz","grund-sonnenzeichen-grenzen"],"task":"Lies die Evidenzseite und formuliere drei Sätze, die eine astrologische Aussage als Tradition kennzeichnen, ohne sie als Tatsache zu behaupten. Vermeide dabei sowohl Spott als auch Werbung."}],"check_questions":["Was ist der Unterschied zwischen Astronomie und Astrologie?","Warum sind Tierkreiszeichen und Sternbilder nicht dasselbe?","Welche Art von Aussage darf eine verantwortliche Astrologie-Seite nicht treffen?"],"next":"lernpfad-stufe-2"},{"id":"lernpfad-stufe-2","slug":"die-zwoelf-zeichen","title":"Stufe 2: Die zwölf Zeichen","level":"grundlagen","goal":"Nach dieser Stufe kannst du alle zwölf Zeichen mit Element, Modalität, traditionellem Herrscher und ungefährer tropischer Zeitspanne benennen und ihre Bilder in eigenen Worten erklären.","reading_time_min":45,"steps":[{"title":"Das Raster verstehen","refs":["element-feuer","element-erde","element-luft","element-wasser","modalitaet-kardinal","modalitaet-fix","modalitaet-veraenderlich"],"task":"Baue eine Tabelle mit vier Elementen und drei Modalitäten. Trage die zwölf Zeichen in die passenden Felder ein, ohne in die Einzeltexte zu schauen. Prüfe anschließend mit den Zeichenseiten."},{"title":"Die Zeichen lesen","refs":["zeichen-widder","zeichen-stier","zeichen-zwillinge","zeichen-krebs","zeichen-loewe","zeichen-jungfrau"],"task":"Lies die ersten sechs Zeichenseiten. Markiere für jedes Zeichen ein Bild, eine Stärke, eine Spannung und eine Reflexionsfrage, die dich persönlich anspricht. Achte darauf, dass du keine Beschreibung als Charaktertest verwendest."},{"title":"Die zweite Hälfte und die Gegenpole","refs":["zeichen-waage","zeichen-skorpion","zeichen-schuetze","zeichen-steinbock","zeichen-wassermann","zeichen-fische"],"task":"Lies die zweiten sechs Zeichenseiten und notiere die sechs Gegenpole (Widder-Waage, Stier-Skorpion, Zwillinge-Schütze, Krebs-Steinbock, Löwe-Wassermann, Jungfrau-Fische). Erkläre zu einem Paar, wie die beiden Seiten zusammenhängen."},{"title":"Herrschaft und Systemgrenze","refs":["grund-herrschaft","grund-tropisch-siderisch"],"task":"Ordne jedem Zeichen den traditionellen Herrscher zu. Markiere die drei Zeichen, bei denen moderne Systeme einen anderen Herrscher ergänzen. Schreibe dazu, warum die Zuordnung eine Konvention ist."}],"check_questions":["Welche vier Zeichen sind kardinal, und was bedeutet das?","Warum hat Skorpion traditionell Mars und modern Pluto als Herrscher?","Was ist der Unterschied zwischen einem Zeichen und einem Sternbild?"],"next":"lernpfad-stufe-3"},{"id":"lernpfad-stufe-3","slug":"faktoren-und-aspekte","title":"Stufe 3: Faktoren und Aspekte","level":"vertiefung","goal":"Nach dieser Stufe kannst du die zehn zentralen Faktoren und die fünf Hauptaspekte erklären, Winkel von Orben unterscheiden und begründen, warum dieselbe Konstellation je nach Schule anders gelesen werden kann.","reading_time_min":40,"steps":[{"title":"Die zehn Faktoren","refs":["faktor-sonne","faktor-mond","faktor-merkur","faktor-venus","faktor-mars"],"task":"Lies die ersten fünf Faktorseiten. Notiere zu jedem Faktor einen astronomischen Fakt und ein traditionelles Thema. Achte darauf, dass du beides nicht verwechselst."},{"title":"Die äußeren Faktoren","refs":["faktor-jupiter","faktor-saturn","faktor-uranus","faktor-neptun","faktor-pluto"],"task":"Lies die zweiten fünf Faktorseiten. Markiere die drei Faktoren, die nicht zur klassischen Siebenzahl gehören, und erkläre, warum sie in der modernen Astrologie trotzdem verwendet werden."},{"title":"Winkel und Orben","refs":["grund-aspekt-orben","aspekt-konjunktion","aspekt-sextil","aspekt-quadrat","aspekt-trigon","aspekt-opposition"],"task":"Zeichne einen Kreis und trage die fünf Hauptwinkel ein. Notiere zu jedem Aspekt einen typischen Orben und einen Satz zur traditionellen Bewertung. Erkläre, warum der Orbis eine Konvention ist."}],"check_questions":["Welche fünf Hauptaspekte gibt es, und welche Winkel gehören dazu?","Warum ist ein weiter Orbis nicht automatisch falsch?","Was unterscheidet die Sonne als Leuchtkörper von den acht Planeten?"],"next":"lernpfad-stufe-4"},{"id":"lernpfad-stufe-4","slug":"haeuser-und-achsen","title":"Stufe 4: Häuser und Achsen","level":"vertiefung","goal":"Nach dieser Stufe kannst du die zwölf Häuser benennen, die vier Achsen unterscheiden und erklären, warum Geburtszeit und Häusersystem die Deutung verändern.","reading_time_min":35,"steps":[{"title":"Die zwölf Felder","refs":["haus-1","haus-2","haus-3","haus-4","haus-5","haus-6"],"task":"Lies die ersten sechs Hausseiten. Ordne jedem Haus ein Stichwort und eine Alltagsfrage zu. Vermeide dabei medizinische oder finanzielle Aussagen."},{"title":"Die zweite Hälfte","refs":["haus-7","haus-8","haus-9","haus-10","haus-11","haus-12"],"task":"Lies die zweiten sechs Hausseiten. Markiere die vier Winkelhäuser und erkläre, warum sie traditionell als besonders prägnant gelten."},{"title":"Achsen und Systeme","refs":["grund-aszendent-mc","grund-haeuser-systeme","gloss-placidus","gloss-equal-house"],"task":"Erkläre den Unterschied zwischen Aszendent, Deszendent, MC und IC. Vergleiche Placidus und Equal House an einem selbst gewählten Beispiel und notiere, welche Angaben ein Text machen muss, damit die Deutung nachvollziehbar bleibt."}],"check_questions":["Warum hängen Häuser von der Geburtszeit ab, Zeichen aber nicht?","Was ist der Unterschied zwischen Aszendent und MC?","Warum ist Placidus in hohen Breiten nicht immer definiert?"],"next":"lernpfad-stufe-5"},{"id":"lernpfad-stufe-5","slug":"synthese-und-grenzen","title":"Stufe 5: Synthese und Grenzen","level":"vertiefung","goal":"Nach dieser Stufe kannst du eine fiktive Radix in sieben Schritten gewichtet lesen, eine Gegenprobe formulieren und die Grenzen der Deutung klar benennen.","reading_time_min":40,"steps":[{"title":"Die Methode","refs":["grund-radix-synthese","grund-herrschaft","gloss-dispositor"],"task":"Lies die Synthesemethode und notiere die sieben Schritte. Erkläre, warum eine Lesart als Hypothese formuliert werden muss und was eine Gegenprobe leistet."},{"title":"Beispiele nachvollziehen","refs":["beispiel-mira","beispiel-tobias","beispiel-nora"],"task":"Lies die drei fiktiven Beispiele. Markiere in jedem Beispiel die gesetzten Annahmen und die Stellen, an denen die Deutung ausdrücklich vorläufig bleibt. Prüfe, ob die Figuren wirklich als erfunden gekennzeichnet sind."},{"title":"Grenzen und Zeitdeutung","refs":["beispiel-selin","grund-transite","grund-ruecklaeufigkeit","grund-ethik"],"task":"Lies das kritische Beispiel und die Seiten zu Transiten und Rückläufigkeit. Formuliere eine astrologische Aussage über einen Transit, die keine Ereignisvorhersage ist, und eine, die unzulässig wäre. Erkläre den Unterschied."}],"check_questions":["Warum ist eine Radixdeutung keine Diagnose?","Wie unterscheidet man eine Zeitqualität von einer Ereignisvorhersage?","Welche Angaben braucht eine echte Berechnung, die dieses Paket nicht liefert?"],"next":"lernpfad-stufe-6"},{"id":"lernpfad-stufe-6","slug":"nachschlagen-und-vertiefen","title":"Stufe 6: Nachschlagen und Vertiefen","level":"nachschlagen","goal":"Nach dieser Stufe kannst du Begriffe selbstständig nachschlagen, Quellen einordnen und erkennen, wann eine Aussage belegt, eine Konvention oder eine Deutungstradition ist.","reading_time_min":20,"steps":[{"title":"Glossar und FAQ nutzen","refs":["gloss-aszendent","gloss-orbis","faq-wissenschaft","faq-sternbild"],"task":"Suche im Glossar drei Begriffe, die dir noch unklar sind, und lies die zugehörigen FAQ-Antworten. Notiere, welche Quelle jeweils genannt wird und welchen Typ sie hat."},{"title":"Quellen einordnen","refs":["grund-evidenz","grund-ethik"],"task":"Lies die Quellen und Claims im Quellenledger. Ordne drei Quellen als primär, sekundär oder tertiär ein und erkläre, warum die Einordnung für die Aussagekraft wichtig ist."},{"title":"Eine eigene Frage formulieren","refs":["grund-berechnung","grund-mond"],"task":"Formuliere eine Frage, die dieses Paket nicht beantwortet, und beschreibe, welche Art von Quelle oder Berechnung nötig wäre, um sie zu beantworten. Achte darauf, keine Scheingenauigkeit zu erzeugen."}],"check_questions":["Woran erkennt man eine belegte Aussage im Vergleich zu einer Deutungstradition?","Welche Rolle spielt die Quellentypologie für die Bewertung?","Was fehlt diesem Paket bewusst, und warum?"],"next":null}];

export const BEISPIELE = [{"id":"beispiel-mira","slug":"beispiel-mira","titel":"Mira: Löwe-Sonne, Krebs-Mond, Waage-Aszendent","fictional":true,"no_calculation":true,"figuren":["Mira, eine erfundene Figur"],"annahmen":["Sonne im Löwe-Sektor, Mond im Krebs-Sektor, Aszendent im Waage-Sektor: gesetzte Lehrannahmen, keine Berechnung.","Merkur im Jungfrau-Sektor, Venus im Löwe-Sektor, Mars im Widder-Sektor: ebenfalls gesetzt.","Keine Geburtszeit, kein Geburtsort, keine Gradangaben; die Hauspositionen bleiben offen."],"schritte":[{"titel":"Leitfrage und Grenzen","denkweg":"Die Leitfrage lautet: Wie zeigt sich Mira in Gruppen, und wo geraten Selbstausdruck und Rücksichtnahme in Spannung? Es geht um ein symbolisches Porträt, nicht um eine Diagnose.","refs":["grund-radix-synthese","grund-ethik"]},{"titel":"Die Trias lesen","denkweg":"Löwe-Sonne wird als Wunsch gelesen, sichtbar zu gestalten und für etwas einzustehen. Krebs-Mond betont Schutzbedürfnis und emotionale Zugehörigkeit. Waage-Aszendent zeigt ein zugewandtes, abwägendes Auftreten. Die Trias ist bewusst widersprüchlich: sichtbar sein wollen und zugleich Schutz suchen.","refs":["faktor-sonne","faktor-mond","grund-aszendent-mc","zeichen-loewe","zeichen-krebs","zeichen-waage"]},{"titel":"Elemente und Modalitäten gewichten","denkweg":"Feuer und Wasser dominieren, Luft ist über den Aszendenten vertreten, Erde fehlt in der gesetzten Auswahl. Kardinal und fix stehen nebeneinander: Der Impuls, etwas zu beginnen, trifft auf das Bedürfnis, es zu halten. Das kann als Engagement gelesen werden, aber auch als innerer Widerstreit zwischen Vortreten und Zurückziehen.","refs":["element-feuer","element-wasser","element-luft","modalitaet-kardinal","modalitaet-fix"]},{"titel":"Faktoren differenzieren","denkweg":"Merkur in Jungfrau spricht eher prüfend und detailgenau; Venus in Löwe sucht warme, sichtbare Bestätigung; Mars in Widder handelt schnell und direkt. Daraus entsteht ein Profil, in dem Zuwendung und Genauigkeit nebeneinander stehen und der Antrieb nicht lange wartet.","refs":["faktor-merkur","faktor-venus","faktor-mars","zeichen-jungfrau"]},{"titel":"Gegenprobe","denkweg":"Würde Mira sich selbst als harmoniesüchtig beschreiben? Der Waage-Aszendent legt das nahe, die Löwe-Sonne widerspricht. Vielleicht ist das Abwägen kein Wesenszug, sondern eine Strategie, um Konflikte zu vermeiden, in denen die Sonne zu viel riskieren würde. Diese Gegenprobe bleibt Hypothese.","refs":["grund-sonnenzeichen-grenzen","grund-aspekt-orben"]}],"synthese":"Mira wirkt nach außen zugewandt und abwägend, während innen ein starkes Bedürfnis nach Schutz und Zugehörigkeit arbeitet. Der Löwe-Anteil will gestalten und gesehen werden, der Krebs-Anteil will nicht verletzlich dastehen. Die Spannung ist nicht per se ein Problem: Sie kann erklären, warum Mira in Gruppen vermittelt, aber persönliche Anerkennung schwer annimmt. Eine hilfreiche Lesart wäre: Mira braucht einen Rahmen, in dem sie sichtbar sein kann, ohne sich schutzlos zu fühlen. Das ist eine Deutungshypothese, keine Aussage über eine reale Person.","alternative_lesart":"Wird statt eines quadrantenbasierten Häusersystems ein Ganzzeichen-System verwendet oder die Geburtszeit anders angenommen, verschieben sich die Hausbezüge und damit die Gewichtung. Auch eine andere Lesart der Waage-Sonne wäre möglich: Statt Harmoniesuche könnte das Abwägen als bewusste Methode gelesen werden, Entscheidungen zu prüfen. Die Beispieldeutung ist daher bewusst vorläufig.","grenzen":["Es gibt keine berechnete Radix und keine gesicherte Geburtszeit; die Hauspositionen sind offen.","Die Deutung ist eine didaktische Konstruktion und keine Aussage über eine reale Person.","Die Zuordnung von Zeichen zu Eigenschaften ist Tradition und keine Messung."],"disclaimer":"Mira ist eine erfundene Figur. Alle Annahmen sind gesetzt, nicht berechnet. Das Beispiel zeigt eine Methode und darf nicht als Persönlichkeitsdiagnose oder als Vorlage für die Deutung realer Menschen verwendet werden.","sources":["S10","S11","S12","S19"],"claims":["c07","c17","c20"],"cross_refs":["grund-radix-synthese","grund-aszendent-mc","grund-haeuser-systeme","zeichen-loewe","zeichen-krebs"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Fiktives Lehrbeispiel ohne Berechnung; die Methode ist Tradition, die Figur ist erfunden."}},{"id":"beispiel-tobias","slug":"beispiel-tobias","titel":"Tobias: Steinbock-Sonne, Zwillinge-Mond, Skorpion-Aszendent","fictional":true,"no_calculation":true,"figuren":["Tobias, eine erfundene Figur"],"annahmen":["Sonne im Steinbock-Sektor, Mond im Zwillinge-Sektor, Aszendent im Skorpion-Sektor: gesetzte Lehrannahmen, keine Berechnung.","Saturn im Steinbock-Sektor und im zehnten Haus: gesetzt, um die Achse Beruf-Verantwortung zu zeigen.","Merkur im Wassermann-Sektor, Venus im Fische-Sektor: ebenfalls gesetzt."],"schritte":[{"titel":"Leitfrage und Grenzen","denkweg":"Die Leitfrage lautet: Wie geht Tobias mit Verantwortung und Nähe um? Das Beispiel soll zeigen, wie eine scheinbar klare Sonne durch Mond und Aszendent gebrochen wird.","refs":["grund-radix-synthese","grund-ethik"]},{"titel":"Die Trias lesen","denkweg":"Steinbock-Sonne wird als Verantwortungs- und Strukturthema gelesen. Zwillinge-Mond betont Beweglichkeit, Sprache und ein Bedürfnis nach geistigem Austausch. Skorpion-Aszendent zeigt eine zurückhaltende, prüfende Präsenz. Die Kombination kann als ernst nach außen und bewegt nach innen gelesen werden.","refs":["faktor-sonne","faktor-mond","grund-aszendent-mc","zeichen-steinbock","zeichen-zwillinge","zeichen-skorpion"]},{"titel":"Häuser und Achsen","denkweg":"Saturn im zehnten Haus verstärkt das Thema Verantwortung und öffentliche Rolle. Der Skorpion-Aszendent legt eine vorsichtige Kontaktaufnahme nahe; der Zwillinge-Mond sucht Austausch, aber eher über Themen als über unmittelbare Nähe. Daraus entsteht die Frage, ob Tobias Nähe über Gespräch herstellt und dabei Distanz wahrt.","refs":["haus-10","haus-1","faktor-saturn","grund-haeuser-systeme"]},{"titel":"Aspekte als Spannung lesen","denkweg":"Angenommen, Saturn steht in einem Spannungsaspekt zur Sonne: Das würde die Ernsthaftigkeit und den Selbstanspruch betonen. Angenommen, der Mond steht in einem Spannungsaspekt zum Aszendenten: Das würde den Unterschied zwischen innerem Bedürfnis und äußerem Auftreten hervorheben. Beide Annahmen sind gesetzt und nicht berechnet.","refs":["aspekt-quadrat","aspekt-opposition","grund-aspekt-orben"]},{"titel":"Gegenprobe","denkweg":"Würde Tobias sich selbst als distanziert beschreiben? Vielleicht nicht; der Zwillinge-Mond kann sehr gesprächig sein. Die Distanz liegt eher im Skorpion-Aszendenten und in der Steinbock-Sonne. Die Gegenprobe fragt, welche Lesart die Person selbst überraschen würde, und hält das Ergebnis offen.","refs":["grund-sonnenzeichen-grenzen","grund-radix-synthese"]}],"synthese":"Tobias wirkt nach außen kontrolliert und beobachtend, während innen ein starkes Bedürfnis nach Austausch und geistiger Bewegung besteht. Die Steinbock-Sonne setzt auf Verantwortung und langfristige Struktur; der Zwillinge-Mond sucht Abwechslung und Gespräch; der Skorpion-Aszendent prüft, bevor er sich zeigt. Eine plausible Lesart: Tobias stellt Nähe über gemeinsame Themen her und schützt sich durch Themenkontrolle. Das kann Verlässlichkeit erzeugen, aber auch Nähe verhindern, wenn Gespräche zur Distanzierung werden. Auch hier gilt: Hypothese, keine Diagnose.","alternative_lesart":"Ohne gesicherte Geburtszeit ist der Skorpion-Aszendent unsicher. Bei einem anderen Aszendenten verschieben sich alle Häuser; die Saturn-Stellung im zehnten Haus wäre dann nicht mehr gegeben. Zudem kann der Zwillinge-Mond als Leichtigkeit statt als Unruhe gelesen werden. Die Beispieldeutung ist bewusst an die gesetzten Annahmen gebunden.","grenzen":["Die Aspekte und Hauspositionen sind gesetzt, nicht berechnet.","Die Geburtszeit fehlt; der Aszendent ist daher nicht belastbar.","Die Lesart ist eine didaktische Konstruktion, keine Aussage über eine reale Person."],"disclaimer":"Tobias ist eine erfundene Figur. Alle Annahmen sind gesetzt, nicht berechnet. Das Beispiel dient der Methodenschulung und darf nicht als Persönlichkeitsdiagnose oder als Vorlage für reale Menschen verwendet werden.","sources":["S10","S11","S12","S19"],"claims":["c07","c08","c09","c20"],"cross_refs":["grund-radix-synthese","grund-aszendent-mc","grund-haeuser-systeme","zeichen-steinbock","zeichen-zwillinge"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Fiktives Lehrbeispiel ohne Berechnung; die Methode ist Tradition, die Figur ist erfunden."}},{"id":"beispiel-nora","slug":"beispiel-nora","titel":"Nora: Fische-Sonne, Waage-Mond, Löwe-Aszendent","fictional":true,"no_calculation":true,"figuren":["Nora, eine erfundene Figur"],"annahmen":["Sonne im Fische-Sektor, Mond im Waage-Sektor, Aszendent im Löwe-Sektor: gesetzte Lehrannahmen, keine Berechnung.","Neptun im Fische-Sektor und im zwölften Haus: gesetzt, um die Frage nach Grenzen und Imagination zu zeigen.","Jupiter im Schütze-Sektor und im neunten Haus: ebenfalls gesetzt."],"schritte":[{"titel":"Leitfrage und Grenzen","denkweg":"Die Leitfrage lautet: Wie verbindet Nora Nähe und Sichtbarkeit? Das Beispiel zeigt eine Konstellation, in der zwei weiche Faktoren auf einen präsenten Aszendenten treffen.","refs":["grund-radix-synthese","grund-ethik"]},{"titel":"Die Trias lesen","denkweg":"Fische-Sonne wird als durchlässige, imaginative Identitätsfigur gelesen. Waage-Mond sucht Balance und emotionale Fairness. Löwe-Aszendent zeigt ein warmes, sichtbares Auftreten. Die Spannung: Nora kann nach außen präsent wirken, während innen Grenzen und Selbstbehauptung schwerfallen.","refs":["faktor-sonne","faktor-mond","grund-aszendent-mc","zeichen-fische","zeichen-waage","zeichen-loewe"]},{"titel":"Häuser und Herrscher","denkweg":"Neptun im zwölften Haus verstärkt das Thema Rückzug und Auflösung. Jupiter im neunten Haus betont Sinnsuche und Weite. Der Löwe-Aszendent wird von der Sonne regiert, die in Fische steht: Das zeigt eine Verbindung zwischen sichtbarem Auftreten und einer eher durchlässigen Identitätsfigur.","refs":["haus-12","haus-9","faktor-neptun","faktor-jupiter","grund-herrschaft"]},{"titel":"Aspekte als Ressource lesen","denkweg":"Angenommen, Mond und Venus stehen in einem fließenden Aspekt: Das würde soziale Wärme und Ästhetik betonen. Angenommen, Sonne und Neptun stehen in einem Spannungsaspekt: Das würde die Frage nach Selbstbild und Auflösung verschärfen. Beide Annahmen sind gesetzt, nicht berechnet.","refs":["aspekt-trigon","aspekt-quadrat","grund-aspekt-orben"]},{"titel":"Gegenprobe und Sprache","denkweg":"Die Gefahr dieser Lesart ist, Nora auf Weichheit zu reduzieren. Der Löwe-Aszendent widerspricht dem. Die Gegenprobe fragt: Wo zeigt Nora Klarheit und Struktur, die im Beispiel nicht betont werden? Eine gute Deutung benennt diese Lücke, statt sie zu füllen.","refs":["grund-sonnenzeichen-grenzen","grund-radix-synthese","grund-ethik"]}],"synthese":"Nora kann nach außen warm und präsent wirken, während innen die Frage nach Grenzen und eigener Position zentral bleibt. Fische-Sonne und Neptun im zwölften Haus betonen Durchlässigkeit und Imagination; der Waage-Mond sucht Fairness und Beziehung; der Löwe-Aszendent gibt dem Ganzen eine sichtbare Form. Eine plausible Lesart: Nora braucht einen gestalteten Rahmen, etwa Kunst, Projekt oder Gruppe, in dem Durchlässigkeit nicht als Überforderung erlebt wird. Die Löwe-Präsenz kann Schutz sein, nicht nur Eitelkeit.","alternative_lesart":"Das zwölfte Haus ist stark von der Häuserkonvention abhängig. Bei einem anderen System kann Neptun in einem anderen Haus stehen; damit ändert sich die Lesart erheblich. Auch die Fische-Sonne kann als Rückzug oder als kreative Offenheit gelesen werden. Die Beispieldeutung bleibt an die gesetzten Annahmen gebunden.","grenzen":["Neptun- und Jupiter-Hauspositionen sind gesetzt, nicht berechnet.","Die Geburtszeit fehlt; Aszendent und Häuser sind nicht belastbar.","Die Lesart ist eine didaktische Konstruktion, keine Aussage über eine reale Person."],"disclaimer":"Nora ist eine erfundene Figur. Alle Annahmen sind gesetzt, nicht berechnet. Das Beispiel dient der Methodenschulung und darf nicht als Persönlichkeitsdiagnose oder als Vorlage für reale Menschen verwendet werden.","sources":["S10","S11","S12","S19"],"claims":["c07","c08","c09","c20"],"cross_refs":["grund-radix-synthese","grund-aszendent-mc","grund-haeuser-systeme","zeichen-fische","zeichen-waage"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Fiktives Lehrbeispiel ohne Berechnung; die Methode ist Tradition, die Figur ist erfunden."}},{"id":"beispiel-selin","slug":"beispiel-selin","titel":"Selin: Warum ein Transit keine Kündigung vorhersagt","fictional":true,"no_calculation":true,"figuren":["Selin, eine erfundene Figur"],"annahmen":["Selin steht vor einer beruflichen Entscheidung und liest, ein Saturn-Transit bedeute eine sichere Kündigung oder einen unvermeidbaren Bruch.","Die Transitbehauptung ist ein populäres Motiv, keine berechnete Aussage und keine belegte Vorhersage.","Es gibt keine Radix, keine Ephemeriden und keine Geburtszeit; das Beispiel prüft den Umgang mit einer Deutung, nicht ein Horoskop."],"schritte":[{"titel":"Die Behauptung isolieren","denkweg":"Zuerst wird die Aussage zerlegt: Was genau wird behauptet? Ein Transit wird als Ursache eines Ereignisses dargestellt. Das ist eine starke Kausalbehauptung, die von der Astrologie nicht belegt ist.","refs":["grund-transite","grund-evidenz","grund-ethik"]},{"titel":"Astronomie und Deutung trennen","denkweg":"Astronomisch beschreibt ein Transit eine aktuelle Position. Die Bedeutung als Krise oder Befreiung ist eine Deutungstradition. Aus der Position folgt kein Ereignis.","refs":["grund-transite","grund-ruecklaeufigkeit","faktor-saturn"]},{"titel":"Die Entscheidung zurückholen","denkweg":"Statt das Horoskop zu fragen, wird gefragt: Welche Informationen braucht Selin für die Entscheidung? Arbeitsbedingungen, Vertrag, Finanzen, Gesundheit, persönliche Ziele. Astrologie kann als Reflexionsfrage dienen, aber nicht als Entscheidungsinstanz.","refs":["grund-radix-synthese","grund-ethik"]},{"titel":"Eine ethische Formulierung finden","denkweg":"Eine vertretbare Formulierung wäre: Der Saturn-Transit kann als Bild für Begrenzung und Verantwortung gelesen werden. Ob Selin kündigt, hängt von realen Bedingungen ab. Die Formulierung macht die Tradition sichtbar, ohne eine Vorhersage zu behaupten.","refs":["grund-ethik","aspekt-quadrat","haus-10"]}],"synthese":"Das Beispiel zeigt, wie eine astrologische Aussage in eine unzulässige Prognose kippt. Selin wird nicht durch einen Transit gekündigt; sie trifft eine Entscheidung aufgrund von Bedingungen, die sie prüfen kann. Der Transit kann als Symbol für Druck, Verantwortung oder Reifung gelesen werden, aber er liefert keine Evidenz für einen konkreten Ausgang. Eine hilfreiche astrologische Sprache wäre: Das Motiv lädt dazu ein, die eigene Situation genauer anzusehen. Eine unhilfreiche Sprache wäre: Der Transit bedeutet, dass du kündigen musst.","alternative_lesart":"Manche Astrologinnen und Astrologen lesen Saturn-Transite als Zeit der Strukturierung und nicht als Krise. Andere halten Transite für bedeutungslos. Beide Haltungen sind mit der Evidenzlage vereinbar, solange sie keine sicheren Ereignisse behaupten. Die Beispieldeutung wählt bewusst die vorsichtige Variante.","grenzen":["Es gibt keine berechnete Radix und keinen berechneten Transit.","Die Behauptung einer sicheren Kündigung ist eine unzulässige Prognose.","Das Beispiel ist eine ethische Übung, keine astrologische Fallanalyse."],"disclaimer":"Selin ist eine erfundene Figur. Das Beispiel enthält keine berechneten Positionen und keine Vorhersage. Es zeigt, wie man eine astrologische Behauptung prüft und in eine nicht-deterministische Sprache übersetzt.","sources":["S09","S10","S11"],"claims":["c17","c19","c28"],"cross_refs":["grund-transite","grund-evidenz","grund-ethik","faktor-saturn","haus-10"],"kennzeichnung":{"typ":"empirie","hinweis":"Kritisches Lehrbeispiel zur Grenze astrologischer Prognosen; die Figur ist erfunden, die Positionen sind nicht berechnet."}}];

export const FAQ = [{"id":"faq-wissenschaft","slug":"ist-astrologie-wissenschaftlich","frage":"Ist Astrologie wissenschaftlich?","short_answer":"Nein. Astrologie ist ein historisches Deutungssystem; ihre Wirkbehauptungen haben in kontrollierten Studien keine belastbare Bestätigung gefunden.","long_answer":"Astrologie wird in der modernen Wissenschaft als Pseudoscience eingeordnet [S07]. Der bekannteste doppelblinde Test an Radixdeutungen (Carlson 1985) ergab laut Sekundärliteratur keine bessere Trefferquote als Zufall [S08][S09]. Auch weitere Untersuchungen fanden keine Unterstützung, und es ist kein plausibler physikalischer oder biologischer Mechanismus bekannt [S09]. Das bedeutet nicht, dass astrologische Symbole kulturell oder reflexiv wertlos sind. Es bedeutet, dass die Behauptung, Himmelskörper würden Persönlichkeit oder Ereignisse verursachen, nicht als wissenschaftlich gesichert gelten kann. Wer Astrologie nutzt, sollte diesen Unterschied kennen und keine medizinischen, finanziellen oder existenziellen Entscheidungen darauf stützen.","related":["grund-evidenz","grund-begriff","grund-ethik"],"sources":["S07","S08","S09"],"claims":["c17","c18","c19"],"kennzeichnung":{"typ":"empirie","hinweis":"Wissenschaftliche Einordnung und Studienlage; keine Aussage über den kulturellen Wert astrologischer Symbolik."}},{"id":"faq-sternbild","slug":"warum-passt-mein-sternzeichen-nicht","frage":"Warum passt mein Sternzeichen nicht zum Sternbild?","short_answer":"Weil Tierkreiszeichen und Sternbilder verschiedene Dinge sind. Die Zeichen sind 30-Grad-Sektoren ab dem Frühlingspunkt; die Sternbilder haben ungleiche Grenzen und haben sich durch die Präzession verschoben.","long_answer":"Der tropische Tierkreis beginnt am Frühlings-Äquinoktium und teilt die Ekliptik in zwölf gleiche Sektoren von 30 Grad [S13][S19]. Diese Sektoren sind an den Jahreszeiten orientiert. Sternbilder sind dagegen Areale am Himmel mit historisch gewachsenen, ungleichen Grenzen; die IAU kennt 88 Sternbilder [S04]. Entlang der Ekliptik liegen zwölf klassische Tierkreissternbilder plus Ophiuchus [S05]. Durch die Präzession der Erdachse verschiebt sich der Frühlingspunkt langsam gegenüber den Sternbildern, etwa um ein Grad in 72 Jahren [S01][S13]. Deshalb steht die Sonne heute in anderen Sternbildern als in den Zeichen, die ihnen historisch zugeordnet wurden. Das ist kein Rechenfehler der Astrologie, sondern eine Folge unterschiedlicher Bezugssysteme. Wer die Sternbilder als Bezug will, landet bei der siderischen Astrologie; wer die Jahreszeiten als Bezug will, bleibt beim tropischen System.","related":["grund-zeichen-sternbilder","grund-tropisch-siderisch","grund-ekliptik"],"sources":["S01","S04","S05","S13","S19"],"claims":["c01","c02","c05"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische und definitorische Grundlagen; die Systemwahl ist eine Konvention."}},{"id":"faq-tropisch-siderisch","slug":"tropisch-oder-siderisch","frage":"Was ist der Unterschied zwischen tropischer und siderischer Astrologie?","short_answer":"Tropisch rechnet ab dem Frühlingspunkt, siderisch ab einem sternbezogenen Nullpunkt. Deshalb können dieselben Himmelskörper in verschiedenen Zeichen stehen.","long_answer":"Die tropische Astrologie setzt den Nullpunkt auf das Frühlings-Äquinoktium; die Zeichen sind an den Jahreszeiten orientiert. Die siderische Astrologie orientiert sich an der Position der Sterne und korrigiert die Präzession mit einem Ayanamsa [S13]. Der bekannteste Ayanamsa ist der Lahiri-Wert der vedischen Astrologie; weitere Systeme existieren [S13]. Weil sich der Frühlingspunkt gegenüber den Sternen verschiebt, sind tropische und siderische Zeichen heute nicht mehr deckungsgleich. Ein und dieselbe Planetenposition kann tropisch in einem anderen Zeichen liegen als siderisch. Beide Systeme können intern konsistent sein; sie beantworten unterschiedliche Fragen. Wichtig ist, sie nicht unmarkiert zu mischen. Dieses Paket arbeitet mit der tropischen Konvention und sagt das an jeder Stelle, an der es relevant ist.","related":["grund-tropisch-siderisch","grund-zeichen-sternbilder","zeichen-widder"],"sources":["S13","S19"],"claims":["c02","c03"],"kennzeichnung":{"typ":"konvention","hinweis":"Definitionen und Präzessionsfolge; die Systemwahl ist Tradition."}},{"id":"faq-geburtsdatum","slug":"reicht-geburtsdatum","frage":"Reicht mein Geburtsdatum für ein Horoskop?","short_answer":"Für ein Sonnenzeichen ja, für eine vollständige Radix mit Häusern und Aszendent nein. Dafür braucht es Geburtszeit und Geburtsort.","long_answer":"Mit dem Geburtsdatum lässt sich die ungefähre Sonnenposition im tropischen Zeichensektor bestimmen. Das ist das populäre Sonnenzeichen. Eine vollständige Radix enthält aber auch Mond, Planeten, Häuser und Achsen. Der Mond wechselt den Zeichensektor im Mittel etwa alle 2,46 Tage; ohne Geburtszeit ist das Mondzeichen oft unsicher [S18]. Aszendent und Häuser hängen sogar von der genauen Uhrzeit und vom Ort ab [S22][S10]. Ohne belastbare Zeit sind diese Punkte nicht seriös bestimmbar. Dieses Paket verlangt deshalb keine Geburtsdaten und simuliert keine Radix. Wer eine echte Radix berechnen will, braucht Zeit, Ort und eine dokumentierte Häuserkonvention.","related":["grund-aszendent-mc","grund-haeuser-systeme","faktor-mond"],"sources":["S18","S22","S10"],"claims":["c09","c15","c28"],"kennzeichnung":{"typ":"konvention","hinweis":"Technische und definitorische Grenzen der Datumsangabe; keine Berechnung in diesem Paket."}},{"id":"faq-aszendent","slug":"was-ist-der-aszendent","frage":"Was ist der Aszendent?","short_answer":"Der Aszendent ist der Punkt der Ekliptik, der zum Geburtszeitpunkt am östlichen Horizont aufgeht. Er hängt von Zeit und Ort ab und wird traditionell mit Auftreten und Zugang verbunden.","long_answer":"Geometrisch ist der Aszendent der östliche Schnittpunkt von Ekliptik und Horizont [S22]. Der gegenüberliegende Punkt ist der Deszendent. Der MC ist der obere Meridianpunkt der Ekliptik, der IC der untere [S23]. Diese vier Punkte bilden die Achsen des Horoskops. Der Aszendent ändert sich mit der Zeit und dem Ort; schon wenige Minuten können ihn um etwa ein Grad verschieben. Die Faustregel von rund vier Minuten pro Grad ist eine Näherung und variiert je nach Breite und Tierkreiszeichen. In der Deutung steht der Aszendent traditionell für Auftreten, Körperbezug und die Art, wie jemand in Kontakt tritt. Diese Deutung ist Tradition, keine Messung. Ohne genaue Geburtszeit ist der Aszendent nicht belastbar.","related":["grund-aszendent-mc","haus-1","haus-7"],"sources":["S22","S23","S10"],"claims":["c09","c08"],"kennzeichnung":{"typ":"gemischt","hinweis":"Geometrische Definition ist belegt; die Deutung als Auftreten ist Tradition."}},{"id":"faq-ruecklaeufig","slug":"was-bedeutet-ruecklaeufig","frage":"Was bedeutet es, wenn ein Planet rückläufig ist?","short_answer":"Der Planet bewegt sich nicht tatsächlich rückwärts. Von der Erde aus gesehen kehrt sich seine scheinbare Richtung vor dem Sternhintergrund zeitweise um.","long_answer":"Die scheinbare Rückläufigkeit entsteht durch die unterschiedlichen Bahngeschwindigkeiten von Erde und beobachtetem Planeten. Die Erde überholt einen äußeren Planeten auf der inneren Bahn; dadurch kehrt sich die projizierte Bewegung am Himmel zeitweise um [S15]. Astronomisch läuft der Planet weiter in derselben Richtung. In der Astrologie wird die Rückläufigkeit als Zeit der Verlangsamung, Überprüfung oder Innerlichkeit gedeutet. Besonders Merkur rückläufig ist ein populäres Motiv, oft verbunden mit Warnungen vor Verträgen oder Technik. Für solche konkreten Warnungen gibt es keine belastbare Evidenz [S09]. Sinnvoll ist die Trennung: Astronomisch ist die Rückläufigkeit berechenbar; astrologisch ist sie ein Symbol, keine Ursache für konkrete Ereignisse.","related":["grund-ruecklaeufigkeit","faktor-merkur","grund-transite"],"sources":["S15","S09"],"claims":["c14","c17"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomische Erklärung ist belegt; die Prüfungsdeutung ist Tradition ohne Wirkungsnachweis."}},{"id":"faq-orbis","slug":"was-ist-ein-orbis","frage":"Was ist ein Orbis?","short_answer":"Der Orbis ist die zulässige Abweichung von einem exakten Aspektwinkel. Er ist eine Konvention und variiert nach Schule, Planet und Aspekt.","long_answer":"Ein Aspekt ist eine Winkelbeziehung, zum Beispiel ein Quadrat bei 90 Grad. In der Praxis muss der Winkel nicht exakt sein: Der Orbis legt fest, wie weit die Abweichung sein darf, damit der Aspekt noch gilt [S11]. Ein Quadrat bei 87 Grad kann bei einem Orbis von 3 Grad noch als Quadrat gelten. Orben sind keine Naturkonstanten. Moderne psychologische Astrologie neigt zu weiteren Orben, Horary und traditionelle Schulen zu engeren; Sonne und Mond erhalten oft größere Spielräume als die äußeren Planeten [S11][S17]. Auch die Frage, ob ein Aspekt außerhalb der Zeichen noch zählt, wird unterschiedlich beantwortet. Wichtig ist, den verwendeten Orbis zu nennen, weil sonst zwei Deutungen nicht vergleichbar sind.","related":["grund-aspekt-orben","aspekt-quadrat","grund-radix-synthese"],"sources":["S11","S17"],"claims":["c10","c11"],"kennzeichnung":{"typ":"konvention","hinweis":"Winkeldefinition und schulabhängige Orb-Konventionen."}},{"id":"faq-haeusersysteme","slug":"warum-verschiedene-haeusersysteme","frage":"Warum gibt es verschiedene Häusersysteme?","short_answer":"Weil Häuser aus unterschiedlichen geometrischen und zeitlichen Konstruktionen abgeleitet werden. Kein System ist wissenschaftlich als das richtige erwiesen.","long_answer":"Häuser teilen das Horoskop in zwölf Lebensfelder, abhängig von Zeit und Ort. Es gibt mehrere Ansätze: Equal House teilt ab dem Aszendenten in 30-Grad-Schritten; Ganzzeichen-Häuser ordnen jedem Haus ein volles Zeichen zu; Placidus und andere Quadrantensysteme konstruieren die Hausspitzen aus Zeit- und Raumabschnitten [S10][S16]. Die Systeme liefern unterschiedliche Hausspitzen und damit unterschiedliche Zuordnungen von Planeten zu Häusern. Kein System ist wissenschaftlich als das richtige erwiesen; die Wahl ist eine Fachkonvention. Placidus ist im modernen Westen verbreitet, aber jenseits der Polarkreise nicht durchgehend definiert [S10]. In hohen Breiten werden deshalb oft Equal House oder Ganzzeichen-Häuser verwendet. Für die Deutung ist Transparenz wichtig: Ein Text sollte das verwendete System nennen.","related":["grund-haeuser-systeme","grund-aszendent-mc","haus-1"],"sources":["S10","S16"],"claims":["c08","c09"],"kennzeichnung":{"typ":"konvention","hinweis":"Die Existenz mehrerer Systeme und die Placidus-Grenze sind belegt; die Wahl ist Konvention."}},{"id":"faq-pluto","slug":"ist-pluto-ein-planet","frage":"Ist Pluto ein Planet?","short_answer":"Astronomisch gilt Pluto seit 2006 als Zwergplanet. In der modernen Astrologie wird er dennoch als Deutungsfaktor verwendet.","long_answer":"Pluto wurde am 18. Februar 1930 entdeckt und umrundet die Sonne in rund 248 Jahren [S20]. Seit der IAU-Entscheidung von 2006 wird er als Zwergplanet klassifiziert, nicht als Planet [S20]. Diese Einordnung ist ein astronomischer Status. In der modernen Astrologie wird Pluto weiterhin als Faktor für Macht, Tiefe und Transformation verwendet, oft als moderner Herrscher des Skorpions [S12]. Die beiden Fragen sind zu trennen: Die Astronomie beschreibt, was Pluto ist und wie er sich bewegt; die Astrologie ordnet ihm eine Bedeutung zu. Wer von den acht Planeten spricht, meint astronomisch Merkur bis Neptun; wer in der Astrologie von zehn Faktoren spricht, meint Sonne, Mond und acht Körper einschließlich Pluto.","related":["faktor-pluto","grund-herrschaft","zeichen-skorpion"],"sources":["S20","S12"],"claims":["c13","c12","c27"],"kennzeichnung":{"typ":"gemischt","hinweis":"Astronomischer Status und astrologische Verwendung sind getrennt belegt."}},{"id":"faq-vorhersage","slug":"kann-astrologie-gesundheit-geld-vorhersagen","frage":"Kann Astrologie Gesundheit, Geld oder Ereignisse vorhersagen?","short_answer":"Nein. Für sichere Vorhersagen zu Gesundheit, Geld, Beziehungen oder Ereignissen gibt es keine belastbare Evidenz.","long_answer":"Astrologische Aussagen zu Gesundheit, Geld, Trennung, Tod oder Erfolg sind prognostische Behauptungen. Kontrollierte Studien stützen sie nicht [S06][S09]. Es gibt keinen bekannten Mechanismus, der solche Effekte plausibel machen würde [S09]. Astrologie ist kein medizinisches, psychologisches, rechtliches oder finanzielles Verfahren. Wer astrologische Symbole für Reflexion nutzt, sollte sie nicht als Entscheidungsinstanz behandeln. Das gilt besonders für angstbesetzte Themen: Drohungen mit Transiten oder schlechten Aspekten sind ethisch problematisch und fachlich nicht gedeckt. Eine verantwortliche Darstellung sagt klar, was Tradition ist und was nicht. Sie verspricht keine Sicherheit und macht keine Angst.","related":["grund-ethik","grund-evidenz","grund-transite"],"sources":["S06","S09"],"claims":["c17","c19"],"kennzeichnung":{"typ":"empirie","hinweis":"Evidenzlage und redaktionelle Grenze; keine medizinische, rechtliche oder finanzielle Beratung."}},{"id":"faq-barnum","slug":"warum-wirken-beschreibungen-treffend","frage":"Warum wirken Horoskopbeschreibungen oft so treffend?","short_answer":"Weil sie häufig vage und allgemein genug sind, um auf viele Menschen zu passen. Diesen Effekt nennt man Barnum- oder Forer-Effekt.","long_answer":"Der Barnum- beziehungsweise Forer-Effekt beschreibt die Tendenz, allgemeine Persönlichkeitsbeschreibungen als ungewöhnlich treffend zu erleben, obwohl sie auf viele Menschen zutreffen [S21]. In einem klassischen Experiment erhielten alle Teilnehmenden denselben Text und bewerteten ihn dennoch als individuell passend [S21]. Astrologische Beschreibungen arbeiten oft mit solchen allgemeinen Formulierungen: Sie sind freundlich, mehrdeutig und lassen Spielraum für eigene Erinnerungen. Das erklärt Zustimmung, aber nicht Wahrheit. Ein weiterer Faktor ist der Bestätigungsfehler: Menschen erinnern sich eher an Treffer als an Fehlpassungen. Wer die Trefferquote prüfen will, sollte vorab konkrete, falsifizierbare Vorhersagen notieren und später ehrlich auszählen. Genau das tun kontrollierte Studien, und dort schneiden astrologische Radixdeutungen nicht besser ab als der Zufall [S08][S09].","related":["grund-sonnenzeichen-grenzen","grund-evidenz","grund-radix-synthese"],"sources":["S21","S08","S09"],"claims":["c20","c18","c17"],"kennzeichnung":{"typ":"empirie","hinweis":"Psychologischer Erklärungsansatz; keine Aussage über die Wahrheit einzelner Deutungen."}},{"id":"faq-sonnenzeichen","slug":"was-ist-ein-sonnenzeichen","frage":"Was ist ein Sonnenzeichen - und was nicht?","short_answer":"Das Sonnenzeichen ist die Position der Sonne im tropischen Zeichensektor zum Geburtszeitpunkt. Es ist ein Faktor von vielen, keine vollständige Persönlichkeit.","long_answer":"Das Sonnenzeichen beschreibt, in welchem 30-Grad-Sektor die Sonne zum Geburtszeitpunkt stand. Es ist der bekannteste, aber nicht der einzige Faktor der Astrologie. Eine Radix enthält Mond, weitere Planeten, Häuser, Achsen und Aspekte [S10][S11]. Die populäre Sonnenzeichen-Typologie verkürzt dieses Bild. Sie ist zudem empirisch nicht gestützt: Es gibt keine belastbare Evidenz für einen Zusammenhang zwischen Geburtsdatum und Persönlichkeit oder Intelligenz [S06]. Die Datumsgrenzen sind Näherungen und variieren je nach Jahr und Quelle [S06]. Das Sonnenzeichen kann als Einstieg in eine Bildsprache dienen und Reflexionsfragen anregen. Es ist kein Test, keine Diagnose und keine Identität. Wer mehr wissen will, kommt an Mond, Aszendent und Häusern nicht vorbei - und an der Frage, ob die Geburtszeit belastbar ist.","related":["faktor-sonne","grund-sonnenzeichen-grenzen","zeichen-widder"],"sources":["S06","S10","S11"],"claims":["c07","c06","c17"],"kennzeichnung":{"typ":"gemischt","hinweis":"Definition und Evidenzgrenze; die Nutzung als Reflexionsmotiv ist eine Entscheidung, keine Tatsache."}},{"id":"faq-geburtsdaten-website","slug":"braucht-die-website-geburtsdaten","frage":"Braucht die Website meine Geburtsdaten?","short_answer":"Nein. Der Lernbereich funktioniert ohne Geburtsdaten, ohne Konto und ohne Tracker. Eine echte Radixberechnung ist nicht Teil dieses Pakets.","long_answer":"Dieses Inhalts- und Strukturpaket ist als Lern- und Nachschlagebereich konzipiert. Es erklärt Zeichen, Faktoren, Häuser, Aspekte und Grundlagen, ohne eine individuelle Radix zu berechnen. Dafür sind keine Geburtsdaten nötig. Das ist bewusst so gewählt: Geburtsdaten sind personenbezogene Daten und brauchen einen klaren Zweck, eine Rechtsgrundlage und Schutz. Eine echte Radix- oder Transitberechnung wäre ein separater, technisch und rechtlich anspruchsvoller Schritt. Sie braucht belastbare Ephemeriden, Zeitzonen, Geodaten, eine dokumentierte Häuserkonvention und eine Lizenzklärung [S10][S22]. Zufallswerte oder geschätzte Positionen wären keine Berechnung und würden Scheingenauigkeit erzeugen. Der Lernbereich bleibt daher datensparsam: keine Geburtseingaben, keine Konten, keine Tracker.","related":["grund-berechnung","grund-ethik","grund-aszendent-mc"],"sources":["S10","S22","S23"],"claims":["c28","c09"],"kennzeichnung":{"typ":"konvention","hinweis":"Produkt- und Datenschutzentscheidung; keine Implementierung einer Berechnung."}},{"id":"faq-radix-lernen","slug":"wie-lernt-man-radixlesen","frage":"Wie lernt man, eine Radix zu lesen?","short_answer":"Indem man zuerst die einzelnen Ebenen lernt, dann gewichtet und schließlich eine Synthese mit Gegenprobe formuliert. Übung an fiktiven Beispielen hilft, ohne reale Personen zu deuten.","long_answer":"Ein sinnvoller Lernweg führt vom Einfachen zum Komplexen: zuerst die zwölf Zeichen mit Element, Modalität und Herrscher; dann die zehn Faktoren; dann Häuser, Achsen und Aspekte; schließlich die Synthese [S10][S11][S12]. Wichtig ist, die Ebenen nicht zu verwechseln: Ein Zeichen ist kein Haus, ein Aspekt ist kein Ereignis, ein Herrscher ist kein Schicksal. Für die Synthese hilft eine feste Reihenfolge: Leitfrage, Grundstruktur, Schwerpunkte, Herrscher und Achsen, Spannungen und Ressourcen, Gegenprobe, Sprache prüfen. Übung an fiktiven Figuren ist sinnvoll, weil sie keine Persönlichkeitsrechte verletzt und Fehler erlaubt. Reale Menschen sollten nur mit Einwilligung und ohne diagnostische Ambition gedeutet werden. Und immer gilt: Eine astrologische Lesart ist eine Hypothese, keine Messung [S21].","related":["grund-radix-synthese","beispiel-mira","lernpfad-stufe-4"],"sources":["S10","S11","S12","S21"],"claims":["c07","c20"],"kennzeichnung":{"typ":"deutungstradition","hinweis":"Didaktischer Lernweg; die Methode ist Tradition, die Warnung vor Diagnosen folgt aus der Evidenzlage."}},{"id":"faq-astronomie","slug":"ist-astrologie-astronomie","frage":"Ist Astrologie dasselbe wie Astronomie?","short_answer":"Nein. Astronomie ist die Naturwissenschaft der Himmelskörper; Astrologie ist ein Deutungssystem, das ihnen Bedeutungen zuordnet.","long_answer":"Astronomie beschreibt, was Himmelskörper sind, wie sie sich bewegen und welche physikalischen Gesetze gelten. Astrologie deutet Positionen und Bewegungen als Zeichen für irdische und menschliche Zusammenhänge [S07]. Beide nutzen teilweise dieselben Beobachtungen, aber mit unterschiedlichen Zielen und Methoden. Die eine fragt: Wie ist der Himmel beschaffen? Die andere fragt: Was könnte diese Konstellation symbolisch bedeuten? Die Verwechslung ist alt und wird durch gemeinsame Geschichte begünstigt. Sie ist trotzdem ein Kategorienfehler. Astronomische Fakten wie die Präzession oder die 13 ekliptikalen Sternbilder widerlegen die Astrologie nicht automatisch, weil das tropische System sie nicht als Fehler behandelt [S13]. Aber sie zeigen, dass astrologische Aussagen nicht aus Astronomie abgeleitet werden können. Wer beides sauber trennt, kann über beides reden, ohne sie zu vermischen.","related":["grund-begriff","grund-geschichte","grund-zeichen-sternbilder"],"sources":["S07","S13","S19"],"claims":["c23","c02","c05"],"kennzeichnung":{"typ":"gemischt","hinweis":"Begriffs- und Methodenunterscheidung; keine Wirkungsbehauptung."}}];

export const GLOSSAR = [{"id":"gloss-aszendent","slug":"aszendent","term":"Aszendent","definition":"Der Punkt der Ekliptik, der zum Geburtszeitpunkt am östlichen Horizont aufgeht. Er hängt von Zeit und Ort ab und wird traditionell mit Auftreten und Zugang verbunden.","see_also":["gloss-deszendent","grund-aszendent-mc","haus-1"],"sources":["S22"],"claims":["c09"]},{"id":"gloss-deszendent","slug":"deszendent","term":"Deszendent","definition":"Der Gegenpunkt des Aszendenten am westlichen Horizont. Er wird traditionell mit Begegnung, Partnerschaft und dem Gegenüber verbunden.","see_also":["gloss-aszendent","haus-7"],"sources":["S10","S22"],"claims":["c09"]},{"id":"gloss-mc","slug":"mc","term":"MC (Medium Coeli)","definition":"Der Punkt der Ekliptik, der den oberen Meridian eines Ortes zum Geburtszeitpunkt schneidet. Er wird traditionell mit öffentlicher Rolle und Beruf verbunden.","see_also":["gloss-ic","haus-10","grund-aszendent-mc"],"sources":["S23"],"claims":["c09"]},{"id":"gloss-ic","slug":"ic","term":"IC (Imum Coeli)","definition":"Der untere Meridianpunkt der Ekliptik, Gegenpunkt des MC. Er wird traditionell mit Herkunft, Zuhause und innerem Fundament verbunden.","see_also":["gloss-mc","haus-4"],"sources":["S10","S23"],"claims":["c09"]},{"id":"gloss-achse","slug":"achse","term":"Achse","definition":"Paar gegenüberliegender Punkte im Horoskop, vor allem AC/DC und MC/IC. Die Achsen bleiben in den gängigen Häusersystemen gleich.","see_also":["gloss-aszendent","gloss-mc","grund-aszendent-mc"],"sources":["S16","S22"],"claims":["c09"]},{"id":"gloss-aspekt","slug":"aspekt","term":"Aspekt","definition":"Eine Winkelbeziehung zwischen zwei Faktoren im Horoskop, etwa Konjunktion, Sextil, Quadrat, Trigon oder Opposition.","see_also":["gloss-orbis","grund-aspekt-orben","aspekt-konjunktion"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-orbis","slug":"orbis","term":"Orbis","definition":"Die zulässige Abweichung von einem exakten Aspektwinkel. Der Orbis ist eine Konvention und variiert nach Schule, Planet und Aspekt.","see_also":["gloss-aspekt","gloss-partil","grund-aspekt-orben"],"sources":["S11","S17"],"claims":["c11"]},{"id":"gloss-applikation","slug":"applikation","term":"Applikativer Aspekt","definition":"Ein Aspekt, bei dem sich die beteiligten Faktoren einander annähern. Er gilt manchen Schulen als prägnanter als ein sich entfernender Aspekt.","see_also":["gloss-separation","gloss-aspekt"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-separation","slug":"separation","term":"Separater Aspekt","definition":"Ein Aspekt, bei dem sich die beteiligten Faktoren voneinander entfernen. Die Bewertung ist schulabhängig.","see_also":["gloss-applikation","gloss-aspekt"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-partil","slug":"partil","term":"Partil","definition":"Bezeichnung für einen fast exakten Aspekt. Je exakter der Winkel, desto prägnanter wird der Aspekt in vielen Schulen erlebt.","see_also":["gloss-orbis","gloss-aspekt"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-konjunktion","slug":"konjunktion-glossar","term":"Konjunktion","definition":"Aspekt bei etwa 0 Grad: Zwei Faktoren stehen im selben Tierkreisbereich. Traditionell eine Verdichtung, keine automatische Bewertung.","see_also":["aspekt-konjunktion","gloss-opposition"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-sextil","slug":"sextil-glossar","term":"Sextil","definition":"Aspekt bei 60 Grad. Traditionell als Gelegenheit und Anregung gelesen, nicht als garantierte Harmonie.","see_also":["aspekt-sextil","gloss-trigon"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-quadrat","slug":"quadrat-glossar","term":"Quadrat","definition":"Aspekt bei 90 Grad. Traditionell als Spannung gelesen, die Handlung und Reifung erzwingen kann.","see_also":["aspekt-quadrat","gloss-opposition"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-trigon","slug":"trigon-glossar","term":"Trigon","definition":"Aspekt bei 120 Grad. Traditionell als fließendes Zusammenspiel gelesen, das auch bequem machen kann.","see_also":["aspekt-trigon","gloss-sextil"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-opposition","slug":"opposition-glossar","term":"Opposition","definition":"Aspekt bei 180 Grad. Traditionell als Gegenüberstellung gelesen, die Ausgleich und Verhandlung verlangt.","see_also":["aspekt-opposition","gloss-konjunktion"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-halbsextil","slug":"halbsextil","term":"Halbsextil","definition":"Nebenaspekt bei 30 Grad. Wird je nach Schule unterschiedlich gewichtet und oft nur mit engem Orbis verwendet.","see_also":["gloss-aspekt","gloss-quincunx"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-quincunx","slug":"quincunx","term":"Quincunx","definition":"Nebenaspekt bei 150 Grad. Wird traditionell als Spannung zwischen unvereinbar erscheinenden Bereichen gelesen.","see_also":["gloss-aspekt","gloss-halbsextil"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-tierkreis","slug":"tierkreis","term":"Tierkreis","definition":"Der Gürtel von zwölf Zeichen entlang der Ekliptik. Im tropischen System sind es zwölf gleiche Sektoren von je 30 Grad.","see_also":["gloss-zeichen","gloss-ekliptik","grund-tropisch-siderisch"],"sources":["S14"],"claims":["c02","c04"]},{"id":"gloss-tropisch","slug":"tropisch","term":"Tropischer Tierkreis","definition":"Tierkreis, der am Frühlingspunkt beginnt und die Zeichen an den Jahreszeiten orientiert. Die in diesem Paket verwendete Konvention.","see_also":["gloss-siderisch","gloss-fruehlingspunkt","grund-tropisch-siderisch"],"sources":["S13","S19"],"claims":["c02"]},{"id":"gloss-siderisch","slug":"siderisch","term":"Siderischer Tierkreis","definition":"Tierkreis, der sich an der Sternposition orientiert und die Präzession mit einem Ayanamsa korrigiert. Vor allem in der vedischen Astrologie verbreitet.","see_also":["gloss-tropisch","gloss-ayanamsa","grund-tropisch-siderisch"],"sources":["S13"],"claims":["c03"]},{"id":"gloss-ayanamsa","slug":"ayanamsa","term":"Ayanamsa","definition":"Korrekturwert, der den Unterschied zwischen tropischem und siderischem Nullpunkt angibt. Der Wert ist schulabhängig.","see_also":["gloss-siderisch","gloss-praezession"],"sources":["S13"],"claims":["c03"]},{"id":"gloss-praezession","slug":"praezession","term":"Präzession","definition":"Die langsame Kreiselbewegung der Erdachse mit einer Periode von etwa 26.000 Jahren. Sie verschiebt den Frühlingspunkt gegenüber den Sternbildern.","see_also":["gloss-fruehlingspunkt","gloss-ayanamsa","grund-zeichen-sternbilder"],"sources":["S01","S03"],"claims":["c01"]},{"id":"gloss-ekliptik","slug":"ekliptik-glossar","term":"Ekliptik","definition":"Die scheinbare jährliche Bahn der Sonne am Himmel, also die Projektion der Erdbahn auf die Himmelssphäre.","see_also":["gloss-tierkreis","gloss-himmelsaequator","grund-ekliptik"],"sources":["S14"],"claims":["c25"]},{"id":"gloss-himmelsaequator","slug":"himmelsaequator","term":"Himmelsäquator","definition":"Die Projektion des Erdäquators auf die Himmelssphäre. Sein Schnittpunkt mit der Ekliptik definiert den Frühlingspunkt.","see_also":["gloss-ekliptik","gloss-fruehlingspunkt"],"sources":["S01","S14"],"claims":["c25"]},{"id":"gloss-fruehlingspunkt","slug":"fruehlingspunkt","term":"Frühlingspunkt","definition":"Der Punkt, an dem die Sonne den Himmelsäquator nach Norden kreuzt. Er ist der Nullpunkt des tropischen Tierkreises.","see_also":["gloss-tropisch","gloss-praezession","grund-tropisch-siderisch"],"sources":["S13","S19"],"claims":["c02"]},{"id":"gloss-zeichen","slug":"zeichen","term":"Zeichen","definition":"Ein 30-Grad-Sektor des Tierkreises. Zeichen sind keine Sternbilder; im tropischen System beginnen sie am Frühlingspunkt.","see_also":["gloss-sternbild","gloss-tierkreis","grund-zeichen-sternbilder"],"sources":["S19","S14"],"claims":["c02","c05"]},{"id":"gloss-sternbild","slug":"sternbild","term":"Sternbild","definition":"Ein astronomisch definiertes Areal am Himmel mit festen Grenzen. Die IAU kennt 88 Sternbilder; zwölf davon liegen klassisch im Tierkreis, dazu Ophiuchus.","see_also":["gloss-zeichen","grund-zeichen-sternbilder"],"sources":["S04","S05"],"claims":["c05"]},{"id":"gloss-haus","slug":"haus","term":"Haus","definition":"Eines von zwölf Lebensfeldern im Horoskop. Häuser hängen von Geburtszeit und Ort ab und sind von den Zeichen zu unterscheiden.","see_also":["gloss-hausspitze","grund-haeuser-systeme","haus-1"],"sources":["S10"],"claims":["c08"]},{"id":"gloss-hausspitze","slug":"hausspitze","term":"Hausspitze (Cusp)","definition":"Der Anfangsgrad eines Hauses. Die Lage der Hausspitzen hängt vom Häusersystem ab und bestimmt, welches Zeichen ein Haus regiert.","see_also":["gloss-haus","gloss-herrscher","grund-haeuser-systeme"],"sources":["S10","S12"],"claims":["c08","c26"]},{"id":"gloss-ganzzeichenhaus","slug":"ganzzeichenhaus","term":"Ganzzeichen-Haus","definition":"Häusersystem, bei dem jedes Haus ein volles Zeichen umfasst; das erste Haus beginnt mit dem Zeichen des Aszendenten.","see_also":["gloss-equal-house","gloss-placidus","grund-haeuser-systeme"],"sources":["S10"],"claims":["c08"]},{"id":"gloss-placidus","slug":"placidus","term":"Placidus","definition":"Zeitbasiertes Quadrantenhäusersystem, das im modernen Westen verbreitet ist. Jenseits der Polarkreise nicht durchgehend definiert.","see_also":["gloss-koch","gloss-equal-house","grund-haeuser-systeme"],"sources":["S10","S16"],"claims":["c08"]},{"id":"gloss-koch","slug":"koch","term":"Koch","definition":"Häusersystem, das auf der Geburtszeit und der geografischen Breite aufbaut. Es ist eine Alternative zu Placidus, keine wissenschaftlich ausgezeichnete Norm.","see_also":["gloss-placidus","gloss-campanus"],"sources":["S10","S16"],"claims":["c08"]},{"id":"gloss-campanus","slug":"campanus","term":"Campanus","definition":"Häusersystem, das die Himmelssphäre in gleiche Raumabschnitte teilt und auf die Ekliptik projiziert.","see_also":["gloss-regiomontanus","gloss-placidus"],"sources":["S10"],"claims":["c08"]},{"id":"gloss-regiomontanus","slug":"regiomontanus","term":"Regiomontanus","definition":"Häusersystem, das den Himmelsäquator in gleiche Abschnitte teilt und die Teilung auf die Ekliptik überträgt.","see_also":["gloss-campanus","gloss-placidus"],"sources":["S10"],"claims":["c08"]},{"id":"gloss-equal-house","slug":"equal-house","term":"Equal House","definition":"Häusersystem, bei dem ab dem Aszendenten zwölf gleich große Abschnitte von je 30 Grad gebildet werden. In hohen Breiten oft robuster als Placidus.","see_also":["gloss-ganzzeichenhaus","gloss-placidus"],"sources":["S10"],"claims":["c08"]},{"id":"gloss-winkelhaus","slug":"winkelhaus","term":"Winkelhaus","definition":"Die Häuser 1, 4, 7 und 10. Sie liegen an den Achsen und gelten traditionell als besonders prägnant.","see_also":["gloss-sukzedentenhaus","gloss-kadentenhaus","haus-1"],"sources":["S10"],"claims":["c08"]},{"id":"gloss-sukzedentenhaus","slug":"sukzedentenhaus","term":"Sukzedentenhaus","definition":"Die Häuser 2, 5, 8 und 11. Sie folgen auf die Winkelhäuser und gelten traditionell als stabilisierend.","see_also":["gloss-winkelhaus","gloss-kadentenhaus","haus-2"],"sources":["S10"],"claims":["c08"]},{"id":"gloss-kadentenhaus","slug":"kadentenhaus","term":"Kadentenhaus","definition":"Die Häuser 3, 6, 9 und 12. Sie gelten traditionell als Häuser des Übergangs und der Vorbereitung.","see_also":["gloss-winkelhaus","gloss-sukzedentenhaus","haus-3"],"sources":["S10"],"claims":["c08"]},{"id":"gloss-herrscher","slug":"herrscher","term":"Herrscher","definition":"Der Planet, der einem Zeichen zugeordnet ist. Traditionell regieren sieben sichtbare Himmelskörper die Zeichen; moderne Systeme ergänzen Uranus, Neptun und Pluto.","see_also":["gloss-domizil","gloss-dispositor","grund-herrschaft"],"sources":["S12"],"claims":["c12"]},{"id":"gloss-dispositor","slug":"dispositor","term":"Dispositor","definition":"Der Herrscher des Zeichens, in dem ein Planet steht. Dispositor-Ketten folgen den Herrschaftsbeziehungen durch das Horoskop.","see_also":["gloss-herrscher","grund-herrschaft"],"sources":["S12"],"claims":["c12","c26"]},{"id":"gloss-domizil","slug":"domizil","term":"Domizil","definition":"Ein Planet steht in einem Zeichen, das er selbst regiert. In der traditionellen Würdenlehre gilt das als starke Stellung.","see_also":["gloss-exil","gloss-herrscher","grund-herrschaft"],"sources":["S12"],"claims":["c26"]},{"id":"gloss-exil","slug":"exil","term":"Exil","definition":"Ein Planet steht im Gegenzeichen seines Domizils. In der Würdenlehre gilt das als geschwächte Stellung.","see_also":["gloss-domizil","gloss-fall","grund-herrschaft"],"sources":["S12"],"claims":["c26"]},{"id":"gloss-erhoehung","slug":"erhoehung","term":"Erhöhung","definition":"Eine weitere Würde in der traditionellen Astrologie, in der ein Planet in einem bestimmten Zeichen als besonders wirksam gilt.","see_also":["gloss-fall","gloss-domizil","grund-herrschaft"],"sources":["S12"],"claims":["c26"]},{"id":"gloss-fall","slug":"fall","term":"Fall","definition":"Das Gegenzeichen der Erhöhung. In der Würdenlehre gilt diese Stellung als geschwächt.","see_also":["gloss-erhoehung","gloss-exil","grund-herrschaft"],"sources":["S12"],"claims":["c26"]},{"id":"gloss-element","slug":"element","term":"Element","definition":"Eine der vier symbolischen Qualitäten Feuer, Erde, Luft und Wasser. Jedes Zeichen gehört einem Element an.","see_also":["element-feuer","element-erde","element-luft","element-wasser"],"sources":["S14"],"claims":["c02"]},{"id":"gloss-modalitaet","slug":"modalitaet","term":"Modalität","definition":"Die Einteilung der Zeichen in kardinal, fix und veränderlich. Sie beschreibt einen Rhythmus, keine Persönlichkeitseigenschaft.","see_also":["modalitaet-kardinal","modalitaet-fix","modalitaet-veraenderlich"],"sources":["S14"],"claims":["c02"]},{"id":"gloss-polaritaet","slug":"polaritaet","term":"Polarität","definition":"Die Einteilung der Zeichen in yang oder aktiv und yin oder empfangend. Die Zuordnung ist traditionell und kulturell geprägt.","see_also":["gloss-element","gloss-modalitaet"],"sources":["S14"],"claims":["c02"]},{"id":"gloss-triplizitaet","slug":"triplizitaet","term":"Triplizität","definition":"Gruppe von drei Zeichen desselben Elements. Die Triplizitäten bilden die Grundlage der Elementlehre.","see_also":["gloss-element","element-feuer"],"sources":["S14"],"claims":["c02"]},{"id":"gloss-sonnenzeichen","slug":"sonnenzeichen","term":"Sonnenzeichen","definition":"Die Position der Sonne im tropischen Zeichensektor zum Geburtszeitpunkt. Ein Faktor unter vielen, keine vollständige Persönlichkeit.","see_also":["faktor-sonne","grund-sonnenzeichen-grenzen","gloss-mondzeichen"],"sources":["S19","S06"],"claims":["c07","c17"]},{"id":"gloss-mondzeichen","slug":"mondzeichen","term":"Mondzeichen","definition":"Die Position des Mondes im Zeichensektor zum Geburtszeitpunkt. Ohne genaue Geburtszeit oft unsicher, weil der Mond den Sektor etwa alle 2,46 Tage wechselt.","see_also":["faktor-mond","gloss-sonnenzeichen","grund-mond"],"sources":["S18"],"claims":["c15"]},{"id":"gloss-radix","slug":"radix","term":"Radix","definition":"Die Horoskopkarte zum Geburtszeitpunkt an einem Ort. Sie enthält Faktoren, Zeichen, Häuser, Achsen und Aspekte.","see_also":["grund-radix-synthese","gloss-transit","grund-aszendent-mc"],"sources":["S10","S11"],"claims":["c07"]},{"id":"gloss-transit","slug":"transit","term":"Transit","definition":"Die aktuelle Himmelsstellung eines Faktors im Verhältnis zu einer festen Radix. Wird traditionell als Zeitqualität gelesen, nicht als sichere Ereignisvorhersage.","see_also":["grund-transite","gloss-radix","gloss-ruecklaeufigkeit"],"sources":["S10","S11"],"claims":["c07","c17"]},{"id":"gloss-ruecklaeufigkeit","slug":"ruecklaeufigkeit-glossar","term":"Rückläufigkeit","definition":"Die scheinbare Umkehr der Bewegung eines Planeten vor dem Sternhintergrund. Sie entsteht durch unterschiedliche Bahngeschwindigkeiten, nicht durch eine echte Richtungsumkehr.","see_also":["grund-ruecklaeufigkeit","faktor-merkur","gloss-transit"],"sources":["S15"],"claims":["c14"]},{"id":"gloss-synodisch","slug":"synodischer-monat","term":"Synodischer Monat","definition":"Die Zeit von einer Mondphase zur nächsten gleichen Phase: 29,53 Tage. Er ist länger als der siderische Monat, weil sich die Erde weiterbewegt.","see_also":["gloss-siderischer-monat","grund-mond","faktor-mond"],"sources":["S18"],"claims":["c15"]},{"id":"gloss-siderischer-monat","slug":"siderischer-monat","term":"Siderischer Monat","definition":"Die Zeit, in der der Mond einmal relativ zu den Sternen die Erde umrundet: 27,3217 Tage.","see_also":["gloss-synodisch","grund-mond"],"sources":["S18"],"claims":["c15"]},{"id":"gloss-ephemeride","slug":"ephemeride","term":"Ephemeride","definition":"Tabelle oder Datensatz mit berechneten Positionen von Himmelskörpern zu bestimmten Zeiten. Eine echte Radixberechnung braucht belastbare Ephemeriden.","see_also":["grund-berechnung","gloss-radix"],"sources":["S10"],"claims":["c28"]},{"id":"gloss-stellium","slug":"stellium","term":"Stellium","definition":"Häufung von mindestens drei Faktoren in einem Zeichen oder Haus. Wird traditionell als Schwerpunkt gelesen; die genauen Kriterien sind schulabhängig.","see_also":["grund-radix-synthese","gloss-aspektfigur"],"sources":["S10","S11"],"claims":["c07"]},{"id":"gloss-aspektfigur","slug":"aspektfigur","term":"Aspektfigur","definition":"Muster aus mehreren Aspekten, etwa ein Großes Trigon oder ein T-Quadrat. Die Deutung ist Tradition und schulabhängig.","see_also":["gloss-stellium","grund-aspekt-orben"],"sources":["S11"],"claims":["c10"]},{"id":"gloss-barnum","slug":"barnum-effekt","term":"Barnum-Effekt","definition":"Die Tendenz, vage und allgemeine Persönlichkeitsbeschreibungen als ungewöhnlich treffend zu erleben. Auch Forer-Effekt genannt.","see_also":["grund-sonnenzeichen-grenzen","gloss-bestaetigungsfehler"],"sources":["S21"],"claims":["c20"]},{"id":"gloss-bestaetigungsfehler","slug":"bestaetigungsfehler","term":"Bestätigungsfehler","definition":"Die Neigung, Informationen zu bevorzugen, die bestehende Erwartungen bestätigen, und Widersprechendes zu übersehen.","see_also":["gloss-barnum","grund-evidenz"],"sources":["S21","S09"],"claims":["c20","c17"]},{"id":"gloss-divination","slug":"divination","term":"Divination","definition":"Deutungspraxis, die Zeichen oder Bilder nutzt, um Zusammenhänge oder zukünftige Entwicklungen zu erschließen. Astrologie wird als Form der Divination eingeordnet.","see_also":["grund-begriff","grund-geschichte"],"sources":["S07"],"claims":["c23"]},{"id":"gloss-determinismus","slug":"determinismus","term":"Determinismus","definition":"Die Annahme, Ereignisse seien vollständig durch vorherige Bedingungen festgelegt. Eine deterministische Astrologie behauptet, das Horoskop lege das Leben fest; diese Annahme ist nicht belegt.","see_also":["grund-ethik","grund-evidenz"],"sources":["S09"],"claims":["c17","c19"]},{"id":"gloss-deutung","slug":"deutung","term":"Deutung","definition":"Die Zuordnung von Bedeutung zu einem Zeichen, einer Konstellation oder einem Aspekt. Deutung ist Interpretation, nicht Messung.","see_also":["grund-radix-synthese","gloss-synthese"],"sources":["S07"],"claims":["c07","c23"]},{"id":"gloss-synthese","slug":"synthese","term":"Synthese","definition":"Die Zusammenführung mehrerer Deutungsebenen zu einer gewichteten Lesart. Eine Synthese bleibt Hypothese und sollte ihre Grenzen nennen.","see_also":["grund-radix-synthese","gloss-deutung"],"sources":["S10","S11"],"claims":["c07"]},{"id":"gloss-mondknoten","slug":"mondknoten","term":"Mondknoten","definition":"Die Schnittpunkte der Mondbahn mit der Ekliptik. In der Astrologie werden sie als Entwicklungsachse gedeutet; astronomisch sind sie berechenbare Bahnpunkte.","see_also":["faktor-mond","grund-transite"],"sources":["S18"],"claims":["c15"]}];

export const QUELLEN = [{"id":"S01","titel":"Chapter 2: Reference Systems","herausgeber":"NASA Science","url":"https://science.nasa.gov/learn/basics-of-space-flight/chapter2-1/","typ":"referenzwerk","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"NASA-Textinhalte gelten überwiegend als gemeinfrei. Hier nur kurze Zitate und Paraphrase; keine Übernahme ganzer Passagen, keine NASA-Logos.","abrufstatus":"vollständig abgerufen","kurzzitat":"precession causes the axis of Earth to describe a circle having a 23.4 degree radius ... over about 26,000 years ... .014 degree each year","einsatz":["Präzession","Bezugssysteme","Sternorte"],"grenzen":"Technische Referenz für Raumfahrt; keine astrologischen Aussagen."},{"id":"S02","titel":"Planetary Fact Sheet - Metric","herausgeber":"NASA NSSDCA","url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","typ":"referenzwerk","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"NASA-Daten, überwiegend gemeinfrei. Zahlenwerte hier paraphrasiert; Quellenangabe erforderlich.","abrufstatus":"vollständig abgerufen; Seite zuletzt aktualisiert am 2025-03-18","kurzzitat":"Orbital Period (days): Mercury 88.0, Venus 224.7, Earth 365.2, Mars 687.0, Jupiter 4331, Saturn 10,747, Uranus 30,589, Neptune 59,800, Pluto 90,560","einsatz":["Umlaufzeiten","Achsenneigung","Pluto als Zwergplanet im Datenblatt"],"grenzen":"Mittlere Bahndaten; keine Ephemeriden für einzelne Tage."},{"id":"S03","titel":"Nutation and Precession","herausgeber":"NASA Earth Sciences","url":"https://earth.gsfc.nasa.gov/geo/multimedia/nutation-and-precession","typ":"referenzwerk","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"NASA-Inhalt, überwiegend gemeinfrei; kurze Paraphrase mit Quellenangabe.","abrufstatus":"vollständig abgerufen","kurzzitat":"the spin axis appears to trace a circle ... over a long period of time (approximately 26,000 years)","einsatz":["Präzession als langfristige Achsenbewegung"],"grenzen":"Erklärung der Bewegung, keine Aussage zu Tierkreisdeutung."},{"id":"S04","titel":"The Constellations","herausgeber":"International Astronomical Union (IAU)","url":"https://www.iau.org/IAU/IAU/Astronomy-FAQs/Constellations.aspx","typ":"referenzwerk","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"IAU-Webtext; kurze Zitate mit Quellenangabe, keine Übernahme größerer Abschnitte.","abrufstatus":"vollständig abgerufen","kurzzitat":"At its first General Assembly held in Rome in 1922, the IAU ... agreed on a list of 88 constellations ... boundaries approved ... 1928, published 1930","einsatz":["88 Sternbilder","Grenzen und Geschichte der Sternbilder"],"grenzen":"Sternbilder sind astronomische Areale, keine astrologischen Zeichen."},{"id":"S05","titel":"A Brief Guide to the Zodiac","herausgeber":"timeanddate.com (Dean Clark)","url":"https://www.timeanddate.com/astronomy/zodiac-guide.html","typ":"sekundaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"Urheberrechtlich geschützt; nur kurze Zitate und Paraphrase mit Quellenangabe.","abrufstatus":"vollständig abgerufen","kurzzitat":"The Sun actually passes through another constellation known as Ophiuchus ... not included ... twelve equal sections of 30 degrees","einsatz":["Ophiuchus","Zwölfteilung","Präzession"],"grenzen":"Populärwissenschaftliche Darstellung; für Detailfragen IAU-Quellen vorziehen."},{"id":"S06","titel":"Zodiac | Signs, Dates, Symbols, Months, Astrology, & Facts","herausgeber":"Encyclopädia Britannica","url":"https://www.britannica.com/topic/zodiac","typ":"referenzwerk","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"Urheberrechtlich geschützt; nur kurze Zitate mit Quellenangabe, keine Übernahme.","abrufstatus":"vollständig abgerufen","kurzzitat":"Because of the precession of the equinoxes ... the zodiac sign dates ... no longer correspond to the actual constellation. Astrology is not supported by science. No correlation has been found between birth dates and personality or intelligence.","einsatz":["Zeichendaten","Präzession","Evidenzlage"],"grenzen":"Enzyklopädie-Übersicht; Datumsangaben dort weichen von anderen Publikationen um etwa einen Tag ab."},{"id":"S07","titel":"Astrology | Chart, Zodiac Signs, Meaning, Definition, History","herausgeber":"Encyclopädia Britannica (David E. Pingree)","url":"https://www.britannica.com/topic/astrology","typ":"referenzwerk","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"Urheberrechtlich geschützt; kurze Zitate mit Quellenangabe.","abrufstatus":"vollständig abgerufen","kurzzitat":"astrology, type of divination ... widely considered today to be a pseudoscience ... millions of people ... put their faith in such systems","einsatz":["Definition","Geschichte","Wissenschaftliche Einordnung","Typen der Astrologie"],"grenzen":"Übersichtsartikel; keine vollständige Schulgeschichte."},{"id":"S08","titel":"A double-blind test of astrology","herausgeber":"Nature 318, 419-425 (Shawn Carlson, 1985)","url":"https://www.nature.com/articles/318419a0","typ":"primaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"Paywall; nur Abstract eingesehen. Kurzes Zitat, kein Volltextzugriff, keine Übernahme von Tabellen.","abrufstatus":"nur Abstract öffentlich abrufbar; Volltext nicht eingesehen","kurzzitat":"Two double-blind tests were made of the thesis that astrological 'natal charts' can be used to describe accurately personality traits of test subjects.","einsatz":["Empirische Prüfung der Radixdeutung"],"grenzen":"Eine Studie mit methodischen Debatten; kein Beweis für oder gegen jede Form astrologischer Praxis. Ergebnis laut Sekundärliteratur nicht besser als Zufall."},{"id":"S09","titel":"Astrology and science","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Astrology_and_science","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Nur Faktenentnahme und kurze Zitate mit Quellenangabe; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"Scientific testing has found no evidence to support the premises ... the most famous test ... led to the conclusion that natal astrology performed no better than chance ... no proposed mechanism","einsatz":["Forschungsstand","Carlson-Test","Mechanismus-Kritik"],"grenzen":"Tertiärquelle; Aussagen wurden gegen S06, S07 und S08 geprüft."},{"id":"S10","titel":"House (astrology)","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/House_(astrology)","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"divide the horoscope into ... twelve houses whose positions depend on time and location rather than on date ... Placidus ... most commonly used ... not defined beyond polar circles ... equal house ... 30 degree increments starting from the degree of the ascendant","einsatz":["Häuser","Häusersysteme","Placidus-Grenzen","Equal House"],"grenzen":"Tertiärquelle mit wechselnder Belegqualität; Systemnamen und Grundprinzipien wurden quergeprüft."},{"id":"S11","titel":"Astrological aspect","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Astrological_aspect","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"conjunction ... 0-10 degrees ... trine ... 120 degrees ... an orb of 5-10 degrees is allowed ... easy (60 sextile or 120 trine) or hard (90 square or 180 opposition)","einsatz":["Hauptaspekte","Winkel","Orben"],"grenzen":"Tertiärquelle; keine normative Festlegung von Orben."},{"id":"S12","titel":"Domicile (astrology)","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Domicile_(astrology)","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"each sign is ruled by one of the 7 visible planets ... modern astrologers assign ... Pluto ... Uranus ... Neptune","einsatz":["Herrschaft","traditionelle und moderne Zuordnung"],"grenzen":"Tertiärquelle; Zuordnungen sind Konventionen, keine Naturgesetze."},{"id":"S13","titel":"Sidereal and tropical astrology","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Sidereal_and_tropical_astrology","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"tropical systems consider 0 degrees of Aries as always coinciding with the March equinox ... sidereal ... maintains the alignment ... via ... ayanamsas ... drift apart over the centuries","einsatz":["tropisch vs. siderisch","Ayanamsa","Präzessionsfolge"],"grenzen":"Tertiärquelle; Differenzwerte sind schulabhängig."},{"id":"S14","titel":"Zodiac","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Zodiac","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"belt-shaped region ... approximately 8 degrees north and south of the ecliptic ... divided ... into 12 equal parts ... each occupying 30 degrees","einsatz":["Zodiak-Gürtel","Zwölfteilung","Ekliptik"],"grenzen":"Tertiärquelle; Definitionen wurden mit S05, S06 und S19 abgeglichen."},{"id":"S15","titel":"Apparent retrograde motion","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Apparent_retrograde_motion","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"the term refers to planets, as they appear from Earth, stopping briefly and reversing direction ... in reality ... perpetually orbit in the same uniform direction","einsatz":["Rückläufigkeit als Scheinbewegung"],"grenzen":"Tertiärquelle; physikalische Erklärung ist Standardastronomie."},{"id":"S16","titel":"House System","herausgeber":"Astrodienst Astrowiki","url":"http://www.astro.com/astrowiki/en/House_System","typ":"sekundaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"Urheberrechtlich geschützt; nur Suchsnippet eingesehen, kein Volltextabruf.","abrufstatus":"Direktabruf nicht möglich (Bot-Schutz); nur Suchsnippet vom 2026-11-01","kurzzitat":"no matter which system is used, the axes Ascendant/Descendant and Medium Coeli/Imum Coeli stay the same ... The Placidus House System is the most commonly used","einsatz":["Achseninvarianz","Placidus-Verbreitung"],"grenzen":"Nur Snippet; als schwache Stütze markiert, Kernaussagen auch in S10 belegt."},{"id":"S17","titel":"Orb - Astrodienst Astrowiki","herausgeber":"Astrodienst Astrowiki","url":"https://www.astro.com/astrowiki/en/Orb","typ":"sekundaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"Urheberrechtlich geschützt; nur Suchsnippet eingesehen, kein Volltextabruf.","abrufstatus":"Direktabruf durch Bot-Schutz blockiert; nur Suchsnippet vom 2026-11-01","kurzzitat":"modern astrologers allow larger orbs for the sun and moon, of perhaps 10-12 degrees ... narrower orbs for the other planets, perhaps 5-7 degrees ... Psychological Astrology tends to use larger orbs, whereas Horary Astrology tends to work with tighter ones","einsatz":["Orb-Größen","Schulabhängigkeit"],"grenzen":"Nur Snippet; keine normative Quelle, nur Beispielkonvention."},{"id":"S18","titel":"Moon Fact Sheet","herausgeber":"NASA NSSDCA","url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/moonfact.html","typ":"referenzwerk","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"NASA-Daten, überwiegend gemeinfrei; Zahlenwerte paraphrasiert.","abrufstatus":"vollständig abgerufen","kurzzitat":"Revolution period (days) 27.3217 ... Synodic period (days) 29.53","einsatz":["Mondzyklus","siderischer und synodischer Monat"],"grenzen":"Astronomische Daten; keine Aussage zu Monddeutung oder Verhalten."},{"id":"S19","titel":"Astrological sign","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Astrological_sign","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"twelve 30-degree sectors ... enumerate from the first day of spring ... shifted out of alignment ... by axial precession ... Astrology is a pseudoscience ... more plausible explanations ... seasonal birth","einsatz":["Zeichendefinition","Präzession","Evidenzlage","saisonale Alternativerklärung"],"grenzen":"Tertiärquelle; die saisonale Hypothese ist dort nur knapp referiert."},{"id":"S20","titel":"Pluto","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Pluto","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"Pluto ... is a dwarf planet in the Kuiper belt ... discovered February 18, 1930 ... orbital period 247.94 years","einsatz":["Pluto-Status","Entdeckung","Umlaufzeit"],"grenzen":"Tertiärquelle; Statusfrage wurde 2006 durch die IAU entschieden."},{"id":"S21","titel":"Barnum effect","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Barnum_effect","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"individuals give high accuracy ratings to descriptions of their personality that supposedly are tailored specifically to them, yet which are in fact vague and general enough to apply to a broad range of people","einsatz":["Barnum-/Forer-Effekt","subjektive Validierung"],"grenzen":"Tertiärquelle; Effekt ist in der Psychologie gut etabliert, hier nur als Erklärungsangebot genutzt."},{"id":"S22","titel":"Ascendant","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Ascendant","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"the value of the ecliptical geocentric longitude ... which is easterly on the horizon","einsatz":["Aszendent als geometrischer Schnittpunkt"],"grenzen":"Tertiärquelle; Definition ist geometrisch nachvollziehbar."},{"id":"S23","titel":"Midheaven","herausgeber":"Collins English Dictionary","url":"https://www.collinsdictionary.com/us/dictionary/english/midheaven","typ":"lexikon","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"Wörterbucheintrag, urheberrechtlich geschützt; nur Definitionsparaphrase mit Quellenangabe.","abrufstatus":"vollständig abgerufen","kurzzitat":"the point on the ecliptic, measured in degrees, that crosses the meridian of a particular place at a particular time","einsatz":["MC-Definition"],"grenzen":"Kurze Lexikondefinition; keine weitergehende Fachdiskussion."},{"id":"S24","titel":"Uranus","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Uranus","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"Uranus is the seventh planet from the Sun ... ice giant ... On 23 September 1846, Johann Gottfried Galle located a new planet, later named Neptune","einsatz":["Uranus als Ice Giant","Neptun-Entdeckung 1846"],"grenzen":"Tertiärquelle; Entdeckungsjahr Uranus nicht im abgerufenen Ausschnitt belegt und daher hier nicht behauptet."},{"id":"S25","titel":"Neptune","herausgeber":"Wikipedia (englischsprachige Ausgabe)","url":"https://en.wikipedia.org/wiki/Neptune","typ":"tertiaerquelle","abgerufen_am":"2026-11-01","sprache":"en","rechte_hinweis":"CC BY-SA 4.0. Faktenentnahme und kurze Zitate; kein Artikeltext übernommen.","abrufstatus":"vollständig abgerufen","kurzzitat":"Neptune is the eighth and farthest known planet orbiting the Sun ... unexpected changes in the orbit of Uranus led ... to hypothesise ... perturbation by an unknown planet","einsatz":["Neptun als äußerster Planet","Entdeckungszusammenhang"],"grenzen":"Tertiärquelle; Detailgeschichte der Entdeckung nicht vollständig eingesehen."}];

export const CLAIMS = [{"id":"c01","aussage":"Die Erdachse präzediert: Sie beschreibt mit rund 23,4 Grad Radius einen Kegel und braucht für einen vollen Umlauf etwa 26.000 Jahre; daraus folgt eine apparente Verschiebung von etwa 0,014 Grad pro Jahr.","evidenztyp":"astronomischer_fakt","quellen":["S01","S03"],"sicherheit":"hoch","hinweis":"Zahlen sind gerundet; aktuelle Epochenwerte unterscheiden sich leicht."},{"id":"c02","aussage":"Der tropische Tierkreis beginnt am Frühlings-Äquinoktium und teilt die Ekliptik in zwölf gleiche Sektoren von je 30 Grad; die Zeichen sind an Jahreszeiten, nicht an Sternbildgrenzen gebunden.","evidenztyp":"konvention","quellen":["S13","S19","S14"],"sicherheit":"hoch","hinweis":"Definition des tropischen Systems; andere Systeme definieren anders."},{"id":"c03","aussage":"Siderische Systeme korrigieren die Präzession über Ayanamsa-Werte und orientieren sich an der Sternposition; tropische und siderische Zeichen sind deshalb heute um einen schulabhängigen Betrag gegeneinander verschoben.","evidenztyp":"konvention","quellen":["S13"],"sicherheit":"hoch","hinweis":"Der konkrete Abstand hängt vom Ayanamsa ab und wird hier nicht als fixer Wert behauptet."},{"id":"c04","aussage":"Der Zodiak ist ein Gürtel von etwa 8 Grad nördlich und südlich der Ekliptik; er wird in zwölf Sektoren von je 30 Grad geteilt.","evidenztyp":"astronomischer_fakt","quellen":["S14","S06"],"sicherheit":"hoch","hinweis":"Die 8-Grad-Angabe beschreibt den Bereich, in dem Mond und Planeten überwiegend erscheinen."},{"id":"c05","aussage":"Entlang der Ekliptik liegen zwölf klassische Tierkreissternbilder plus Ophiuchus; die IAU kennt insgesamt 88 Sternbilder mit seit 1928/1930 festen Grenzen.","evidenztyp":"astronomischer_fakt","quellen":["S04","S05","S14"],"sicherheit":"hoch","hinweis":"Sternbilder sind ungleiche Areale; Zeichen sind gleiche Sektoren."},{"id":"c06","aussage":"Die in Publikationen genannten Datumsgrenzen der Sonnenzeichen sind Näherungen und unterscheiden sich je nach Jahr, Zeitzone und Quelle um etwa einen Tag.","evidenztyp":"konvention","quellen":["S06","S19"],"sicherheit":"hoch","hinweis":"Deshalb werden im Paket Zeiträume als ungefähre Orientierung und nicht als exakte Kalenderdaten ausgegeben."},{"id":"c07","aussage":"Ein Horoskop umfasst in der westlichen Tradition weit mehr als das Sonnenzeichen: unter anderem Mond, weitere Planeten, Häuser, Achsen und Aspekte; das Sonnenzeichen beschreibt nur die Sonnenposition im Zeichensektor.","evidenztyp":"deutungstradition","quellen":["S07","S10","S11","S19"],"sicherheit":"hoch","hinweis":"Die Aussage beschreibt den Aufbau der Tradition, nicht deren empirische Gültigkeit."},{"id":"c08","aussage":"Häuser sind zeit- und ortsabhängige Einteilungen des Horoskops; es gibt mehrere Systeme. Placidus ist im modernen Westen verbreitet und jenseits der Polarkreise nicht durchgehend definiert; Equal House teilt ab dem Aszendenten in 30-Grad-Schritten.","evidenztyp":"konvention","quellen":["S10","S16"],"sicherheit":"hoch","hinweis":"Kein System ist wissenschaftlich als richtig erwiesen; die Wahl ist eine Fachkonvention."},{"id":"c09","aussage":"Aszendent und MC sind geometrische Schnittpunkte: der Aszendent ist der östliche Schnittpunkt von Ekliptik und Horizont, der MC der Punkt der Ekliptik am oberen Meridian. Die Achsen AC/DC und MC/IC bleiben in den gängigen Häusersystemen gleich.","evidenztyp":"konvention","quellen":["S22","S23","S16","S10"],"sicherheit":"hoch","hinweis":"Die Deutung dieser Punkte ist Tradition; die geometrische Definition ist davon unabhängig."},{"id":"c10","aussage":"Die fünf Hauptaspekte sind Konjunktion (0 Grad), Sextil (60 Grad), Quadrat (90 Grad), Trigon (120 Grad) und Opposition (180 Grad).","evidenztyp":"konvention","quellen":["S11"],"sicherheit":"hoch","hinweis":"Winkel sind Definition; die Zuordnung zu leicht oder spannungsreich ist Deutungstradition."},{"id":"c11","aussage":"Orben sind keine festen Naturgrößen: Zulässige Abweichungen variieren nach Planet, Aspekt, Schule und Anwendungszweck; psychologische Astrologie nutzt eher weite, Horary eher enge Orben.","evidenztyp":"konvention","quellen":["S11","S17"],"sicherheit":"mittel","hinweis":"S17 ist nur als Suchsnippet abrufbar; die Aussage wird deshalb als Konvention mit Beispielwerten, nicht als Norm ausgegeben."},{"id":"c12","aussage":"Die traditionelle Herrschaftslehre ordnet die zwölf Zeichen den sieben mit bloßem Auge sichtbaren Himmelskörpern zu; moderne Systeme ergänzen Uranus, Neptun und Pluto für einzelne Zeichen.","evidenztyp":"konvention","quellen":["S12"],"sicherheit":"hoch","hinweis":"Zuordnungen sind historisch gewachsen und schulabhängig."},{"id":"c13","aussage":"Pluto wurde am 18. Februar 1930 entdeckt und ist seit der IAU-Entscheidung von 2006 ein Zwergplanet; in der modernen Astrologie wird er dennoch als Deutungsfaktor verwendet.","evidenztyp":"astronomischer_fakt","quellen":["S20","S02"],"sicherheit":"hoch","hinweis":"Astronomischer Status und astrologische Verwendung sind zwei verschiedene Fragen."},{"id":"c14","aussage":"Rückläufig erscheinende Planeten bewegen sich nicht tatsächlich rückwärts; die Umkehr ist eine Perspektivwirkung der unterschiedlichen Bahngeschwindigkeiten von Erde und beobachtetem Planeten.","evidenztyp":"astronomischer_fakt","quellen":["S15"],"sicherheit":"hoch","hinweis":"Die scheinbare Bewegung ist real beobachtbar, die Deutung als Ereignis ist Tradition."},{"id":"c15","aussage":"Der siderische Monat dauert 27,3217 Tage, der synodische Monat 29,53 Tage; daraus ergibt sich ein Wechsel des Mond-Zeichensektors im Mittel etwa alle 2,46 Tage.","evidenztyp":"astronomischer_fakt","quellen":["S18"],"sicherheit":"hoch","hinweis":"Der 2,46-Tage-Wert ist eine Rechnung aus 29,53 geteilt durch 12 und keine Ephemeridenangabe."},{"id":"c16","aussage":"Die mittleren siderischen Umlaufzeiten betragen rund 88 Tage (Merkur), 225 Tage (Venus), 687 Tage (Mars), 11,9 Jahre (Jupiter), 29,4 Jahre (Saturn), 83,7 Jahre (Uranus), 163,7 Jahre (Neptun) und 247,9 Jahre (Pluto).","evidenztyp":"astronomischer_fakt","quellen":["S02","S20"],"sicherheit":"hoch","hinweis":"Gerundete Mittelwerte; keine Aussage über aktuelle Positionen."},{"id":"c17","aussage":"Astrologie wird in der modernen Wissenschaft als Pseudoscience eingeordnet; es gibt keine belastbare Evidenz für einen Zusammenhang zwischen Geburtsdatum und Persönlichkeit oder Intelligenz.","evidenztyp":"empirischer_befund","quellen":["S06","S07","S09","S19"],"sicherheit":"hoch","hinweis":"Die Einordnung betrifft astrologische Wirkbehauptungen, nicht die kulturelle oder reflexive Nutzung von Symbolen."},{"id":"c18","aussage":"Der bekannteste doppelblinde Test an Radixdeutungen (Carlson 1985) ergab laut Sekundärliteratur keine bessere Trefferquote als Zufall.","evidenztyp":"empirischer_befund","quellen":["S08","S09"],"sicherheit":"hoch","hinweis":"Nur das Abstract von S08 war zugänglich; das Ergebnis wird über S09 berichtet."},{"id":"c19","aussage":"Für astrologische Wirkbehauptungen fehlt ein plausibler physikalischer oder biologischer Mechanismus, der nicht grundlegenden Erkenntnissen widersprechen würde.","evidenztyp":"empirischer_befund","quellen":["S09"],"sicherheit":"hoch","hinweis":"Negativbefund; er schließt eine bisher unbekannte Wirkung nicht logisch aus, macht sie aber unbegründet."},{"id":"c20","aussage":"Der Barnum- beziehungsweise Forer-Effekt erklärt, warum vage, allgemein zutreffende Persönlichkeitsbeschreibungen als ungewöhnlich treffend erlebt werden können.","evidenztyp":"empirischer_befund","quellen":["S21"],"sicherheit":"hoch","hinweis":"Psychologischer Effekt; er erklärt Zustimmung, nicht die Wahrheit der Aussage."},{"id":"c21","aussage":"Als alternative Erklärung für scheinbare Geburtsmonat-Persönlichkeitszusammenhänge werden unter anderem saisonale Effekte der Geburt diskutiert.","evidenztyp":"empirischer_befund","quellen":["S19"],"sicherheit":"mittel","hinweis":"Nur als Forschungsrichtung genannt, nicht als abschließend belegt."},{"id":"c22","aussage":"Astrologie ist historisch aus mesopotamischer Himmelsomen-Deutung entstanden, wurde in hellenistischer Zeit zu horoskopbasierter Astrologie weiterentwickelt und verbreitete sich nach Indien, in den islamischen Raum und nach Europa.","evidenztyp":"historisch","quellen":["S07"],"sicherheit":"hoch","hinweis":"Grobe Entwicklungslinie; regionale Traditionen sind vielfältiger als diese Summe."},{"id":"c23","aussage":"Astrologie wird als Form der Divination definiert, die Himmelskörperpositionen als Zeichen für irdische und menschliche Ereignisse deutet.","evidenztyp":"historisch","quellen":["S07"],"sicherheit":"hoch","hinweis":"Definitionsaussage einer Enzyklopädie, keine Wirksamkeitsbehauptung."},{"id":"c24","aussage":"Uranus und Neptun gehören nicht zu den klassischen sieben sichtbaren Himmelskörpern; Neptun wurde 1846 anhand von Bahnstörungen aufgefunden.","evidenztyp":"astronomischer_fakt","quellen":["S24","S25","S12"],"sicherheit":"hoch","hinweis":"Entdeckungsgeschichte Neptuns; das Entdeckungsjahr von Uranus wird hier nicht behauptet, weil es im abgerufenen Ausschnitt nicht belegt war."},{"id":"c25","aussage":"Die Ekliptik ist die scheinbare jährliche Bahn der Sonne am Himmel; die geozentrische Perspektive ist für die Astrologie konstitutiv, auch wenn die Planeten tatsächlich die Sonne umlaufen.","evidenztyp":"astronomischer_fakt","quellen":["S14","S05","S15"],"sicherheit":"hoch","hinweis":"Geozentrisch meint hier den Beobachtungsstandpunkt, nicht ein Weltbild."},{"id":"c26","aussage":"Häuserherrschaft wird in der Tradition über das Zeichen auf der Hausspitze bestimmt; ein Planet in seinem Domizil gilt als besonders stark.","evidenztyp":"deutungstradition","quellen":["S10","S12"],"sicherheit":"hoch","hinweis":"Deutungsregel, keine messbare Eigenschaft."},{"id":"c27","aussage":"Sonne und Mond werden in der Astrologie als Leuchtkörper den acht weiteren Deutungsfaktoren vorangestellt; die Zahl zehn ergibt sich aus zwei Leuchtkörpern plus acht Planeten beziehungsweise Pluto.","evidenztyp":"konvention","quellen":["S12","S20"],"sicherheit":"hoch","hinweis":"Die Erde ist kein astrologischer Deutungsfaktor; Pluto wird trotz Zwergplanetenstatus mitgezählt."},{"id":"c28","aussage":"Eine echte Radix- oder Transitberechnung erfordert belastbare Ephemeriden, korrekte Zeitzonen- und Ortsdaten sowie eine dokumentierte Häuserkonvention; Zufallswerte oder geschätzte Positionen wären keine Berechnung.","evidenztyp":"konvention","quellen":["S10","S22","S23"],"sicherheit":"hoch","hinweis":"Technische Anforderung für einen späteren, separaten Rechenschritt."}];
